/**********************************************************************************
Criar stored procedure [dbo].[Config]
**********************************************************************************/
IF(SELECT object_id('[dbo].[Config]', 'P')) IS NULL
	EXEC('CREATE PROCEDURE [dbo].[Config] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[Config](@SystemName VARCHAR(25)
							  ,@DatabaseName VARCHAR(25) = NULL
							  ,@TableName VARCHAR(25) = NULL
							  ,@ReturnValue BIT OUT) AS
BEGIN
	SET NOCOUNT ON
	SET TRANSACTION ISOLATION LEVEL READ COMMITTED
	DECLARE @ErrorMessage VARCHAR(MAX)

	SET @ReturnValue = 1
		IF @SystemName IS NULL
			THROW 51000, 'Nome de sistema é requerido.', 1
		-- 0 [Systems]
		SELECT 	'System' AS [Kind]
				,[Id]
				,[Name]
				,[Description]
				,[ClientName]
				,[MaxRetryLogins]
				,[IsOffAir]
			INTO [#Systems]
			FROM [dbo].[Systems]
			WHERE [Name] = @SystemName
		IF @@ROWCOUNT = 0 BEGIN
			SET @ErrorMessage = 'Sistema "' + @SystemName + '" não cadastrado.';
			THROW 51000, @ErrorMessage, 1
		END
		IF (SELECT IsOffAir FROM [#Systems]) = 1 BEGIN
			SET @ErrorMessage = 'Sistema "' + @SystemName + '" fora do ar.';
			THROW 51000, @ErrorMessage, 1
		END
		ALTER TABLE [#Systems] DROP COLUMN [IsOffAir]
		IF @DatabaseName IS NULL
			RETURN 0
		ALTER TABLE [#Systems] ADD PRIMARY KEY CLUSTERED([Id])
		IF @DatabaseName = 'all' BEGIN
			SET @DatabaseName = NULL
			SET @TableName = NULL
		END

		-- 1 [Databases]
		SELECT 	'Database' AS [Kind]
				,[D].[Id]
				,[D].[ConnectionId]
				,[D].[Name]
				,[D].[Alias]
				,[D].[Description]
				,[D].[Folder]
			INTO [#Databases]
			FROM [dbo].[Databases] [D]
				INNER JOIN [dbo].[SystemsDatabases] [SD] ON [SD].[DatabaseId] = [D].[id]
				INNER JOIN [#Systems] [S] ON [S].[Id] = [SD].[SystemId]
			WHERE @DatabaseName IS NULL OR [D].[Name] = @DatabaseName
		IF @@ROWCOUNT = 0
			THROW 51000, 'Banco(s)-de-dados não cadastrado(s).', 1
		ALTER TABLE [#Databases] ADD PRIMARY KEY CLUSTERED([Id])
		IF @DatabaseName IS NULL BEGIN
			ALTER TABLE [#Databases] DROP COLUMN [Folder]
		END

		-- 2 [Connections]
		SELECT 'Connection' AS [Kind]
			  ,[Id]
			  ,[Environment]
			  ,[ConnectionString]

			INTO [#Connections]
			FROM [dbo].[Connections] [C]
			WHERE [C].[Id] IN (SELECT [ConnectionId] FROM [#Databases])
		IF @@ROWCOUNT = 0
			THROW 51000, 'Banco(s)-de-dados não cadastrado(s).', 1
		ALTER TABLE [#Connections] ADD PRIMARY KEY CLUSTERED([Id])

		-- 3 [Tables]
		SELECT	'Table' AS [Kind]
				,[T].[Id]
				,[DT].[DatabaseId]
				,[T].[Name]
				,[T].[Alias]
				,[T].[Description]
				,[T].[ParentTableId]
				,[T].[IsLegacy]
			INTO [#Tables]
			FROM [dbo].[Tables] [T]
				INNER JOIN [dbo].[DatabasesTables] [DT] ON [DT].[TableId] = [T].[Id]
				INNER JOIN [#Databases] [D] ON [D].[Id] = [DT].[DatabaseId]
			WHERE @TableName IS NULL OR [T].[Name] = @TableName
		IF @@ROWCOUNT = 0
			THROW 51000, 'Tabela(s) não cadastrada(s).', 1
		ALTER TABLE [#Tables] ADD PRIMARY KEY CLUSTERED([Id])

		IF @DatabaseName IS NULL BEGIN
			-- 4 [Columns]
			SELECT	'Column' AS [Kind]
					,[C].[Id]
					,[C].[TableId]
					,[C].[Sequence]
					,[C].[DomainId]
					,[C].[ReferenceTableId]
					,[C].[Name]
					,[C].[Alias]
					,[C].[Description]
					,[C].[Title]
					,[C].[Caption]
				    ,[C].[Default]
				    ,[C].[Minimum]
				    ,[C].[Maximum]
					,[C].[IsPrimarykey]
					,[C].[IsAutoIncrement]
					,[C].[IsRequired]
					,[C].[IsListable]
					,[C].[IsFilterable]
					,[C].[IsEditable]
					,[C].[IsGridable]			
					,[C].[IsEncrypted]
					,[C].[IsInWords]
				INTO [#Columns]
				FROM [dbo].[Columns] [C]
					INNER JOIN [#Tables] [T] ON [T].[Id]= [C].[TableId] 
			IF @@ROWCOUNT = 0
				THROW 51000, 'Colunas de tabelas não cadastradas.', 1
			ALTER TABLE [#Columns] ADD PRIMARY KEY CLUSTERED([Id])
			CREATE INDEX [#ColumnsDomainId] ON [#Columns]([DomainId])

			-- 5 [Domains]
			SELECT	'Domain' AS [Kind]
					,[D].[Id]
					,[D].[TypeId]
					,[D].[MaskId]
					,[D].[Name]
					,[D].[Length]
					,[D].[Decimals]
					,[D].[ValidValues]
					,[D].[Default]
					,[D].[Minimum]
					,[D].[Maximum]
					,[D].[Codification]
				INTO [#Domains]
				FROM [dbo].[Domains] [D]
				WHERE EXISTS(SELECT TOP 1 1 FROM [#Columns] WHERE [DomainId] = [D].[Id])
			IF @@ROWCOUNT = 0
				THROW 51000, 'Domínios de colunas não cadastrados.', 1
			ALTER TABLE [#Domains] ADD PRIMARY KEY NONCLUSTERED([Id])
			CREATE INDEX [#DomainsTypeId] ON [#Domains]([TypeId])

			-- 6 [Types]
			SELECT 	'Type' AS [Kind]
					,[T].[Id]
					,[T].[CategoryId]
					,[T].[Name]
					,[T].[MaxLength]
				    ,[T].[Minimum]
					,[T].[Maximum]
					,[T].[AskLength]
					,[T].[AskDecimals]
					,[T].[AskPrimarykey]
					,[T].[AskAutoincrement]
					,[T].[AskFilterable]
					,[T].[AskGridable]
					,[T].[AskCodification]
					,[T].[IsActive]
				INTO [#Types]
				FROM [dbo].[Types] [T]
				WHERE EXISTS(SELECT TOP 1 1 FROM [#Domains] WHERE [TypeId] = [T].[Id])
			IF @@ROWCOUNT = 0
				THROW 51000, 'Tipos de domínios não cadastrados.', 1
			CREATE INDEX [#TypesCategoryId] ON [#Types]([CategoryId])

			-- 7 [Categories]
			SELECT 	'Category' AS [Kind]
					,[C].[Id]
					,[C].[Name]
					,[C].[HtmlInputType]
					,[C].[HtmlInputAlign]
					,[C].[AskEncrypted]
					,[C].[AskMask]
					,[C].[AskListable]
					,[C].[AskDefault]
					,[C].[AskMinimum]
					,[C].[AskMaximum]
					,[C].[AskInWords]
				INTO [#Categories]
				FROM [dbo].[Categories] [C]
				WHERE EXISTS(SELECT TOP 1 1 FROM [#Types] WHERE [CategoryId] = [C].[Id])
			IF @@ROWCOUNT = 0
			   THROW 51000, 'Categoria(s) de tipos não cadastrada(s).', 1

			-- 8 [Menus]
			SELECT 	'Menu' AS [Kind]
					,[M].[Id]
					,[M].[SystemId]
					,[M].[Sequence]
					,[M].[Caption]
					,[M].[Message]
					,[M].[Action]
					,[M].[ParentMenuId]
				INTO [#Menus]
				FROM [dbo].[Menus] [M]
					INNER JOIN [#Systems] [S] ON [S].[Id] = [M].[SystemId]
			IF @@ROWCOUNT = 0
			   THROW 51000, 'Menu(s) de sistema não cadastrado(s).', 1

			-- 9 [Indexes]
			SELECT 	'Index' AS [Kind]
					,[I].[Id]
					,[I].[TableId]
					,[I].[Name]
					,[I].[IsUnique]
				INTO [#Indexes]
				FROM [dbo].[Indexes] [I]
					INNER JOIN [#Tables] [T] ON [T].[Id] = [I].[TableId]
			ALTER TABLE [#Indexes] ADD PRIMARY KEY NONCLUSTERED([Id])

			-- 10 [Indexkeys]
			SELECT 	'Indexkey' AS [Kind]
					,[IK].[Id]
					,[IK].[IndexId]
					,[IK].[Sequence]
					,[IK].[ColumnId]
					,[IK].[IsDescending]
				INTO [#Indexkeys]
				FROM [dbo].[Indexkeys] [IK]
					INNER JOIN [#Indexes] [I] ON [I].[Id] = [IK].IndexId
			
			-- 11 [Masks]
			SELECT 	'Mask' AS [Kind]
					,[M].[Id]
					,[M].[Name]
					,[M].[Mask]
				INTO [#Masks]
				FROM [dbo].[Masks] [M]
				WHERE EXISTS(SELECT TOP 1 1 FROM [#Domains] WHERE [MaskId] = [M].[Id])
			
			-- 12 [Unicities]
			SELECT 'Unicity' AS [Kind]
					,[U].[Id]
					,[U].[ColumnId1]
					,[U].[ColumnId2]
					,[U].[IsBidirectional]
				INTO [#Unicities]
				FROM [dbo].[Unicities] [U]
				WHERE EXISTS(SELECT 1 FROM [dbo].[#Columns] WHERE [Id] IN ([U].[ColumnId1], [U].[ColumnId2]))
		END

		-- Results
		SELECT * FROM [#Systems] ORDER BY [Name] -- 0 [#Systems]
		IF @DatabaseName IS NULL BEGIN
			SELECT * FROM [#Databases] ORDER BY [Name] -- 1 [#Databases]
			SELECT * FROM [#Tables] ORDER BY [DatabaseId], [Name] -- 2 [#Tables]
			SELECT * FROM [#Columns] ORDER BY [TableId], [Sequence] -- 3 [#Columns]
			SELECT * FROM [#Domains] ORDER BY [Name] -- 4 [#Domains]
			SELECT * FROM [#Types] ORDER BY [Name] -- 5 [#Types]
			SELECT * FROM [#Categories] ORDER BY [Name] -- 6 [#Categories]
			SELECT * FROM [#Menus] ORDER BY [SystemId], [Sequence] -- 7 [#Menus]
			SELECT * FROM [#Indexes] ORDER BY [Name] -- 8 [#Indexes]
			SELECT * FROM [#Indexkeys] ORDER BY [IndexId], [Sequence] -- 9 [#Indexkeys]
			SELECT * FROM [#Masks] ORDER BY [Id] -- 10 [#Masks]
			SELECT * FROM [#Unicities] ORDER BY [Id] -- 11 [#Unicities]
		END ELSE BEGIN
			SELECT * FROM [#Connections] ORDER BY [Id] -- 1 [#Connections]]
			SELECT * FROM [#Databases] ORDER BY [Name] -- 2 [#Databases]
			SELECT * FROM [#Tables] ORDER BY [DatabaseId], [Name] -- 3 [#Tables]
		END
END
GO
/**********************************************************************************
Criar stored procedure [dbo].[NewId]
**********************************************************************************/
IF(SELECT object_id('[dbo].[NewId]','P')) IS NULL
	EXEC('CREATE PROCEDURE [dbo].[NewId] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[NewId](@SystemName VARCHAR(25)
							 ,@DatabaseName VARCHAR(25)
							 ,@TableName VARCHAR(25)
							 ,@ReturnValue BIGINT OUT) AS BEGIN
	SET NOCOUNT ON
	SET TRANSACTION ISOLATION LEVEL SERIALIZABLE

	DECLARE @SystemId BIGINT
			,@DatabaseId BIGINT
			,@TableId BIGINT
			,@NextId BIGINT

	SELECT @SystemId = [Id]
		FROM [dbo].[Systems]
		WHERE [Name] = @SystemName
	IF @SystemId IS NULL
		THROW 51000, 'Sistema não encontrado', 1
	SELECT @DatabaseId = [Id]
		FROM [dbo].[Databases]
		WHERE [Name] = @DatabaseName
	IF @DatabaseId IS NULL
		THROW 51000, 'Banco-de-dados não encontrado', 1
	IF NOT EXISTS(SELECT 1
					FROM [dbo].[SystemsDatabases]
					WHERE [SystemId] = @SystemId
						  AND [DatabaseId] = @DatabaseId)
		THROW 51000, 'Banco-de-dados não pertence ao sistema especificado', 1

	SELECT @TableId = [Id]
		   ,@NextId = ISNULL([CurrentId], 0) + 1
		FROM [dbo].[Tables] WITH (UPDLOCK, HOLDLOCK)
		WHERE [Name] = @TableName
	IF @TableId IS NULL
		THROW 51000, 'Tabela não encontrada', 1
	IF NOT EXISTS(SELECT 1
					FROM [dbo].[DatabasesTables]
					WHERE [DatabaseId] = @DatabaseId
						  AND [TableId] = @TableId)
		THROW 51000, 'Tabela não pertence ao banco-de-dados especificado', 1
	UPDATE [dbo].[Tables]
		SET [CurrentId] = @NextId
		WHERE [Id] = @TableId
	SET @ReturnValue = @NextId
	RETURN 0
END
GO
/**********************************************************************************
Criar stored procedure [dbo].[NewOperationId]
**********************************************************************************/
IF(SELECT object_id('[dbo].[NewOperationId]','P')) IS NULL
	EXEC('CREATE PROCEDURE [dbo].[NewOperationId] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[NewOperationId](@SystemName VARCHAR(25)
									  ,@DatabaseName VARCHAR(25)
									  ,@ReturnValue BIGINT OUT) AS BEGIN
	SET NOCOUNT ON
	SET TRANSACTION ISOLATION LEVEL READ COMMITTED

	DECLARE @SystemId BIGINT
			,@DatabaseId BIGINT
			,@NexOperationtId BIGINT

	SELECT @SystemId = [Id]
		FROM [dbo].[Systems]
		WHERE [Name] = @SystemName
	IF @SystemId IS NULL
		THROW 51000, 'Sistema não encontrado', 1
	SELECT @DatabaseId = [Id]
			,@NexOperationtId = ISNULL([CurrentOperationId], 0) + 1
		FROM [dbo].[Databases]
		WHERE [Name] = @DatabaseName
	IF @DatabaseId IS NULL
		THROW 51000, 'Banco-de-dados não encontrado', 1
	IF NOT EXISTS(SELECT 1
					FROM [dbo].[SystemsDatabases]
					WHERE [SystemId] = @SystemId
						  AND [DatabaseId] = @DatabaseId)
		THROW 51000, 'Banco-de-dados não pertence ao sistema especificado', 1
	UPDATE [dbo].[Databases] 
		SET [CurrentOperationId] = @NexOperationtId
		WHERE [Id] = @DatabaseId
	SET @ReturnValue = @NexOperationtId

	RETURN 0
END
GO
/**********************************************************************************
Criar stored procedure [dbo].[Login]
**********************************************************************************/
IF(SELECT object_id('[dbo].[Login]', 'P')) IS NULL
	EXEC('CREATE PROCEDURE [dbo].[Login] AS PRINT 1')
GO

ALTER PROCEDURE [dbo].[Login](@Parameters VARCHAR(MAX)
							 ,@ReturnValue BIGINT OUT) AS BEGIN
	DECLARE @ErrorMessage NVARCHAR(MAX)

	SET NOCOUNT ON
	SET TRANSACTION ISOLATION LEVEL READ COMMITTED
		IF ISJSON(@Parameters) = 0
			THROW 51000, 'Parâmetro login não está no formato JSON', 1

		DECLARE @Action VARCHAR(15) = CAST(JSON_VALUE(@Parameters, '$.Action') AS VARCHAR(15))
				,@LoginId BIGINT = CAST(JSON_VALUE(@Parameters, '$.LoginId') AS BIGINT)
				,@SystemName VARCHAR(25) = CAST(JSON_VALUE(@Parameters, '$.SystemName') AS VARCHAR(25))
				,@UserName VARCHAR(25) = CAST(JSON_VALUE(@Parameters, '$.UserName') AS VARCHAR(25))
				,@Password VARCHAR(256) = CAST(JSON_VALUE(@Parameters, '$.Password') AS VARCHAR(256))
				,@PublicKey VARCHAR(256) = CAST(JSON_VALUE(@Parameters, '$.PublicKey') AS VARCHAR(256))
				,@PasswordAux VARCHAR(256)
				,@SystemId BIGINT
				,@SystemIdAux BIGINT
				,@UserId BIGINT
				,@UserIdAux BIGINT
				,@MaxRetryLogins TINYINT
				,@RetryLogins TINYINT
				,@IsLogged BIT
				,@IsActive BIT
				,@IsOffAir BIT
	
		IF @Action IS NULL
			THROW 51000, 'Ação de login é requerida', 1
		IF @Action NOT IN ('login','logout','authenticate','change')
			THROW 51000, 'Ação de login é inválida', 1
		IF @SystemName IS NULL
			THROW 51000, 'Sistema é requerido', 1
		SELECT @SystemId = [Id]
			   ,@MaxRetryLogins = [MaxRetryLogins]
			   ,@IsOffAir = [IsOffAir]
			FROM [dbo].[Systems]
			WHERE [Name] = @SystemName
		IF @SystemId IS NULL
			THROW 51000, 'Sistema não cadastrado', 1
		IF @IsOffAir = 1
			THROW 51000, 'Sistema fora do ar', 1
		IF @UserName IS NULL
			THROW 51000, 'Usuário é requerido', 1
		SELECT	@UserId = [Id]
				,@RetryLogins = [RetryLogins]
				,@IsActive = [IsActive]
				,@PasswordAux = [Password]
			FROM [dbo].[Users]
			WHERE [Name] = @UserName
		IF @UserId IS NULL
			THROW 51000, 'Usuário não cadastrado', 1
		IF @IsActive = 0
			THROW 51000, 'Usuário está inativo', 1
		IF @RetryLogins >= @MaxRetryLogins
			THROW 51000, 'Usuário está bloqueado', 1
		IF NOT EXISTS(SELECT TOP 1 1
						FROM [dbo].[SystemsUsers]
						WHERE [SystemId] = @SystemId
							  AND [UserId] =  @UserId)
			THROW 51000, 'Usuário não autorizado', 1
		IF @Password IS NULL
			THROW 51000, 'Senha é requerida', 1
		IF CAST(@PasswordAux AS VARCHAR(MAX)) <> CAST(@Password AS VARCHAR(MAX)) BEGIN
			SET @RetryLogins = @RetryLogins + 1
			UPDATE [dbo].[Users] 
				SET [RetryLogins] = @RetryLogins
				WHERE [Id] = @UserId
			IF @RetryLogins = @MaxRetryLogins
				THROW 51000, 'Usuário está bloqueado', 1
			ELSE BEGIN
				SET @ErrorMessage = 'Senha é inválida (' + CAST(@MaxRetryLogins -  @RetryLogins AS VARCHAR(3)) + ' tentativas restantes)';
				THROW 51000, @ErrorMessage, 1
			END
		END
		IF @action = 'login' OR @action = 'change' BEGIN
			IF @action = 'change' BEGIN
				DECLARE @NewPassword VARCHAR(256) = CAST(JSON_VALUE(@Parameters, '$.NewPassword') AS VARCHAR(256))
						,@RetypedPassword VARCHAR(256) = CAST(JSON_VALUE(@Parameters, '$.RetypedPassword') AS VARCHAR(256))

				IF @NewPassword IS NULL
					THROW 51000, 'Nova senha é requerida', 1
				IF @NewPassword = @Password
					THROW 51000, 'Nova senha deve ser diferente da anterior', 1
				IF @RetypedPassword IS NULL
					THROW 51000, 'Senha redigitada é requerida', 1
				IF @NewPassword <> @RetypedPassword
					THROW 51000, 'Senha redigitada não confere com a nova senha', 1
				UPDATE [dbo].[Users] 
					SET [Password] = @NewPassword
					WHERE [Id] = @UserId
			END
			EXEC [dbo].[NewId] 'crudex', 'crudex', 'Sessions', @LoginId OUT
			INSERT [dbo].[Sessions]([Id],
								  [SystemId],
								  [UserId],
								  [PublicKey],
								  [IsLogged],
								  [CreatedAt],
								  [CreatedBy])
						  VALUES (ISNULL(@LoginId, 1),
								  @SystemId,
								  @UserId,
								  @PublicKey,
								  1,
								  GETDATE(),
								  @UserName)
			UPDATE [dbo].[Users]
				SET [RetryLogins] = 0
				WHERE [Id] = @UserId
					  AND [RetryLogins] > 0
			SET @ReturnValue = @LoginId
		END ELSE IF @LoginId IS NULL
			THROW 51000, 'Id de login é requerido', 1
		ELSE BEGIN
			SELECT @SystemIdAux = [SystemId],
				   @UserIdAux = [UserId],
				   @IsLogged = [IsLogged]
				FROM [dbo].[Sessions]
				WHERE [Id] = @LoginId
			IF @SystemIdAux IS NULL
				THROW 51000, 'Login não cadastrado', 1
			IF @SystemId <> @SystemIdAux
				THROW 51000, 'Sistema é inválido para este login', 1
			IF @UserId <> @UserIdAux
				THROW 51000, 'Usuário é inválido para este login', 1
			IF @IsLogged = 0
				THROW 51000, 'Login já encerrado', 1
			IF @action = 'logout'
				UPDATE [dbo].[Sessions]
					SET [IsLogged] = 0,
						[UpdatedAt] = GETDATE(),
						[UpdatedBy] = @UserName
					WHERE [Id] = @LoginId
		END

	RETURN 1
END
GO
/**********************************************************************************
Criar stored procedure [dbo].[GetPublicKey]
**********************************************************************************/
IF(SELECT object_id('[dbo].[GetPublicKey]', 'P')) IS NULL
	EXEC('CREATE PROCEDURE [dbo].[GetPublicKey] AS PRINT 1')
GO
ALTER PROCEDURE[dbo].[GetPublicKey](@LoginId BIGINT
								   ,@ReturnValue BIGINT OUT) AS BEGIN
	SET NOCOUNT ON
	SET TRANSACTION ISOLATION LEVEL READ COMMITTED

	IF @LoginId IS NULL
		THROW 51000, 'Parâmetro @LoginId é requerido', 1
	SELECT [PublicKey]
		FROM [dbo].[Sessions]
		WHERE [Id] = @LoginId
	IF @@ROWCOUNT = 0
		THROW 51000, 'Valor @LoginId é inexistente', 1
	SET @ReturnValue = @LoginId

	RETURN @ReturnValue
END
GO
/**********************************************************************************
Criar stored procedure [dbo].[ScriptSystem]
**********************************************************************************/
IF (SELECT object_id('[dbo].[ScriptSystem]', 'P')) IS NULL
	EXEC('CREATE PROCEDURE [dbo].[ScriptSystem] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[ScriptSystem](@ReturnValue BIGINT OUT) AS
BEGIN
	SET NOCOUNT ON
	SET TRANSACTION ISOLATION LEVEL READ COMMITTED
	-- 1 [Systems]
		SELECT 	'System' AS [Kind]
				,[Id]
				,[Name]
				,[Description]
				,[ClientName]
				,[MaxRetryLogins]
				,[IsOffAir]
			INTO [#Systems]
			FROM [dbo].[Systems]
		IF @@ROWCOUNT = 0
			THROW 51000, 'Sistema não cadastrado', 1
		ALTER TABLE [#Systems] ADD PRIMARY KEY CLUSTERED([Id])
		-- 2 [[SystemsDatabases]]
		SELECT 	'SystemDatabase' AS [Kind]
				,[SD].[Id]
				,[SD].[SystemId]
				,[S].[Name] AS [#SystemName]
				,[SD].[DatabaseId]
				,[D].[Name] AS [#DatabaseName]
				,[D].[ConnectionId] AS [#ConnectionId]
				,[SD].[Name]
			INTO [#SystemsDatabases]
			FROM [dbo].[SystemsDatabases] [SD]
				INNER JOIN [#Systems] [S] ON [S].[Id] = [SD].[SystemId]
				INNER JOIN [dbo].[Databases] [D] ON [D].[Id] = [SD].[DatabaseId]
		IF @@ROWCOUNT = 0
			THROW 51000, 'Sistemas x Bancos-de-dados não cadastrado(s)', 1
		ALTER TABLE [#SystemsDatabases] ADD PRIMARY KEY CLUSTERED([Id])
		-- 3 [Connections]
		SELECT [Id]
			  ,[Environment]
			  ,[ConnectionString]
		  INTO [#Connections]
		  FROM [dbo].[Connections]
		-- 4 [Databases]
		SELECT 	'Database' AS [Kind]
				,[D].[Id]
				,[D].[ConnectionId]
				,[D].[Name]
				,[D].[Alias]
				,[D].[Description]
				,[D].[Folder]
				,[D].[IsLegacy]
				,[D].[CurrentOperationId]
			INTO [#Databases]
			FROM [dbo].[Databases] [D]
				INNER JOIN [#SystemsDatabases] [SD] ON [SD].[DatabaseId] = [D].[Id]
		IF @@ROWCOUNT = 0
			THROW 51000, 'Banco(s)-de-dados não cadastrado(s)', 1
		ALTER TABLE [#Databases] ADD PRIMARY KEY CLUSTERED([Id])
		-- 5 [DatabasesTables]
		SELECT 'DatabaseTable' AS [Kind]
			  ,[DT].[Id]
			  ,[DT].[DatabaseId]
			  ,[D].[Name] AS [#DatabaseName]
			  ,[D].[ConnectionId] AS [#ConnectionId]
			  ,[DT].[TableId]
			  ,[T].[Name] AS [#TableName]
			  ,[DT].[Name]
			INTO [#DatabasesTables]
			FROM [dbo].[DatabasesTables] [DT]
				INNER JOIN [#Databases] [D] ON [D].[Id] = [DT].[DatabaseId]
				INNER JOIN [dbo].[Tables] [T] ON [T].[Id] = [DT].[TableId]
		ALTER TABLE [#DatabasesTables] ADD PRIMARY KEY CLUSTERED([Id])
		-- 6 [Tables]
		SELECT	'Table' AS [Kind]
				,[T].[Id]
				,[T].[Name]
				,[T].[Alias]
				,[T].[Description]
				,[T].[ParentTableId]
				,[PT].[Name] AS [#ParentTableName]
				,[T].[IsLegacy]
				,[T].[CurrentId]
			INTO [#Tables]
			FROM [dbo].[Tables] [T]
				INNER JOIN [#DatabasesTables] [DT] ON [DT].[TableId] = [T].[Id]
				LEFT JOIN [dbo].[Tables] [PT] ON [PT].[Id] = [T].[ParentTableId]
		IF @@ROWCOUNT = 0
			THROW 51000, 'Tabela(s) não cadastrada(s)', 1
		ALTER TABLE [#Tables] ADD PRIMARY KEY CLUSTERED([Id])
		-- 7 [Categories]
		SELECT 	'Category' AS [Kind]
				,[C].[Id]
				,[C].[Name]
				,[C].[HtmlInputType]
				,[C].[HtmlInputAlign]
				,[C].[AskEncrypted]
				,[C].[AskMask]
				,[C].[AskListable]
				,[C].[AskDefault]
				,[C].[AskMinimum]
				,[C].[AskMaximum]
				,[C].[AskInWords]
			INTO [#Categories]
			FROM [dbo].[Categories] [C]
		IF @@ROWCOUNT = 0
			THROW 51000, 'Categoria(s) de tipos não cadastrada(s)', 1
		ALTER TABLE [#Categories] ADD PRIMARY KEY CLUSTERED([Id])
		-- 8 [Types]
		SELECT 	'Type' AS [Kind]
				,[T].[Id]
				,[T].[CategoryId]
				,[C].[Name] AS [#CategoryName]
				,[T].[Name]
				,[T].[Name] AS [#DataType]
				,[T].[MaxLength]
				,[T].[Minimum]
				,[T].[Maximum]
				,[T].[AskLength]
				,[T].[AskDecimals]
				,[T].[AskPrimarykey]
				,[T].[AskAutoincrement]
				,[T].[AskFilterable]
				,[T].[AskGridable]
				,[T].[AskCodification]
				,[T].[IsActive]
			INTO [#Types]
			FROM [dbo].[Types] [T]
				INNER JOIN [#Categories] [C] ON [C].[Id] = [T].[CategoryId]
		IF @@ROWCOUNT = 0
			THROW 51000, 'Tipos de domínios não cadastrados', 1
		ALTER TABLE [#Types] ADD PRIMARY KEY CLUSTERED([Id])
		-- 9 [Masks]
		SELECT 	'Mask' AS [Kind]
				,[M].[Id]
				,[M].[Name]
				,[M].[Mask]
			INTO [#Masks]
			FROM [dbo].[Masks] [M]
		-- 10 [Domains]
		SELECT	'Domain' AS [Kind]
				,[D].[Id]
				,[D].[TypeId]
				,[T].[Name] AS [#TypeName]
				,[C].[Name] AS [#CategoryName]
				,[T].[Name] + CASE WHEN ISNULL([D].[Length], 0) > 0 
								   THEN '(' + CAST([D].[Length] AS VARCHAR(10)) + 
										CASE WHEN ISNULL([D].[Decimals], 0) > 0 
											 THEN CAST([D].[Decimals] AS VARCHAR(10)) 
											 ELSE '' 
										END + ')'
								   ELSE ''
							  END AS [#DataType]
				,[D].[MaskId]
				,[M].[Name] AS [#MaskName]
				,[D].[Name]
				,[D].[Length]
				,[D].[Decimals]
				,[D].[ValidValues]
				,[D].[Default]
				,[D].[Minimum]
				,[D].[Maximum]
				,[D].[Codification]
			INTO [#Domains]
			FROM [dbo].[Domains] [D]
				INNER JOIN [#Types] [T] ON [T].[Id] = [D].[TypeId]
				INNER JOIN [#Categories] [C] ON [C].[Id] = [T].[CategoryId]
				LEFT JOIN [dbo].[Masks] [M] ON [M].[Id] = [D].[MaskId]
		IF @@ROWCOUNT = 0
			THROW 51000, 'Domínios de colunas não cadastrados', 1
		ALTER TABLE [#Domains] ADD PRIMARY KEY CLUSTERED([Id])
		-- 11 [Menus]
		SELECT 	'Menu' AS [Kind]
				,[M].[Id]
				,[M].[SystemId]
				,[S].[Name] AS [#SystemName]
				,[M].[Sequence]
				,[M].[Caption]
				,[M].[Message]
				,[M].[Action]
				,[M].[ParentMenuId]
				,[PM].[Caption] AS [#ParentMenuCaption]
			INTO [#Menus]
			FROM [dbo].[Menus] [M]
				LEFT JOIN [dbo].[Menus] [PM] ON [PM].[Id] = [M].[ParentMenuId]
				INNER JOIN [#Systems] [S] ON [S].[Id] = [M].[SystemId]
		IF @@ROWCOUNT = 0
			THROW 51000, 'Menu(s) de sistema não cadastrado(s)', 1
		ALTER TABLE [#Menus] ADD PRIMARY KEY CLUSTERED([Id])
		-- 12 [SystemsUsers]
		SELECT 'SystemUser' AS [Kind] 
			  ,[SU].[Id]
			  ,[SU].[SystemId]
			  ,[S].[Name] AS [#SystemName]
			  ,[SU].[UserId]
			  ,[U].[Name] AS [#UserName]
			  ,[SU].[Name]
			INTO [#SystemsUsers] 
			FROM [dbo].[SystemsUsers] [SU]
				INNER JOIN [#Systems] [S] ON [S].[Id] = [SU].[SystemId]
				INNER JOIN [dbo].[Users] [U] ON [U].[Id] = [SU].[UserId]
		IF @@ROWCOUNT = 0
			THROW 51000, 'Menu(s) de sistema não cadastrado(s)', 1
		ALTER TABLE [#SystemsUsers] ADD PRIMARY KEY NONCLUSTERED([Id])
		-- 13 [Users]
		SELECT 'User' AS [Kind] 
			  ,[U].[Id]
			  ,[U].[Name]
			  ,[U].[Password]
			  ,[U].[FullName]
			  ,[U].[RetryLogins]
			  ,[U].[IsActive]
			INTO [#Users]
			FROM [dbo].[Users] [U]
				INNER JOIN [#SystemsUsers] [SU] ON [SU].[UserId] = [U].[Id]
		ALTER TABLE [#Users] ADD PRIMARY KEY CLUSTERED([Id])
		-- 14 [Columns]
		SELECT 'Column' AS [Kind]
			  ,[C].[Id]
			  ,[C].[TableId]
			  ,[T].[Name] AS [#TableName]
			  ,[T].[Alias] AS [#TableAlias]
			  ,[C].[Sequence]
			  ,[C].[DomainId]
			  ,[D].[Name] AS [#DomainName]
			  ,[D].[#CategoryName]
			  ,[D].[#TypeName]
			  ,[D].[#DataType]
			  ,[C].[ReferenceTableId]
			  ,[RT].[Name] AS [#ReferenceTableName]
			  ,[C].[Name]
			  ,[C].[Alias]
			  ,[C].[Description]
			  ,[C].[Title]
			  ,[C].[Caption]
			  ,[C].[Default]
			  ,[C].[Minimum]
			  ,[C].[Maximum]
			  ,[C].[IsPrimarykey]
			  ,[C].[IsAutoIncrement]
			  ,[C].[IsRequired]
			  ,[C].[IsListable]
			  ,[C].[IsFilterable]
			  ,[C].[IsEditable]
			  ,[C].[IsGridable]
			  ,[C].[IsEncrypted]
			  ,[C].[IsInWords]
			INTO [#Columns]
			FROM [dbo].[Columns] [C]
				INNER JOIN [#Tables] [T] ON [T].[Id] = [C].[TableId]
				INNER JOIN [#Domains] [D] ON [D].[Id] = [C].[DomainId]
				LEFT JOIN [#Tables] [RT] ON [RT].[Id] = [C].[ReferenceTableId]
		IF @@ROWCOUNT = 0
			THROW 51000, 'Coluna(s) de tabela(s) não cadastrada(s)', 1
		ALTER TABLE [#Columns] ADD PRIMARY KEY CLUSTERED([Id])
		-- 15 [Indexes]
		SELECT 'Index' AS [Kind]
			  ,[I].[Id]
			  ,[I].[TableId]
			  ,[T].[Name] AS [#TableName]
			  ,[I].[Name]
			  ,[I].[IsUnique]
		  INTO [#Indexes]
		  FROM [dbo].[Indexes] [I]
			INNER JOIN [#Tables] [T] ON [T].[Id] = [I].[TableId]
		ALTER TABLE [#Indexes] ADD PRIMARY KEY CLUSTERED([Id])
		-- 16 [Indexkeys]
		SELECT 'Indexkey' AS [Kind]
			  ,[IK].[Id]
			  ,[IK].[IndexId]
			  ,[I].[Name] AS [#IndexName]
			  ,[IK].[Sequence]
			  ,[IK].[ColumnId]
			  ,[C].[Name] AS [#ColumnName]
			  ,[IK].[IsDescending]
		  INTO [#Indexkeys]
		  FROM [dbo].[Indexkeys] [IK]
			INNER JOIN [#Indexes] [I] ON [I].[Id] = [IK].[IndexId]
			INNER JOIN [#Columns] [C] ON [C].[Id] = [IK].[ColumnId]
		ALTER TABLE [#Indexkeys] ADD PRIMARY KEY CLUSTERED([Id])
		-- 17 [Sessions]
		SELECT TOP 0 'Session' AS [Kind]
					,[Id]
				    ,[SystemId]
					,[UserId]
					,[PublicKey]
					,[IsLogged]
			INTO [#Sessions]
			FROM [dbo].[Sessions]
		-- 18 [Transactions]
		SELECT TOP 0 'Transaction' AS [Kind]
					,[Id]
				    ,[SessionId]
					,[IsConfirmed]
			INTO [#Transactions]
			FROM [dbo].[Transactions]
		-- 19 [Operations]
		SELECT TOP 0 'Operation' AS [Kind]
					,[Id]
				    ,[TransactionId]
					,[TableName]
					,[Action]
					,[LastRecord]
					,[ActualRecord]
					,[IsConfirmed]
			INTO [#Operations]
			FROM [dbo].[Operations]
		-- 21 [Unicities]
		SELECT DISTINCT 'Unicity' AS [Kind]
						,[U].[Id]
						,[U].[ColumnId1]
						,[T1].[Id] AS [#TableId1]
						,[T1].[Name] AS [#TableName1]
						,[T1].[Alias] AS [#TableAlias1]
						,[C1].[Name] AS [#ColumnName1]
						,[U].[ColumnId2]
						,[T2].[Id] AS [#TableId2]
						,[T2].[Name] AS [#TableName2]
						,[T2].[Alias] AS [#TableAlias2]
						,[C2].[Name] AS [#ColumnName2]
						,[U].[IsBidirectional]
			INTO [#Unicities]
			FROM [dbo].[Unicities] [U]
				INNER JOIN [dbo].[#Columns] [C] ON [C].[Id] IN ([U].[ColumnId1], [U].[ColumnId2])
				INNER JOIN [dbo].[Columns] [C1] ON [C1].[Id] = [U].[ColumnId1]
				INNER JOIN [dbo].[Columns] [C2] ON [C2].[Id] = [U].[ColumnId2]
				INNER JOIN [dbo].[Tables] [T1] ON [T1].[Id] = [C1].[TableId]
				INNER JOIN [dbo].[Tables] [T2] ON [T2].[Id] = [C2].[TableId]

		SELECT * FROM [#Categories]
		SELECT * FROM [#Types]
		SELECT * FROM [#Masks]
		SELECT * FROM [#Domains]
		SELECT * FROM [#Systems]
		SELECT * FROM [#Menus] ORDER BY [SystemId], [Sequence]
		SELECT * FROM [#Users]
		SELECT * FROM [#SystemsUsers]
		SELECT * FROM [#Connections]
		SELECT * FROM [#Databases]
		SELECT * FROM [#SystemsDatabases]
		SELECT * FROM [#Tables]
		SELECT * FROM [#DatabasesTables]
		SELECT * FROM [#Columns] ORDER BY [TableId], [Sequence]
		SELECT * FROM [#Indexes]
		SELECT * FROM [#Indexkeys] ORDER BY [IndexId], [Sequence]
		SELECT * FROM [#Sessions]
		SELECT * FROM [#Transactions]
		SELECT * FROM [#Operations]
		SELECT * FROM [#Associations]
		SELECT * FROM [#Unicities]

	RETURN 0
END
GO
/**********************************************************************************
Criar function [dbo].[HUNDREDS_IN_WORDS]
**********************************************************************************/
IF(SELECT object_id('[dbo].[HUNDREDS_IN_WORDS]', 'FN')) IS NULL
	EXEC('CREATE FUNCTION [dbo].[HUNDREDS_IN_WORDS]() RETURNS VARCHAR(MAX) AS BEGIN RETURN '''' END')
GO
ALTER FUNCTION [dbo].[HUNDREDS_IN_WORDS](@Value AS SMALLINT
										  ,@EnglishOrPortuguese BIT)
RETURNS VARCHAR(MAX) AS  
BEGIN 
	DECLARE @ThirdDigit INT = @Value / 100,
			@SecondDigit INT = CAST(@Value / 10 AS INT) % 10,
			@FirstDigit INT = @Value % 10,
			@And VARCHAR(10),
			@Result VARCHAR(MAX) = '',
			@Separator VARCHAR(5)
	DECLARE @Units TABLE (Id INT, Nome VARCHAR(50))
	DECLARE @Dozens TABLE (Id INT, Nome VARCHAR(50))
	DECLARE @Hundreds TABLE (Id INT, Nome VARCHAR(50))

	IF @EnglishOrPortuguese = 1 BEGIN
		SET @And = ' e '
		INSERT @Units
			VALUES(0, ''),
				  (1, 'Um'),
				  (2, 'Dois'),
				  (3, 'Três'),
				  (4, 'Quatro'),
				  (5, 'Cinco'),
				  (6, 'Seis'),
				  (7, 'Sete'),
				  (8, 'Oito'),
				  (9, 'Nove'),
				  (10, 'Dez'),
				  (11, 'Onze'),
				  (12, 'Doze'),
				  (13, 'Treze'),
				  (14, 'Quatorze'),
				  (15, 'Quinze'),
				  (16, 'Dezesseis'),
				  (17, 'Dezessete'),
				  (18, 'Dezoito'),
				  (19, 'Dezenove')
			
		INSERT @Dozens
			VALUES(0, ''),
				  (1, 'Dez'),
				  (2, 'Vinte'),
				  (3, 'Trinta'),
				  (4, 'Quarenta'),
				  (5, 'Cinquenta'),
				  (6, 'Sessenta'),
				  (7, 'Setenta'),
				  (8, 'Oitenta'),
				  (9, 'Noventa')
			
		INSERT @Hundreds
			VALUES(0, ''),
				  (1, 'Cento'),
				  (2, 'Duzentos'),
				  (3, 'Trezentos'),
				  (4, 'Quatrocentos'),
				  (5, 'Quinhentos'),
				  (6, 'Seiscentos'),
				  (7, 'Setecentos'),
				  (8, 'Oitocentos'),
				  (9, 'Novecentos')
	END ELSE BEGIN
		SET @And = ' and '
		INSERT @Units
			VALUES(0, ''),
				  (1, 'One'),
				  (2, 'Two'),
				  (3, 'Three'),
				  (4, 'Four'),
				  (5, 'Five'),
				  (6, 'Six'),
				  (7, 'Seven'),
				  (8, 'Eight'),
				  (9, 'Nine'),
				  (10, 'Ten'),
				  (11, 'Eleven'),
				  (12, 'Twelve'),
				  (13, 'Thirteen'),
				  (14, 'Fourteen'),
				  (15, 'Fifteen'),
				  (16, 'Sixteen'),
				  (17, 'Seventeen'),
				  (18, 'Eighteen'),
				  (19, 'Nineteen')
			
		INSERT @Dozens
			VALUES(0, ''),
				  (1, 'Ten'),
				  (2, 'Twenty'),
				  (3, 'Thirty'),
				  (4, 'Forty'),
				  (5, 'Fifty'),
				  (6, 'Sixty'),
				  (7, 'Seventy'),
				  (8, 'Eighty'),
				  (9, 'Ninety')
			
		INSERT @Hundreds
			VALUES(0, ''),
				  (1, 'One Hundred'),
				  (2, 'Two Hundred'),
				  (3, 'Three Hundred'),
				  (4, 'Four Hundred'),
				  (5, 'Five Hundred'),
				  (6, 'Six Hundred'),
				  (7, 'Seven Hundred'),
				  (8, 'Eight Hundred'),
				  (9, 'Nine Hundred')
	END
	SET  @Separator = CASE WHEN @EnglishOrPortuguese = 1 THEN @And ELSE ' ' END
	IF @Value < 20 BEGIN
		SET @Result = (SELECT Nome FROM @Units WHERE Id = @Value)
	END ELSE IF @Value < 100 BEGIN
		SET @Result = (SELECT Nome FROM @Dozens WHERE Id = @SecondDigit) +
						 CASE WHEN @FirstDigit = 0 THEN '' ELSE CASE WHEN @EnglishOrPortuguese = 1 THEN @And ELSE '-' END + (SELECT Nome FROM @Units WHERE Id = @FirstDigit) END
	END ELSE IF @Value = 100 BEGIN
		SET @Result = CASE WHEN @EnglishOrPortuguese = 1 THEN 'Cem' ELSE 'One Hundred' END
	END ELSE IF @Value % 100 = 0 BEGIN
		SET @Result = (SELECT Nome FROM @Hundreds WHERE Id = @ThirdDigit)
	END ELSE BEGIN
		SET @Result = (SELECT Nome FROM @Hundreds WHERE Id = @ThirdDigit) +
						 CASE WHEN @Value < 20
							  THEN @Separator + (SELECT Nome FROM @Units WHERE Id = @SecondDigit * 10 + @FirstDigit)
						      ELSE @Separator + (SELECT Nome FROM @Dozens WHERE Id = @SecondDigit) + CASE WHEN @FirstDigit = 0 
																										  THEN '' 
																										  ELSE CASE WHEN @EnglishOrPortuguese = 1 THEN @And ELSE '-' END + (SELECT Nome FROM @Units WHERE Id = @FirstDigit)
																									 END
						 END
	END

	RETURN @Result
END
GO
/**********************************************************************************
Criar function [dbo].[NUMBER_IN_WORDS]
**********************************************************************************/
IF(SELECT object_id('[dbo].[NUMBER_IN_WORDS]', 'FN')) IS NULL
	EXEC('CREATE FUNCTION [dbo].[NUMBER_IN_WORDS]() RETURNS VARCHAR(MAX) AS BEGIN RETURN '''' END')
GO
ALTER FUNCTION [dbo].[NUMBER_IN_WORDS](@Value AS DECIMAL(18,2)
										,@EnglishOrPortuguese BIT = 1
										,@CurrencyInSingular VARCHAR(50) = NULL
										,@CurrencyInPlural VARCHAR(50) = NULL
										,@CentsInSingular VARCHAR(50) = NULL
										,@CentsInPlural VARCHAR(50) = NULL)
RETURNS VARCHAR(MAX) AS  
BEGIN 
	DECLARE @Power INT = 0,
		    @Separator VARCHAR(5) = '',
		    @PartialValue INT,
		    @Digito INT = 0,
		    @LastDigit INT,
			@Result VARCHAR(MAX) = '',
			@Minus VARCHAR(10) = '',
			@Of VARCHAR(10),
			@And VARCHAR(10),
			@ValueOfHundreds INT = 0,
			@ValueOfThousands INT = 0
	DECLARE @Powers TABLE (Id INT, NomeSingular VARCHAR(50), NomePlural VARCHAR(50))

	IF @EnglishOrPortuguese = 1 BEGIN
		IF @CurrencyInSingular IS NULL
			SET @CurrencyInSingular = 'Real'
		IF @CurrencyInPlural IS NULL
			SET @CurrencyInPlural = 'Reais'
		IF @CentsInSingular IS NULL
			SET @CentsInSingular = 'Centavo'
		IF @CentsInPlural IS NULL
			SET @CentsInPlural = 'Centavos'
		SET @Of = ' de '
		SET @And = ' e '
		IF @Value < 0 BEGIN
			SET @Value = -@Value
			SET @Minus = 'Menos'
		END	
		INSERT @Powers
			VALUES(0,'', ''),
				  (1,'Mil', 'Mil'),
				  (2,'Milhão', 'Milhões'),
				  (3,'Bilhão', 'Bilhões'),
				  (4,'Trilhão', 'Trilhões'),
				  (5,'Quatrilhão', 'Quatrilhões'),
				  (6,'Quintilhão', 'Quintilhões'),
				  (7,'Sextilhão', 'Sextilhões'),
				  (8,'Septilhão', 'Septilhões'),
				  (9,'Octilhão', 'Octilhões'),
				  (10,'Nonilhão', 'Nonilhões'),
				  (11,'Decilhão', 'Decilhões'),
			      (12,'Undecilhão', 'Undecilhões'),
				  (13,'Duodecilhão', 'Duodecilhões'),
				  (14,'Tredecilhão', 'Tredecilhões')
	END ELSE BEGIN
		IF @CurrencyInSingular IS NULL
			SET @CurrencyInSingular = 'Dollar'
		IF @CurrencyInPlural IS NULL
			SET @CurrencyInPlural = 'Dollars'
		IF @CentsInSingular IS NULL
			SET @CentsInSingular = 'Cent'
		IF @CentsInPlural IS NULL
			SET @CentsInPlural = 'Cents'
		SET @Of = ' of '
		SET @And = ' and '
		IF @Value < 0 BEGIN
			SET @Value = -@Value
			SET @Minus = 'Minus'
		END	
		INSERT @Powers
			VALUES(0,'', ''),
				  (1,'Thousand', 'Thousand'),
				  (2,'Million', 'Million'),
				  (3,'Billion', 'Billion'),
				  (4,'Trillion', 'Trillion'),
				  (5,'Quadrillion', 'Quadrillion'),
				  (6,'Quintillion', 'Quintillion'),
				  (7,'Sextillion', 'Sextillion'),
				  (8,'Septillion', 'Septillion'),
				  (9,'Octillion', 'Octillion'),
				  (10,'Nonillion', 'Nonillion'),
				  (11,'Decillion', 'Decillion'),
				  (12,'Undecillion', 'Undecillion'),
				  (13,'Duodecillion', 'Duodecillion'),
				  (14,'Tredecillion', 'Tredecillion')
	END
	SET @PartialValue = FLOOR(@Value)
	WHILE @PartialValue > 0 BEGIN
		SET @LastDigit = @Digito
		SET @Digito = @PartialValue % 1000
		IF @Power = 0 BEGIN
			SET @ValueOfHundreds = @Digito
		END ELSE IF @Power = 1 BEGIN
			SET @ValueOfThousands = @Digito
		END
		IF @Digito = 1 BEGIN
			 SET @Result = [dbo].[HUNDREDS_IN_WORDS](@Digito, @EnglishOrPortuguese) + ' ' + 
							  (SELECT NomeSingular FROM @Powers WHERE Id = @Power) + 
							  @Separator + @Result
		END ELSE IF @Digito > 0 BEGIN
			 SET @Result = [dbo].[HUNDREDS_IN_WORDS](@Digito, @EnglishOrPortuguese) + ' ' + 
							  (SELECT NomePlural FROM @Powers WHERE Id = @Power) + 
							  @Separator + @Result
		END
		SET @PartialValue = @PartialValue / 1000
		IF @Digito > 0 BEGIN
			IF (@Power = 0) BEGIN
				SET @Separator = CASE WHEN @EnglishOrPortuguese = 1 THEN @And ELSE ', ' END
			END ELSE BEGIN
				SET @Separator = ', '
			END
		END
		SET @Power = @Power + 1
	END
	SET @Result = RTRIM(@Result)
	IF @Result = '' BEGIN
		IF @Value = 0 BEGIN
			SET @Result = 'Zero ' + @CurrencyInPlural
		END
	END ELSE IF @Digito = 1 BEGIN
		IF @Power < 2 BEGIN
			SET @Result = @Result + ' ' + @CurrencyInSingular
		END ELSE IF @Power = 2 BEGIN
			SET @Result = @Result + ' ' + @CurrencyInPlural
		END ELSE BEGIN
			SET @Result = @Result + CASE WHEN @ValueOfHundreds > 0 OR @ValueOfThousands > 0 THEN ' ' ELSE @Of END + @CurrencyInPlural
		END
	END ELSE IF @Power <= 2 BEGIN
		SET @Result = @Result + ' ' + @CurrencyInPlural
	END ELSE BEGIN
		SET @Result = @Result + CASE WHEN @ValueOfHundreds > 0 OR @ValueOfThousands > 0 THEN ' ' ELSE @Of END + @CurrencyInPlural
	END
	SET @PartialValue = FLOOR(@Value * 100) % 100
	IF @PartialValue > 0 BEGIN
		IF @PartialValue = 1 BEGIN
			IF @Result = '' BEGIN
				SET @Result = [dbo].[HUNDREDS_IN_WORDS](@PartialValue, @EnglishOrPortuguese) + ' ' + @CentsInSingular + @Of + @CurrencyInSingular
			END ELSE BEGIN
				SET @Result = @Result + @And + [dbo].[HUNDREDS_IN_WORDS](@PartialValue, @EnglishOrPortuguese) + ' ' + @CentsInSingular 
			END
		END ELSE BEGIN
			IF @Result = '' BEGIN
				SET @Result = [dbo].[HUNDREDS_IN_WORDS](@PartialValue, @EnglishOrPortuguese) + ' ' + @CentsInPlural + @Of + @CurrencyInPlural
			END ELSE BEGIN
				SET @Result = @Result + @And + [dbo].[HUNDREDS_IN_WORDS](@PartialValue, @EnglishOrPortuguese) + ' ' + @CentsInPlural
			END
		END
	END		

	RETURN @Minus + ' ' + @Result
END
GO

/**********************************************************************************
Criar function [dbo].[IS_EQUAL]
**********************************************************************************/
IF (SELECT object_id('[dbo].[IS_EQUAL]', 'FN')) IS NULL
    EXEC('CREATE FUNCTION [dbo].[IS_EQUAL]() RETURNS BIT AS BEGIN RETURN 1 END')
GO

ALTER FUNCTION [dbo].[IS_EQUAL](
    @LeftValue NVARCHAR(MAX),
    @RightValue NVARCHAR(MAX),
    @TypeValue NVARCHAR(25)
)
RETURNS BIT AS 
BEGIN
    IF @LeftValue IS NULL AND @RightValue IS NULL
        RETURN 1;
    IF @LeftValue IS NULL OR @RightValue IS NULL
        RETURN 0;
	
    -- Comparações numéricas
	IF @TypeValue = 'int'
        RETURN CASE WHEN TRY_CAST(@LeftValue AS int) = TRY_CAST(@RightValue AS int) THEN 1 ELSE 0 END;
	IF @TypeValue = 'smallint'
        RETURN CASE WHEN TRY_CAST(@LeftValue AS smallint) = TRY_CAST(@RightValue AS smallint) THEN 1 ELSE 0 END;
	IF @TypeValue = 'tinyint'
        RETURN CASE WHEN TRY_CAST(@LeftValue AS tinyint) = TRY_CAST(@RightValue AS tinyint) THEN 1 ELSE 0 END;
	IF @TypeValue = 'int'
        RETURN CASE WHEN TRY_CAST(@LeftValue AS int) = TRY_CAST(@RightValue AS int) THEN 1 ELSE 0 END;

	-- Comparações decimais e monetárias
	IF @TypeValue = 'decimal'
        RETURN CASE WHEN TRY_CAST(@LeftValue AS decimal(38, 18)) = TRY_CAST(@RightValue AS decimal(38, 18)) THEN 1 ELSE 0 END;
	IF @TypeValue = 'numeric'
        RETURN CASE WHEN TRY_CAST(@LeftValue AS numeric(38, 18)) = TRY_CAST(@RightValue AS numeric(38, 18)) THEN 1 ELSE 0 END;
	IF @TypeValue = 'float'
        RETURN CASE WHEN TRY_CAST(@LeftValue AS float) = TRY_CAST(@RightValue AS float) THEN 1 ELSE 0 END;
	IF @TypeValue = 'real'
        RETURN CASE WHEN TRY_CAST(@LeftValue AS real) = TRY_CAST(@RightValue AS real) THEN 1 ELSE 0 END;
	IF @TypeValue = 'money'
        RETURN CASE WHEN TRY_CAST(@LeftValue AS money) = TRY_CAST(@RightValue AS money) THEN 1 ELSE 0 END;
	IF @TypeValue = 'smallmoney'
        RETURN CASE WHEN TRY_CAST(@LeftValue AS smallmoney) = TRY_CAST(@RightValue AS smallmoney) THEN 1 ELSE 0 END;
    
    -- Comparação de strings
	IF @TypeValue IN ('varchar', 'char', 'text', 'nvarchar', 'nchar', 'ntext')
        RETURN CASE WHEN @LeftValue = @RightValue THEN 1 ELSE 0 END;

    -- Comparações de datas
	IF @TypeValue = 'date'
        RETURN CASE WHEN TRY_CAST(@LeftValue AS date) = TRY_CAST(@RightValue AS date) THEN 1 ELSE 0 END;
	IF @TypeValue = 'datetime'
        RETURN CASE WHEN TRY_CAST(@LeftValue AS datetime) = TRY_CAST(@RightValue AS datetime) THEN 1 ELSE 0 END;
	IF @TypeValue = 'datetime2'
        RETURN CASE WHEN TRY_CAST(@LeftValue AS datetime2) = TRY_CAST(@RightValue AS datetime2) THEN 1 ELSE 0 END;
	IF @TypeValue = 'smalldatetime'
        RETURN CASE WHEN TRY_CAST(@LeftValue AS smalldatetime) = TRY_CAST(@RightValue AS smalldatetime) THEN 1 ELSE 0 END;
	IF @TypeValue = 'datetimeoffset'
        RETURN CASE WHEN TRY_CAST(@LeftValue AS datetimeoffset) = TRY_CAST(@RightValue AS datetimeoffset) THEN 1 ELSE 0 END;
	IF @TypeValue = 'time'
        RETURN CASE WHEN TRY_CAST(@LeftValue AS time) = TRY_CAST(@RightValue AS time) THEN 1 ELSE 0 END;

    -- Comparações de tipos especiais
    IF @TypeValue = 'bit'
        RETURN CASE WHEN TRY_CAST(@LeftValue AS BIT) = TRY_CAST(@RightValue AS BIT) THEN 1 ELSE 0 END;
    IF @TypeValue = 'sysname'
        RETURN CASE WHEN TRY_CAST(@LeftValue AS SYSNAME) = TRY_CAST(@RightValue AS SYSNAME) THEN 1 ELSE 0 END;
    IF @TypeValue = 'uniqueidentifier'
        RETURN CASE WHEN TRY_CAST(@LeftValue AS UNIQUEIDENTIFIER) = TRY_CAST(@RightValue AS UNIQUEIDENTIFIER) THEN 1 ELSE 0 END;

    -- Comparação final como VARBINARY(MAX) (fallback)
    RETURN CASE WHEN TRY_CAST(@LeftValue AS VARBINARY(MAX)) = TRY_CAST(@RightValue AS VARBINARY(MAX)) THEN 1 ELSE 0 END;
END
GO
/**********************************************************************************
Criar stored procedure [dbo].[TransactionCreate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[TransactionCreate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[TransactionCreate] AS PRINT 1')
GO
ALTER PROCEDURE[dbo].[TransactionCreate](@SessionId BIGINT
                                         ,@UserName VARCHAR(25)
                                         ,@ReturnValue BIGINT OUT) AS BEGIN
    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED
    IF @SessionId IS NULL
        THROW 51000, 'Valor de @SessionId é requerido', 1
    IF @UserName IS NULL
        THROW 51000, 'Valor de @UserName é requerido', 1
    IF EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [SessionId] = @SessionId AND [IsConfirmed] IS NULL)
        THROW 51000, 'Há transação pendente neste @SessionId', 1

    DECLARE @TransactionId BIGINT

    EXEC [dbo].[NewId] 'crudex', 'crudex', 'Transactions', @TransactionId OUT
    INSERT [dbo].[Transactions] ([Id]
                                ,[SessionId]
                                ,[IsConfirmed]
                                ,[CreatedAt]
                                ,[CreatedBy])
                            VALUES (@TransactionId
                                   ,@SessionId
                                   ,NULL
                                   ,GETDATE()
                                   ,@UserName)
    SET @ReturnValue = @TransactionId

    RETURN 0
END
GO
/**********************************************************************************
Criar stored procedure [dbo].[TransactionCommit]
**********************************************************************************/
IF(SELECT object_id('[dbo].[TransactionCommit]', 'P')) IS NULL

	EXEC('CREATE PROCEDURE [dbo].[TransactionCommit] AS PRINT 1')

GO

ALTER PROCEDURE[dbo].[TransactionCommit](@Login NVARCHAR(MAX)

										   ,@TransactionId BIGINT

										   ,@ReturnValue BIGINT OUT) AS BEGIN

	DECLARE @ErrorMessage NVARCHAR(MAX)



	SET NOCOUNT ON

	SET TRANSACTION ISOLATION LEVEL READ COMMITTED



	DECLARE @LoginReturn BIGINT

			,@SessionId BIGINT

			,@UserName VARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS VARCHAR(25))

			,@IsConfirmed BIT

			,@CreatedBy VARCHAR(25)

			,@sql NVARCHAR(MAX)



	EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT

	SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)

	IF @SessionId IS NULL

		THROW 51000, 'LoginId Ã© requerido', 1

	IF @TransactionId IS NULL

		THROW 51000, 'Valor de @TransactionId Ã© requerido', 1

	IF @UserName IS NULL

		THROW 51000, 'Valor de @UserName Ã© requerido', 1

	SELECT @IsConfirmed = [IsConfirmed]

		  ,@CreatedBy = [CreatedBy]

		FROM [dbo].[Transactions]

		WHERE [Id] = @TransactionId

			  AND [SessionId] = @SessionId

	IF @@ROWCOUNT = 0

		THROW 51000, 'TransaÃ§Ã£o inexistente', 1

	IF @IsConfirmed IS NOT NULL BEGIN

		SET @ErrorMessage = 'TransaÃ§Ã£o jÃ¡ ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluÃ­da' END;

		THROW 51000, @ErrorMessage, 1

	END

	IF @UserName <> @CreatedBy

		THROW 51000, 'Erro grave de seguranÃ§a', 1

	SET @sql = (SELECT STRING_AGG(
								  CASE [O].[Action]
									  WHEN 'create' THEN '[dbo].[' + [T].[Alias] + 'Create] @Login = @Login, @OperationId = ' + CAST([O].[Id] AS VARCHAR(20))
									  WHEN 'update' THEN '[dbo].[' + [T].[Alias] + 'Update] @Login = @Login, @OperationId = ' + CAST([O].[Id] AS VARCHAR(20))
									  WHEN 'delete' THEN '[dbo].[' + [T].[Alias] + 'Delete] @Login = @Login, @OperationId = ' + CAST([O].[Id] AS VARCHAR(20))
								  END, '; ')

					FROM [dbo].[Operations] [O]

						INNER JOIN [dbo].[Tables] [T] ON [T].[Name] = [O].[TableName]

					WHERE [O].[TransactionId] = @TransactionId

						  AND [O].[IsConfirmed] IS NULL)

	IF @sql IS NOT NULL

		EXEC sp_executesql @sql, N'@Login NVARCHAR(MAX)', @Login = @Login

	UPDATE [dbo].[Transactions]

		SET [IsConfirmed] = 1

			,[UpdatedBy] = @UserName

			,[UpdatedAt] = GETDATE()

		WHERE [Id] = @TransactionId



	RETURN 0

END

GO

/**********************************************************************************
Criar stored procedure [dbo].[TransactionRollback]
**********************************************************************************/
IF(SELECT object_id('[dbo].[TransactionRollback]', 'P')) IS NULL
	EXEC('CREATE PROCEDURE [dbo].[TransactionRollback] AS PRINT 1')
GO
ALTER PROCEDURE[dbo].[TransactionRollback](@TransactionId INT
											,@UserName VARCHAR(25)) AS BEGIN
	DECLARE @ErrorMessage NVARCHAR(MAX)

	SET NOCOUNT ON
	SET TRANSACTION ISOLATION LEVEL READ COMMITTED

	DECLARE @OperationId INT
			,@CreatedBy VARCHAR(25)
			,@IsConfirmed BIT

	IF @TransactionId IS NULL
		THROW 51000, 'Valor de @TransactionId Ã© requerido', 1
	SELECT @IsConfirmed = [IsConfirmed]
		  ,@CreatedBy = [CreatedBy]
		FROM [dbo].[Transactions]
		WHERE [Id] = @TransactionId
	IF @@ROWCOUNT = 0
		THROW 51000, 'TransaÃ§Ã£o inexistente', 1
	IF @IsConfirmed IS NOT NULL BEGIN
		SET @ErrorMessage = 'TransaÃ§Ã£o jÃ¡ ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluÃ­da' END;
		THROW 51000, @ErrorMessage, 1
	END

	IF @UserName <> @CreatedBy
		THROW 51000, 'Erro grave de seguranÃ§a', 1
	WHILE 1 = 1 BEGIN
		SELECT TOP 1 @OperationId = [Id]
					,@CreatedBy = [CreatedBy]
			FROM [dbo].[Operations]
			WHERE [TransactionId] = @TransactionId
					AND [IsConfirmed] IS NULL
			ORDER BY [Id]
		IF @@ROWCOUNT = 0
			BREAK
		IF @UserName <> @CreatedBy
			THROW 51000, 'Erro grave de seguranÃ§a', 1
		UPDATE [dbo].[Operations]
			SET [IsConfirmed] = 0
				,[UpdatedBy] = @UserName
				,[UpdatedAt] = GETDATE()
			WHERE [Id] = @OperationId
	END
	UPDATE [dbo].[Transactions]
		SET [IsConfirmed] = 0
			,[UpdatedBy] = @UserName
			,[UpdatedAt] = GETDATE()
		WHERE [Id] = @TransactionId

	RETURN 1
END
GO

