               ,@W_Name nvarchar(25) = CAST(JSON_VALUE(@ActualRecord, '$.Name') AS nvarchar(25))
               ,@W_MaxLength int = CAST(JSON_VALUE(@ActualRecord, '$.MaxLength') AS int)
               ,@W_Minimum nvarchar(max) = CAST(JSON_VALUE(@ActualRecord, '$.Minimum') AS nvarchar(max))
               ,@W_Maximum nvarchar(max) = CAST(JSON_VALUE(@ActualRecord, '$.Maximum') AS nvarchar(max))
               ,@W_AskLength bit = CAST(JSON_VALUE(@ActualRecord, '$.AskLength') AS bit)
               ,@W_AskDecimals bit = CAST(JSON_VALUE(@ActualRecord, '$.AskDecimals') AS bit)
               ,@W_AskPrimarykey bit = CAST(JSON_VALUE(@ActualRecord, '$.AskPrimarykey') AS bit)
               ,@W_AskAutoincrement bit = CAST(JSON_VALUE(@ActualRecord, '$.AskAutoincrement') AS bit)
               ,@W_AskFilterable bit = CAST(JSON_VALUE(@ActualRecord, '$.AskFilterable') AS bit)
               ,@W_AskGridable bit = CAST(JSON_VALUE(@ActualRecord, '$.AskGridable') AS bit)
               ,@W_AskCodification bit = CAST(JSON_VALUE(@ActualRecord, '$.AskCodification') AS bit)
               ,@W_IsLikeable bit = CAST(JSON_VALUE(@ActualRecord, '$.IsLikeable') AS bit)
               ,@W_IsActive bit = CAST(JSON_VALUE(@ActualRecord, '$.IsActive') AS bit)

        UPDATE [dbo].[Types] SET [Id] = @W_Id
                                          ,[CategoryId] = @W_CategoryId
                                          ,[Name] = @W_Name
                                          ,[MaxLength] = @W_MaxLength
                                          ,[Minimum] = @W_Minimum
                                          ,[Maximum] = @W_Maximum
                                          ,[AskLength] = @W_AskLength
                                          ,[AskDecimals] = @W_AskDecimals
                                          ,[AskPrimarykey] = @W_AskPrimarykey
                                          ,[AskAutoincrement] = @W_AskAutoincrement
                                          ,[AskFilterable] = @W_AskFilterable
                                          ,[AskGridable] = @W_AskGridable
                                          ,[AskCodification] = @W_AskCodification
                                          ,[IsLikeable] = @W_IsLikeable
                                          ,[IsActive] = @W_IsActive
                                          ,[UpdatedAt] = GETDATE()
                                          ,[UpdatedBy] = @UserName
            WHERE [Id] = @W_Id
        UPDATE [dbo].[Operations]
            SET [IsConfirmed] = 1
                ,[UpdatedAt] = GETDATE()
                ,[UpdatedBy] = @UserName
            WHERE [Id] = @OperationId

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[TypeDelete]
**********************************************************************************/
IF(SELECT object_id('[dbo].[TypeDelete]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[TypeDelete] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[TypeDelete](@Login NVARCHAR(MAX)
                                             ,@OperationId BIGINT) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    DECLARE @TransactionId BIGINT
               ,@TransactionIdAux BIGINT
               ,@TableName NVARCHAR(25)
               ,@Action NVARCHAR(15)
               ,@CreatedBy NVARCHAR(25)
               ,@LastRecord NVARCHAR(max)
               ,@ActualRecord NVARCHAR(max)
               ,@IsConfirmed BIT

    IF @OperationId IS NULL
            THROW 51000, 'Valor de @OperationId requerido', 1
        SELECT @TransactionId = [TransactionId]
               ,@TableName = [TableName]
               ,@Action = [Action]
               ,@CreatedBy = [CreatedBy]
               ,@LastRecord = [LastRecord]
               ,@ActualRecord = [ActualRecord]
               ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [Id] = @OperationId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Operação inexistente', 1
        IF @TableName <> 'Types'
            THROW 51000, 'Tabela da operação é inválida', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @Action <> 'delete'
            THROW 51000, 'Ação da operação é inválida para Delete', 1
        EXEC @TransactionIdAux = [dbo].[TypeValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        IF @TransactionId <> @TransactionIdAux
            THROW 51000, 'Transação da operação é inválida', 1
        DECLARE @W_Id tinyint = CAST(JSON_VALUE(@LastRecord, '$.Id') AS tinyint)

        DELETE FROM [dbo].[Types] WHERE [Id] = @W_Id

        UPDATE [dbo].[Operations]
            SET [IsConfirmed] = 1
                ,[UpdatedAt] = GETDATE()
                ,[UpdatedBy] = @UserName
            WHERE [Id] = @OperationId

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[TypesRead]
**********************************************************************************/
IF(SELECT object_id('[dbo].[TypesRead]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[TypesRead] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[TypesRead](@Login NVARCHAR(MAX)
                                          ,@RecordFilter NVARCHAR(MAX)
                                          ,@OrderBy NVARCHAR(MAX)
                                          ,@PaddingGridLastPage BIT
                                          ,@IsActionList BIT
                                          ,@PageNumber INT OUT
                                          ,@LimitRows INT OUT
                                          ,@MaxPage INT OUT
                                          ,@ReturnValue BIGINT OUT) AS BEGIN

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @LoginId BIGINT
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @LoginId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @LoginId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    IF @RecordFilter IS NULL
            SET @RecordFilter = '{}'
        ELSE IF ISJSON(@RecordFilter) = 0
            THROW 51000, 'Valor de @RecordFilter não está no formato JSON', 1
        SET @OrderBy = TRIM(ISNULL(@OrderBy, ''))
        IF @OrderBy = ''
            SET @OrderBy = '[Id]'
        ELSE BEGIN
            SET @OrderBy = REPLACE(REPLACE(@OrderBy, '[', ''), ']', '')
            IF EXISTS(SELECT 1 
                         FROM (SELECT CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                           WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                           ELSE TRIM([value])
                                      END AS [ColumnName]
                                  FROM STRING_SPLIT(@OrderBy, ',')) AS [O]
                                      LEFT JOIN (SELECT [#1].[name] AS ColumnName
                                                    FROM [sys].[columns] [#1]
                                                        INNER JOIN [sys].[tables] [#2] ON [#1].[object_id] = [#2].[object_id]
                                                    WHERE [#2].[name] = 'Types') AS [T] ON [T].[ColumnName] = [O].[ColumnName]
                         WHERE [T].[ColumnName] IS NULL)
                THROW 51000, 'Nome de coluna em @OrderBy é inválido', 1
            SELECT @OrderBy = STRING_AGG('[' + TRIM(CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                                         ELSE TRIM([value])
                                                    END) + '] ' + 
                                                    CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN 'DESC'
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN 'ASC'
                                                         ELSE 'ASC'
                                                    END, ', ')
                FROM STRING_SPLIT(@OrderBy, ',')
        END
        IF @IsActionList = 1
            SET @OrderBy = '[Name]'
        DECLARE @PickerValue nvarchar(25) = NULL

        DECLARE @TransactionId BIGINT = (SELECT MAX([Id]) FROM [dbo].[Transactions] WHERE [SessionId] = @LoginId)

        IF NOT EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [Id] = @TransactionId AND [IsConfirmed] IS NULL)
            SET @TransactionId = NULL
        SELECT [Action] AS [_]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS tinyint) AS [Id]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.CategoryId') AS tinyint) AS [CategoryId]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Name') AS nvarchar(25)) AS [Name]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.MaxLength') AS int) AS [MaxLength]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Minimum') AS nvarchar(max)) AS [Minimum]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Maximum') AS nvarchar(max)) AS [Maximum]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskLength') AS bit) AS [AskLength]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskDecimals') AS bit) AS [AskDecimals]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskPrimarykey') AS bit) AS [AskPrimarykey]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskAutoincrement') AS bit) AS [AskAutoincrement]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskFilterable') AS bit) AS [AskFilterable]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskGridable') AS bit) AS [AskGridable]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskCodification') AS bit) AS [AskCodification]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsLikeable') AS bit) AS [IsLikeable]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsActive') AS bit) AS [IsActive]
            INTO [#tmpOperations]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Types'
                  AND [IsConfirmed] IS NULL
        CREATE UNIQUE INDEX [#tmpOperations] ON [#tmpOperations]([Id])

        DECLARE @_ NVARCHAR(MAX) = (SELECT STRING_AGG(value, ',') FROM OPENJSON(@RecordFilter, '$.Filter._'))
               ,@WhereFixed NVARCHAR(MAX) = ''
               ,@WhereFilter NVARCHAR(MAX) = ''
               ,@WhereSearch NVARCHAR(MAX) = ''
               ,@WhereUser NVARCHAR(MAX) = ''
               ,@Where NVARCHAR(MAX) = ''
               ,@sql NVARCHAR(MAX)

        DECLARE @W_F_Id tinyint = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.Id') AS tinyint)
               ,@W_U_Id tinyint = CAST(JSON_VALUE(@RecordFilter, '$.Filter.Id') AS tinyint)
               ,@W_S_Id tinyint = CAST(JSON_VALUE(@RecordFilter, '$.Search.Id') AS tinyint)
               ,@W_F_Name nvarchar(25) = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.Name') AS nvarchar(25))
               ,@W_U_Name nvarchar(25) = CAST(JSON_VALUE(@RecordFilter, '$.Filter.Name') AS nvarchar(25))
               ,@W_S_Name nvarchar(25) = CAST(JSON_VALUE(@RecordFilter, '$.Search.Name') AS nvarchar(25))
               ,@W_F_AskLength bit = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.AskLength') AS bit)
               ,@W_U_AskLength bit = CAST(JSON_VALUE(@RecordFilter, '$.Filter.AskLength') AS bit)
               ,@W_S_AskLength bit = CAST(JSON_VALUE(@RecordFilter, '$.Search.AskLength') AS bit)
               ,@W_F_AskDecimals bit = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.AskDecimals') AS bit)
               ,@W_U_AskDecimals bit = CAST(JSON_VALUE(@RecordFilter, '$.Filter.AskDecimals') AS bit)
               ,@W_S_AskDecimals bit = CAST(JSON_VALUE(@RecordFilter, '$.Search.AskDecimals') AS bit)
               ,@W_F_AskPrimarykey bit = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.AskPrimarykey') AS bit)
               ,@W_U_AskPrimarykey bit = CAST(JSON_VALUE(@RecordFilter, '$.Filter.AskPrimarykey') AS bit)
               ,@W_S_AskPrimarykey bit = CAST(JSON_VALUE(@RecordFilter, '$.Search.AskPrimarykey') AS bit)
               ,@W_F_AskAutoincrement bit = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.AskAutoincrement') AS bit)
               ,@W_U_AskAutoincrement bit = CAST(JSON_VALUE(@RecordFilter, '$.Filter.AskAutoincrement') AS bit)
               ,@W_S_AskAutoincrement bit = CAST(JSON_VALUE(@RecordFilter, '$.Search.AskAutoincrement') AS bit)
               ,@W_F_AskFilterable bit = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.AskFilterable') AS bit)
               ,@W_U_AskFilterable bit = CAST(JSON_VALUE(@RecordFilter, '$.Filter.AskFilterable') AS bit)
               ,@W_S_AskFilterable bit = CAST(JSON_VALUE(@RecordFilter, '$.Search.AskFilterable') AS bit)
               ,@W_F_AskGridable bit = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.AskGridable') AS bit)
               ,@W_U_AskGridable bit = CAST(JSON_VALUE(@RecordFilter, '$.Filter.AskGridable') AS bit)
               ,@W_S_AskGridable bit = CAST(JSON_VALUE(@RecordFilter, '$.Search.AskGridable') AS bit)
               ,@W_F_AskCodification bit = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.AskCodification') AS bit)
               ,@W_U_AskCodification bit = CAST(JSON_VALUE(@RecordFilter, '$.Filter.AskCodification') AS bit)
               ,@W_S_AskCodification bit = CAST(JSON_VALUE(@RecordFilter, '$.Search.AskCodification') AS bit)
               ,@W_F_IsLikeable bit = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.IsLikeable') AS bit)
               ,@W_U_IsLikeable bit = CAST(JSON_VALUE(@RecordFilter, '$.Filter.IsLikeable') AS bit)
               ,@W_S_IsLikeable bit = CAST(JSON_VALUE(@RecordFilter, '$.Search.IsLikeable') AS bit)
               ,@W_F_IsActive bit = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.IsActive') AS bit)
               ,@W_U_IsActive bit = CAST(JSON_VALUE(@RecordFilter, '$.Filter.IsActive') AS bit)
               ,@W_S_IsActive bit = CAST(JSON_VALUE(@RecordFilter, '$.Search.IsActive') AS bit)

        IF @W_F_Id IS NOT NULL BEGIN
            IF @W_F_Id < CAST('1' AS tinyint)
                THROW 51000, 'Valor de Id deve ser maior que ou igual a ''1''', 1
            SET @WhereFixed = @WhereFixed + ' AND [T].[Id] = @F_Id'
        END
        IF @W_F_Name IS NOT NULL BEGIN
            SET @WhereFixed = @WhereFixed + ' AND [T].[Name] = @F_Name'
        END
        IF @W_F_AskLength IS NOT NULL BEGIN
            SET @WhereFixed = @WhereFixed + ' AND [T].[AskLength] = @F_AskLength'
        END
        IF @W_F_AskDecimals IS NOT NULL BEGIN
            SET @WhereFixed = @WhereFixed + ' AND [T].[AskDecimals] = @F_AskDecimals'
        END
        IF @W_F_AskPrimarykey IS NOT NULL BEGIN
            SET @WhereFixed = @WhereFixed + ' AND [T].[AskPrimarykey] = @F_AskPrimarykey'
        END
        IF @W_F_AskAutoincrement IS NOT NULL BEGIN
            SET @WhereFixed = @WhereFixed + ' AND [T].[AskAutoincrement] = @F_AskAutoincrement'
        END
        IF @W_F_AskFilterable IS NOT NULL BEGIN
            SET @WhereFixed = @WhereFixed + ' AND [T].[AskFilterable] = @F_AskFilterable'
        END
        IF @W_F_AskGridable IS NOT NULL BEGIN
            SET @WhereFixed = @WhereFixed + ' AND [T].[AskGridable] = @F_AskGridable'
        END
        IF @W_F_AskCodification IS NOT NULL BEGIN
            SET @WhereFixed = @WhereFixed + ' AND [T].[AskCodification] = @F_AskCodification'
        END
        IF @W_F_IsLikeable IS NOT NULL BEGIN
            SET @WhereFixed = @WhereFixed + ' AND [T].[IsLikeable] = @F_IsLikeable'
        END
        IF @W_F_IsActive IS NOT NULL BEGIN
            SET @WhereFixed = @WhereFixed + ' AND [T].[IsActive] = @F_IsActive'
        END
        IF @IsActionList = 1 BEGIN
            SET @PickerValue = CAST(JSON_VALUE(@RecordFilter, '$.Picker.Value') AS nvarchar(25))
            IF @PickerValue IS NULL
                SET @PickerValue = ''
            SET @WhereUser = '[T].[Name] LIKE ''%'' + @PickerValue + ''%'''
        END ELSE BEGIN
        IF @_ IS NULL BEGIN
            IF @W_U_Id IS NOT NULL BEGIN
                IF @W_U_Id < CAST('1' AS tinyint)
                    THROW 51000, 'Valor de Id deve ser maior que ou igual a ''1''', 1
                SET @WhereFilter = @WhereFilter + ' AND [T].[Id] = @U_Id'
            END
            IF @W_U_Name IS NOT NULL BEGIN
                SET @WhereFilter = @WhereFilter + ' AND [T].[Name] = @U_Name'
            END
            IF @W_U_AskLength IS NOT NULL BEGIN
                SET @WhereFilter = @WhereFilter + ' AND [T].[AskLength] = @U_AskLength'
            END
            IF @W_U_AskDecimals IS NOT NULL BEGIN
                SET @WhereFilter = @WhereFilter + ' AND [T].[AskDecimals] = @U_AskDecimals'
            END
            IF @W_U_AskPrimarykey IS NOT NULL BEGIN
                SET @WhereFilter = @WhereFilter + ' AND [T].[AskPrimarykey] = @U_AskPrimarykey'
            END
            IF @W_U_AskAutoincrement IS NOT NULL BEGIN
                SET @WhereFilter = @WhereFilter + ' AND [T].[AskAutoincrement] = @U_AskAutoincrement'
            END
            IF @W_U_AskFilterable IS NOT NULL BEGIN
                SET @WhereFilter = @WhereFilter + ' AND [T].[AskFilterable] = @U_AskFilterable'
            END
            IF @W_U_AskGridable IS NOT NULL BEGIN
                SET @WhereFilter = @WhereFilter + ' AND [T].[AskGridable] = @U_AskGridable'
            END
            IF @W_U_AskCodification IS NOT NULL BEGIN
                SET @WhereFilter = @WhereFilter + ' AND [T].[AskCodification] = @U_AskCodification'
            END
            IF @W_U_IsLikeable IS NOT NULL BEGIN
                SET @WhereFilter = @WhereFilter + ' AND [T].[IsLikeable] = @U_IsLikeable'
            END
            IF @W_U_IsActive IS NOT NULL BEGIN
                SET @WhereFilter = @WhereFilter + ' AND [T].[IsActive] = @U_IsActive'
            END
            IF @W_S_Id IS NOT NULL BEGIN
                IF @W_S_Id < CAST('1' AS tinyint)
                    THROW 51000, 'Valor de Id deve ser maior que ou igual a ''1''', 1
                SET @WhereSearch = @WhereSearch + ' AND [T].[Id] = @S_Id'
            END
            IF @W_S_Name IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[Name] = @S_Name'
            END
            IF @W_S_AskLength IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[AskLength] = @S_AskLength'
            END
            IF @W_S_AskDecimals IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[AskDecimals] = @S_AskDecimals'
            END
            IF @W_S_AskPrimarykey IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[AskPrimarykey] = @S_AskPrimarykey'
            END
            IF @W_S_AskAutoincrement IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[AskAutoincrement] = @S_AskAutoincrement'
            END
            IF @W_S_AskFilterable IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[AskFilterable] = @S_AskFilterable'
            END
            IF @W_S_AskGridable IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[AskGridable] = @S_AskGridable'
            END
            IF @W_S_AskCodification IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[AskCodification] = @S_AskCodification'
            END
            IF @W_S_IsLikeable IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[IsLikeable] = @S_IsLikeable'
            END
            IF @W_S_IsActive IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[IsActive] = @S_IsActive'
            END
            IF @WhereFilter <> '' AND @WhereSearch <> ''
                SET @WhereUser = '(' + STUFF(@WhereFilter, 1, 5, '') + ') OR (' + STUFF(@WhereSearch, 1, 5, '') + ')'
            ELSE IF @WhereFilter <> ''
                SET @WhereUser = STUFF(@WhereFilter, 1, 5, '')
            ELSE IF @WhereSearch <> ''
                SET @WhereUser = STUFF(@WhereSearch, 1, 5, '')
        END ELSE
            SET @WhereUser = '[T].[Id] IN (' + @_ + ')'
        END
        SET @Where = @WhereFixed
        IF @WhereUser <> ''
            SET @Where = @Where + ' AND (' + @WhereUser + ')'
        SET @sql = 'INSERT [#tmpTable]
                        SELECT ''T'' AS [_]
                              ,[T].[Id]
                            FROM [dbo].[Types] [T]
                                LEFT JOIN [#tmpOperations] [#] ON [#].[Id] = [T].[Id]
                            WHERE [#].[Id] IS NULL'
        SET @sql = @sql + @Where + '
                        UNION ALL
                            SELECT ''O'' AS [_]
                                  ,[T].[Id]
                                FROM [#tmpOperations] [T]
                                WHERE [T].[_] <> ''delete'''
        SET @sql = @sql + @Where
        CREATE TABLE [#tmpTable]([_] CHAR(1), [Id] tinyint)
        IF @_ IS NULL
            EXEC sp_executesql @sql
                               ,N'@F_Id tinyint,@U_Id tinyint,@S_Id tinyint
                               ,@F_Name nvarchar(25),@U_Name nvarchar(25),@S_Name nvarchar(25)
                               ,@F_AskLength bit,@U_AskLength bit,@S_AskLength bit
                               ,@F_AskDecimals bit,@U_AskDecimals bit,@S_AskDecimals bit
                               ,@F_AskPrimarykey bit,@U_AskPrimarykey bit,@S_AskPrimarykey bit
                               ,@F_AskAutoincrement bit,@U_AskAutoincrement bit,@S_AskAutoincrement bit
                               ,@F_AskFilterable bit,@U_AskFilterable bit,@S_AskFilterable bit
                               ,@F_AskGridable bit,@U_AskGridable bit,@S_AskGridable bit
                               ,@F_AskCodification bit,@U_AskCodification bit,@S_AskCodification bit
                               ,@F_IsLikeable bit,@U_IsLikeable bit,@S_IsLikeable bit
                               ,@F_IsActive bit,@U_IsActive bit,@S_IsActive bit,@PickerValue nvarchar(25)'
                           ,@F_Id = @W_F_Id
                           ,@U_Id = @W_U_Id
                           ,@S_Id = @W_S_Id
                           ,@F_Name = @W_F_Name
                           ,@U_Name = @W_U_Name
                           ,@S_Name = @W_S_Name
                           ,@F_AskLength = @W_F_AskLength
                           ,@U_AskLength = @W_U_AskLength
                           ,@S_AskLength = @W_S_AskLength
                           ,@F_AskDecimals = @W_F_AskDecimals
                           ,@U_AskDecimals = @W_U_AskDecimals
                           ,@S_AskDecimals = @W_S_AskDecimals
                           ,@F_AskPrimarykey = @W_F_AskPrimarykey
                           ,@U_AskPrimarykey = @W_U_AskPrimarykey
                           ,@S_AskPrimarykey = @W_S_AskPrimarykey
                           ,@F_AskAutoincrement = @W_F_AskAutoincrement
                           ,@U_AskAutoincrement = @W_U_AskAutoincrement
                           ,@S_AskAutoincrement = @W_S_AskAutoincrement
                           ,@F_AskFilterable = @W_F_AskFilterable
                           ,@U_AskFilterable = @W_U_AskFilterable
                           ,@S_AskFilterable = @W_S_AskFilterable
                           ,@F_AskGridable = @W_F_AskGridable
                           ,@U_AskGridable = @W_U_AskGridable
                           ,@S_AskGridable = @W_S_AskGridable
                           ,@F_AskCodification = @W_F_AskCodification
                           ,@U_AskCodification = @W_U_AskCodification
                           ,@S_AskCodification = @W_S_AskCodification
                           ,@F_IsLikeable = @W_F_IsLikeable
                           ,@U_IsLikeable = @W_U_IsLikeable
                           ,@S_IsLikeable = @W_S_IsLikeable
                           ,@F_IsActive = @W_F_IsActive
                           ,@U_IsActive = @W_U_IsActive
                           ,@S_IsActive = @W_S_IsActive
                           ,@PickerValue = @PickerValue
        ELSE
            EXEC sp_executesql @sql

        DECLARE @RowCount INT = @@ROWCOUNT
               ,@OffSet INT

        CREATE UNIQUE INDEX [#tmpTable] ON [#tmpTable]([Id])
        IF @RowCount = 0 OR ISNULL(@PageNumber, 0) = 0 OR ISNULL(@LimitRows, 0) <= 0 BEGIN
            SET @OffSet = 0
            SET @LimitRows = CASE WHEN @RowCount = 0 THEN 1 ELSE @RowCount END
            SET @PageNumber = 1
            SET @MaxPage = 1
        END ELSE BEGIN
            SET @MaxPage = @RowCount / @LimitRows + CASE WHEN @RowCount % @LimitRows = 0 THEN 0 ELSE 1 END
            IF ABS(@PageNumber) > @MaxPage
                SET @PageNumber = CASE WHEN @PageNumber < 0 THEN -@MaxPage ELSE @MaxPage END
            IF @PageNumber < 0
                SET @PageNumber = @MaxPage - ABS(@PageNumber) + 1
            SET @OffSet = (@PageNumber - 1) * @LimitRows
            IF @PaddingGridLastPage = 1 AND @OffSet + @LimitRows > @RowCount
                SET @OffSet = CASE WHEN @RowCount > @LimitRows THEN @RowCount - @LimitRows ELSE 0 END
        END
        SELECT TOP 0 CAST(NULL AS NVARCHAR(50)) AS [Kind]
                    ,CAST(NULL AS tinyint) AS [Id]
                    ,CAST(NULL AS tinyint) AS [CategoryId]
                    ,CAST(NULL AS nvarchar(25)) AS [Name]
                    ,CAST(NULL AS int) AS [MaxLength]
                    ,CAST(NULL AS nvarchar(max)) AS [Minimum]
                    ,CAST(NULL AS nvarchar(max)) AS [Maximum]
                    ,CAST(NULL AS bit) AS [AskLength]
                    ,CAST(NULL AS bit) AS [AskDecimals]
                    ,CAST(NULL AS bit) AS [AskPrimarykey]
                    ,CAST(NULL AS bit) AS [AskAutoincrement]
                    ,CAST(NULL AS bit) AS [AskFilterable]
                    ,CAST(NULL AS bit) AS [AskGridable]
                    ,CAST(NULL AS bit) AS [AskCodification]
                    ,CAST(NULL AS bit) AS [IsLikeable]
                    ,CAST(NULL AS bit) AS [IsActive]
            INTO [#result]
        SET @sql = 'INSERT #result
                        SELECT ''Type'' AS [Kind]
                              ,[T].[Id]
                              ,[T].[CategoryId]
                              ,[T].[Name]
                              ,[T].[MaxLength]
                              ,[T].[Minimum]
                              ,[T].[Maximum]
                              ,[T].[AskLength]
                              ,[T].[AskDecimals]
                              ,[T].[AskPrimarykey]
                              ,[T].[AskAutoincrement]
                              ,[T].[AskFilterable]
                              ,[T].[AskGridable]
                              ,[T].[AskCodification]
                              ,[T].[IsLikeable]
                              ,[T].[IsActive]
                            FROM [#tmpTable] [#]
                                INNER JOIN [dbo].[Types] [T] ON [T].[Id] = [#].[Id]
                            WHERE [#].[_] = ''T''
                        UNION ALL
                            SELECT ''Type'' AS [Kind]
                                  ,[O].[Id]
                                  ,[O].[CategoryId]
                                  ,[O].[Name]
                                  ,[O].[MaxLength]
                                  ,[O].[Minimum]
                                  ,[O].[Maximum]
                                  ,[O].[AskLength]
                                  ,[O].[AskDecimals]
                                  ,[O].[AskPrimarykey]
                                  ,[O].[AskAutoincrement]
                                  ,[O].[AskFilterable]
                                  ,[O].[AskGridable]
                                  ,[O].[AskCodification]
                                  ,[O].[IsLikeable]
                                  ,[O].[IsActive]
                                FROM [#tmpTable] [#]
                                    INNER JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id]
                                WHERE [#].[_] = ''O''
                        ORDER BY ' + @OrderBy + '
                        OFFSET ' + CAST(@offset AS NVARCHAR(20)) + ' ROWS
                        FETCH NEXT ' + CAST(@LimitRows AS NVARCHAR(20)) + ' ROWS ONLY'
        EXEC sp_executesql @sql
        SELECT DISTINCT 'Category' AS [Kind]
              ,[R].[Id]
              ,[R].[Name]
              ,[R].[HtmlInputType]
              ,[R].[HtmlInputAlign]
              ,[R].[AskEncrypted]
              ,[R].[AskMask]
              ,[R].[AskListable]
              ,[R].[AskDefault]
              ,[R].[AskMinimum]
              ,[R].[AskMaximum]
              ,[R].[AskInWords]
            INTO [#Categories]
            FROM [#result] [T]
                INNER JOIN [dbo].[Categories] [R] ON [R].[Id] = [T].[CategoryId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Categories] ON [#Categories](Id)
        SELECT (SELECT [Kind]
                      ,[Id]
                      ,[CategoryId]
                      ,[Name]
                      ,[Name] AS [ListItemValue]
                      ,[MaxLength]
                      ,[Minimum]
                      ,[Maximum]
                      ,[AskLength]
                      ,[AskDecimals]
                      ,[AskPrimarykey]
                      ,[AskAutoincrement]
                      ,[AskFilterable]
                      ,[AskGridable]
                      ,[AskCodification]
                      ,[IsLikeable]
                      ,[IsActive]
                    FROM [#result] FOR JSON PATH) AS [result]
              ,ISNULL((SELECT [Categories].* FROM [#Categories] AS [Categories] FOR JSON PATH), '[]') AS [Categories]
        SET @ReturnValue = @RowCount

    RETURN 0
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[MaskValidate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[MaskValidate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[MaskValidate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[MaskValidate](@SessionId BIGINT
                                               ,@TransactionId BIGINT
                                               ,@UserName NVARCHAR(25)
                                               ,@Action NVARCHAR(15)
                                               ,@LastRecord NVARCHAR(max)
                                               ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED
    IF @SessionId IS NULL
            THROW 51000, 'Valor de @SessionId é requerido', 1
        IF @UserName IS NULL
            THROW 51000, 'Valor de @UserName é requerido', 1
        IF @Action IS NULL
            THROW 51000, 'Valor de @Action é requerido', 1
        IF @Action NOT IN ('create', 'update', 'delete')
            THROW 51000, 'Valor de @Action é inválido', 1
        IF @Action = 'delete' BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
        END ELSE BEGIN
            IF @ActualRecord IS NULL
                THROW 51000, 'Valor de @ActualRecord é requerido', 1
            IF ISJSON(@ActualRecord) = 0
                THROW 51000, 'Valor de @ActualRecord não está no formato JSON', 1
        END
        IF @TransactionId IS NULL
            THROW 51000, 'Valor de @TransactionId é requerido', 1
        DECLARE @IsConfirmed BIT
               ,@CreatedBy NVARCHAR(25)
               ,@IsPendingCreate BIT = 0
               ,@W_Id AS bigint

        IF @Action = 'delete'
            SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)
        ELSE
            SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        SELECT @IsConfirmed = [IsConfirmed]
              ,@CreatedBy = [CreatedBy]
            FROM [dbo].[Transactions]
            WHERE [Id] = @TransactionId
                  AND [SessionId] = @SessionId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Transação inexistente', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Transação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1;
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @W_Id IS NULL BEGIN
            SET @ErrorMessage = 'Valor de Id em @ActualRecord é requerido.';
            THROW 51000, @ErrorMessage, 1
        END
        IF EXISTS(SELECT 1 FROM [dbo].[Masks] WHERE [Id] = @W_Id) BEGIN
            IF @Action = 'create'
                THROW 51000, 'Chave-primária já existe em Masks', 1
        END ELSE IF @Action = 'delete' AND EXISTS(SELECT 1
                                    FROM [dbo].[Operations]
                                    WHERE [TransactionId] = @TransactionId
                                          AND [TableName] = 'Masks'
                                          AND [IsConfirmed] IS NULL
                                          AND [Action] = 'create'
                                          AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id)
            SET @IsPendingCreate = 1
        ELSE IF @Action <> 'create'
            THROW 51000, 'Chave-primária não existe em Masks', 1
        IF @Action <> 'create' AND @IsPendingCreate = 0 BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
            IF NOT EXISTS(SELECT 1
                            FROM [dbo].[Masks]
                            WHERE [Id] = JSON_VALUE(@LastRecord, '$.Id')
                                  AND [Name] = JSON_VALUE(@LastRecord, '$.Name')
                                  AND [Mask] = JSON_VALUE(@LastRecord, '$.Mask'))
            AND NOT EXISTS(SELECT 1
                            FROM [dbo].[Operations]
                            WHERE [TransactionId] = @TransactionId
                                  AND [TableName] = 'Masks'
                                  AND [IsConfirmed] IS NULL
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') = JSON_VALUE(@LastRecord, '$.Id')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Name') = JSON_VALUE(@LastRecord, '$.Name')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Mask') = JSON_VALUE(@LastRecord, '$.Mask'))
                THROW 51000, 'Registro de Masks alterado por outro usuário', 1
        END

        IF @Action = 'delete' BEGIN
            IF EXISTS(SELECT 1 FROM [dbo].[Domains] WHERE [MaskId] = @W_Id)
                THROW 51000, 'Chave-primária referenciada em Domains', 1
        END
        IF @Action IN ('create', 'update') BEGIN

            DECLARE @W_Name nvarchar(25) = CAST(JSON_VALUE(@ActualRecord, '$.Name') AS nvarchar(25))
                   ,@W_Mask nvarchar(max) = CAST(JSON_VALUE(@ActualRecord, '$.Mask') AS nvarchar(max))

            IF @W_Name IS NULL
                THROW 51000, 'Valor de Name em @ActualRecord é requerido.', 1
            IF @W_Mask IS NULL
                THROW 51000, 'Valor de Mask em @ActualRecord é requerido.', 1
            IF @Action = 'create' BEGIN
                IF EXISTS(SELECT 1 FROM [dbo].[Masks] WHERE [Name] = @W_Name)
                    THROW 51000, 'Chave única de UNQ_Masks_Name já existe', 1
            ELSE IF EXISTS(SELECT 1 FROM [dbo].[Masks] WHERE [Name] = @W_Name AND [Id] <> @W_Id)
                THROW 51000, 'Chave única de UNQ_Masks_Name já existe', 1
            END
        END

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[MaskPersist]
**********************************************************************************/
IF(SELECT object_id('[dbo].[MaskPersist]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[MaskPersist] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[MaskPersist](@Login NVARCHAR(MAX)
                                              ,@TransactionId BIGINT
                                              ,@Action NVARCHAR(15)
                                              ,@LastRecord NVARCHAR(max)
                                              ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(255)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    DECLARE @OperationId BIGINT
               ,@CreatedBy NVARCHAR(25)
               ,@ActionAux NVARCHAR(15)
               ,@IsConfirmed BIT
           ,@W_Id bigint

    IF @Action = 'delete'
        SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)
    ELSE
        SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

    IF @Action = 'create' AND @W_Id IS NULL BEGIN
        SELECT @W_Id = CAST(JSON_VALUE([ActualRecord], '$.Id') AS bigint)
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Masks'
                  AND [Action] = 'create'
                  AND [IsConfirmed] IS NULL
        IF @W_Id IS NULL BEGIN
            DECLARE @NewId BIGINT
    EXEC [dbo].[NewId] 'crudex', 'crudex', 'Masks', @NewId OUT
            SET @W_Id = CAST(@NewId AS bigint)
        END
        SET @ActualRecord = JSON_MODIFY(@ActualRecord, '$.Id', @W_Id)
    END

    EXEC @TransactionId = [dbo].[MaskValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        SELECT @OperationId = [Id]
              ,@CreatedBy = [CreatedBy]
              ,@ActionAux = [Action]
              ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Masks'
                  AND [IsConfirmed] IS NULL
                  AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id
        IF @@ROWCOUNT = 0 BEGIN
            EXEC [dbo].[NewOperationId] 'crudex', 'crudex', @OperationId OUT
            INSERT INTO [dbo].[Operations] ([Id]
                                             ,[TransactionId]
                                             ,[TableName]
                                             ,[Action]
                                             ,[LastRecord]
                                             ,[ActualRecord]
                                             ,[IsConfirmed]
                                             ,[CreatedAt]
                                             ,[CreatedBy])
                                       VALUES(@OperationId
                                             ,@TransactionId
                                             ,'Masks'
                                             ,@Action
                                             ,@LastRecord
                                             ,@ActualRecord
                                             ,NULL
                                             ,GETDATE()
                                             ,@UserName)
        END ELSE IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END ELSE IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        ELSE IF @ActionAux = 'delete'
            THROW 51000, 'Registro excluído nesta transação', 1
        ELSE IF @Action = 'create' BEGIN
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END
        ELSE IF @Action = 'update' BEGIN
            IF @ActionAux = 'create'
                EXEC [dbo].[MaskValidate] @SessionId, @TransactionId, @UserName, 'create', NULL, @ActualRecord
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END ELSE IF @ActionAux = 'create' BEGIN
            UPDATE [dbo].[Operations] 
                SET [IsConfirmed] = 0
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END ELSE BEGIN
            UPDATE [dbo].[Operations]
                SET [Action] = 'delete'
                   ,[LastRecord] = @LastRecord
                   ,[ActualRecord] = NULL
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END

    RETURN CAST(@OperationId AS BIGINT)
END
GO

