               ,@W_Mask nvarchar(max) = CAST(JSON_VALUE(@ActualRecord, '$.Mask') AS nvarchar(max))

        INSERT INTO [dbo].[Masks] ([Id]
                                            ,[Name]
                                            ,[Mask]
                                            ,[CreatedAt]
                                            ,[CreatedBy])
                                      VALUES (@W_Id
                                             ,@W_Name
                                             ,@W_Mask
                                             ,GETDATE()
                                             ,@UserName)
        UPDATE [dbo].[Operations]
            SET [IsConfirmed] = 1
                ,[UpdatedAt] = GETDATE()
                ,[UpdatedBy] = @UserName
            WHERE [Id] = @OperationId

    RETURN @TransactionId
END
