/**********************************************************************************
Criar stored procedure [dbo].[DomainsRead]
**********************************************************************************/
IF(SELECT object_id('[dbo].[DomainsRead]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[DomainsRead] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[DomainsRead](@Login NVARCHAR(MAX)
                                          ,@RecordFilter NVARCHAR(MAX)
                                          ,@OrderBy NVARCHAR(MAX)
                                          ,@PaddingGridLastPage BIT
                                          ,@IsActionList BIT
                                          ,@PageNumber INT OUT
                                          ,@LimitRows INT OUT
                                          ,@MaxPage INT OUT
                                          ,@ReturnValue BIGINT OUT) AS BEGIN

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @LoginId BIGINT
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @LoginId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @LoginId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    IF @RecordFilter IS NULL
            SET @RecordFilter = '{}'
        ELSE IF ISJSON(@RecordFilter) = 0
            THROW 51000, 'Valor de @RecordFilter não está no formato JSON', 1
        SET @OrderBy = TRIM(ISNULL(@OrderBy, ''))
        IF @OrderBy = ''
            SET @OrderBy = '[Id]'
        ELSE BEGIN
            SET @OrderBy = REPLACE(REPLACE(@OrderBy, '[', ''), ']', '')
            IF EXISTS(SELECT 1 
                         FROM (SELECT CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                           WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                           ELSE TRIM([value])
                                      END AS [ColumnName]
                                  FROM STRING_SPLIT(@OrderBy, ',')) AS [O]
                                      LEFT JOIN (SELECT [#1].[name] AS ColumnName
                                                    FROM [sys].[columns] [#1]
                                                        INNER JOIN [sys].[tables] [#2] ON [#1].[object_id] = [#2].[object_id]
                                                    WHERE [#2].[name] = 'Domains') AS [T] ON [T].[ColumnName] = [O].[ColumnName]
                         WHERE [T].[ColumnName] IS NULL)
                THROW 51000, 'Nome de coluna em @OrderBy é inválido', 1
            SELECT @OrderBy = STRING_AGG('[' + TRIM(CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                                         ELSE TRIM([value])
                                                    END) + '] ' + 
                                                    CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN 'DESC'
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN 'ASC'
                                                         ELSE 'ASC'
                                                    END, ', ')
                FROM STRING_SPLIT(@OrderBy, ',')
        END
        IF @IsActionList = 1
            SET @OrderBy = '[Name]'
        DECLARE @PickerValue nvarchar(25) = NULL

        DECLARE @TransactionId BIGINT = (SELECT MAX([Id]) FROM [dbo].[Transactions] WHERE [SessionId] = @LoginId)

        IF NOT EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [Id] = @TransactionId AND [IsConfirmed] IS NULL)
            SET @TransactionId = NULL
        SELECT [Action] AS [_]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) AS [Id]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.TypeId') AS tinyint) AS [TypeId]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.MaskId') AS bigint) AS [MaskId]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Name') AS nvarchar(25)) AS [Name]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Length') AS smallint) AS [Length]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Decimals') AS tinyint) AS [Decimals]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.ValidValues') AS nvarchar(max)) AS [ValidValues]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Default') AS nvarchar(max)) AS [Default]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Minimum') AS nvarchar(max)) AS [Minimum]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Maximum') AS nvarchar(max)) AS [Maximum]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Codification') AS nvarchar(5)) AS [Codification]
            INTO [#tmpOperations]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Domains'
                  AND [IsConfirmed] IS NULL
        CREATE UNIQUE INDEX [#tmpOperations] ON [#tmpOperations]([Id])

        DECLARE @_ NVARCHAR(MAX) = (SELECT STRING_AGG(value, ',') FROM OPENJSON(@RecordFilter, '$.Filter._'))
               ,@WhereFixed NVARCHAR(MAX) = ''
               ,@WhereFilter NVARCHAR(MAX) = ''
               ,@WhereSearch NVARCHAR(MAX) = ''
               ,@WhereUser NVARCHAR(MAX) = ''
               ,@Where NVARCHAR(MAX) = ''
               ,@sql NVARCHAR(MAX)

        DECLARE @W_F_Id bigint = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.Id') AS bigint)
               ,@W_U_Id bigint = CAST(JSON_VALUE(@RecordFilter, '$.Filter.Id') AS bigint)
               ,@W_S_Id bigint = CAST(JSON_VALUE(@RecordFilter, '$.Search.Id') AS bigint)
               ,@W_F_TypeId tinyint = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.TypeId') AS tinyint)
               ,@W_U_TypeId tinyint = CAST(JSON_VALUE(@RecordFilter, '$.Filter.TypeId') AS tinyint)
               ,@W_S_TypeId tinyint = CAST(JSON_VALUE(@RecordFilter, '$.Search.TypeId') AS tinyint)
               ,@W_F_MaskId bigint = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.MaskId') AS bigint)
               ,@W_U_MaskId bigint = CAST(JSON_VALUE(@RecordFilter, '$.Filter.MaskId') AS bigint)
               ,@W_S_MaskId bigint = CAST(JSON_VALUE(@RecordFilter, '$.Search.MaskId') AS bigint)
               ,@W_F_Name nvarchar(25) = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.Name') AS nvarchar(25))
               ,@W_U_Name nvarchar(25) = CAST(JSON_VALUE(@RecordFilter, '$.Filter.Name') AS nvarchar(25))
               ,@W_S_Name nvarchar(25) = CAST(JSON_VALUE(@RecordFilter, '$.Search.Name') AS nvarchar(25))
               ,@W_F_ValidValues nvarchar(max) = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.ValidValues') AS nvarchar(max))
               ,@W_U_ValidValues nvarchar(max) = CAST(JSON_VALUE(@RecordFilter, '$.Filter.ValidValues') AS nvarchar(max))
               ,@W_S_ValidValues nvarchar(max) = CAST(JSON_VALUE(@RecordFilter, '$.Search.ValidValues') AS nvarchar(max))
               ,@W_F_Codification nvarchar(5) = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.Codification') AS nvarchar(5))
               ,@W_U_Codification nvarchar(5) = CAST(JSON_VALUE(@RecordFilter, '$.Filter.Codification') AS nvarchar(5))
               ,@W_S_Codification nvarchar(5) = CAST(JSON_VALUE(@RecordFilter, '$.Search.Codification') AS nvarchar(5))

        IF @W_F_Id IS NOT NULL BEGIN
            IF @W_F_Id < CAST('1' AS bigint)
                THROW 51000, 'Valor de Id deve ser maior que ou igual a ''1''', 1
            SET @WhereFixed = @WhereFixed + ' AND [T].[Id] = @F_Id'
        END
        IF @W_F_TypeId IS NOT NULL BEGIN
            IF @W_F_TypeId < CAST('1' AS tinyint)
                THROW 51000, 'Valor de TypeId deve ser maior que ou igual a ''1''', 1
            SET @WhereFixed = @WhereFixed + ' AND [T].[TypeId] = @F_TypeId'
        END
        IF @W_F_MaskId IS NOT NULL BEGIN
            SET @WhereFixed = @WhereFixed + ' AND [T].[MaskId] = @F_MaskId'
        END
        IF @W_F_Name IS NOT NULL BEGIN
            SET @WhereFixed = @WhereFixed + ' AND [T].[Name] = @F_Name'
        END
        IF @W_F_ValidValues IS NOT NULL BEGIN
            SET @WhereFixed = @WhereFixed + ' AND [T].[ValidValues] = @F_ValidValues'
        END
        IF @W_F_Codification IS NOT NULL BEGIN
            SET @WhereFixed = @WhereFixed + ' AND [T].[Codification] = @F_Codification'
        END
        IF @IsActionList = 1 BEGIN
            SET @PickerValue = CAST(JSON_VALUE(@RecordFilter, '$.Picker.Value') AS nvarchar(25))
            IF @PickerValue IS NULL
                SET @PickerValue = ''
            SET @WhereUser = '[T].[Name] LIKE ''%'' + @PickerValue + ''%'''
        END ELSE BEGIN
        IF @_ IS NULL BEGIN
            IF @W_U_Id IS NOT NULL BEGIN
                IF @W_U_Id < CAST('1' AS bigint)
                    THROW 51000, 'Valor de Id deve ser maior que ou igual a ''1''', 1
                SET @WhereFilter = @WhereFilter + ' AND [T].[Id] = @U_Id'
            END
            IF @W_U_TypeId IS NOT NULL BEGIN
                IF @W_U_TypeId < CAST('1' AS tinyint)
                    THROW 51000, 'Valor de TypeId deve ser maior que ou igual a ''1''', 1
                SET @WhereFilter = @WhereFilter + ' AND [T].[TypeId] = @U_TypeId'
            END
            IF @W_U_MaskId IS NOT NULL BEGIN
                SET @WhereFilter = @WhereFilter + ' AND [T].[MaskId] = @U_MaskId'
            END
            IF @W_U_Name IS NOT NULL BEGIN
                SET @WhereFilter = @WhereFilter + ' AND [T].[Name] = @U_Name'
            END
            IF @W_U_ValidValues IS NOT NULL BEGIN
                SET @WhereFilter = @WhereFilter + ' AND [T].[ValidValues] = @U_ValidValues'
            END
            IF @W_U_Codification IS NOT NULL BEGIN
                SET @WhereFilter = @WhereFilter + ' AND [T].[Codification] = @U_Codification'
            END
            IF @W_S_Id IS NOT NULL BEGIN
                IF @W_S_Id < CAST('1' AS bigint)
                    THROW 51000, 'Valor de Id deve ser maior que ou igual a ''1''', 1
                SET @WhereSearch = @WhereSearch + ' AND [T].[Id] = @S_Id'
            END
            IF @W_S_TypeId IS NOT NULL BEGIN
                IF @W_S_TypeId < CAST('1' AS tinyint)
                    THROW 51000, 'Valor de TypeId deve ser maior que ou igual a ''1''', 1
                SET @WhereSearch = @WhereSearch + ' AND [T].[TypeId] = @S_TypeId'
            END
            IF @W_S_MaskId IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[MaskId] = @S_MaskId'
            END
            IF @W_S_Name IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[Name] = @S_Name'
            END
            IF @W_S_ValidValues IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[ValidValues] = @S_ValidValues'
            END
            IF @W_S_Codification IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[Codification] = @S_Codification'
            END
            IF @WhereFilter <> '' AND @WhereSearch <> ''
                SET @WhereUser = '(' + STUFF(@WhereFilter, 1, 5, '') + ') OR (' + STUFF(@WhereSearch, 1, 5, '') + ')'
            ELSE IF @WhereFilter <> ''
                SET @WhereUser = STUFF(@WhereFilter, 1, 5, '')
            ELSE IF @WhereSearch <> ''
                SET @WhereUser = STUFF(@WhereSearch, 1, 5, '')
        END ELSE
            SET @WhereUser = '[T].[Id] IN (' + @_ + ')'
        END
        SET @Where = @WhereFixed
        IF @WhereUser <> ''
            SET @Where = @Where + ' AND (' + @WhereUser + ')'
        SET @sql = 'INSERT [#tmpTable]
                        SELECT ''T'' AS [_]
                              ,[T].[Id]
                            FROM [dbo].[Domains] [T]
                                LEFT JOIN [#tmpOperations] [#] ON [#].[Id] = [T].[Id]
                            WHERE [#].[Id] IS NULL'
        SET @sql = @sql + @Where + '
                        UNION ALL
                            SELECT ''O'' AS [_]
                                  ,[T].[Id]
                                FROM [#tmpOperations] [T]
                                WHERE [T].[_] <> ''delete'''
        SET @sql = @sql + @Where
        CREATE TABLE [#tmpTable]([_] CHAR(1), [Id] bigint)
        IF @_ IS NULL
            EXEC sp_executesql @sql
                               ,N'@F_Id bigint,@U_Id bigint,@S_Id bigint
                               ,@F_TypeId tinyint,@U_TypeId tinyint,@S_TypeId tinyint
                               ,@F_MaskId bigint,@U_MaskId bigint,@S_MaskId bigint
                               ,@F_Name nvarchar(25),@U_Name nvarchar(25),@S_Name nvarchar(25)
                               ,@F_ValidValues nvarchar(max),@U_ValidValues nvarchar(max),@S_ValidValues nvarchar(max)
                               ,@F_Codification nvarchar(5),@U_Codification nvarchar(5),@S_Codification nvarchar(5),@PickerValue nvarchar(25)'
                           ,@F_Id = @W_F_Id
                           ,@U_Id = @W_U_Id
                           ,@S_Id = @W_S_Id
                           ,@F_TypeId = @W_F_TypeId
                           ,@U_TypeId = @W_U_TypeId
                           ,@S_TypeId = @W_S_TypeId
                           ,@F_MaskId = @W_F_MaskId
                           ,@U_MaskId = @W_U_MaskId
                           ,@S_MaskId = @W_S_MaskId
                           ,@F_Name = @W_F_Name
                           ,@U_Name = @W_U_Name
                           ,@S_Name = @W_S_Name
                           ,@F_ValidValues = @W_F_ValidValues
                           ,@U_ValidValues = @W_U_ValidValues
                           ,@S_ValidValues = @W_S_ValidValues
                           ,@F_Codification = @W_F_Codification
                           ,@U_Codification = @W_U_Codification
                           ,@S_Codification = @W_S_Codification
                           ,@PickerValue = @PickerValue
        ELSE
            EXEC sp_executesql @sql

        DECLARE @RowCount INT = @@ROWCOUNT
               ,@OffSet INT

        CREATE UNIQUE INDEX [#tmpTable] ON [#tmpTable]([Id])
        IF @RowCount = 0 OR ISNULL(@PageNumber, 0) = 0 OR ISNULL(@LimitRows, 0) <= 0 BEGIN
            SET @OffSet = 0
            SET @LimitRows = CASE WHEN @RowCount = 0 THEN 1 ELSE @RowCount END
            SET @PageNumber = 1
            SET @MaxPage = 1
        END ELSE BEGIN
            SET @MaxPage = @RowCount / @LimitRows + CASE WHEN @RowCount % @LimitRows = 0 THEN 0 ELSE 1 END
            IF ABS(@PageNumber) > @MaxPage
                SET @PageNumber = CASE WHEN @PageNumber < 0 THEN -@MaxPage ELSE @MaxPage END
            IF @PageNumber < 0
                SET @PageNumber = @MaxPage - ABS(@PageNumber) + 1
            SET @OffSet = (@PageNumber - 1) * @LimitRows
            IF @PaddingGridLastPage = 1 AND @OffSet + @LimitRows > @RowCount
                SET @OffSet = CASE WHEN @RowCount > @LimitRows THEN @RowCount - @LimitRows ELSE 0 END
        END
        SELECT TOP 0 CAST(NULL AS NVARCHAR(50)) AS [Kind]
                    ,CAST(NULL AS bigint) AS [Id]
                    ,CAST(NULL AS tinyint) AS [TypeId]
                    ,CAST(NULL AS bigint) AS [MaskId]
                    ,CAST(NULL AS nvarchar(25)) AS [Name]
                    ,CAST(NULL AS smallint) AS [Length]
                    ,CAST(NULL AS tinyint) AS [Decimals]
                    ,CAST(NULL AS nvarchar(max)) AS [ValidValues]
                    ,CAST(NULL AS nvarchar(max)) AS [Default]
                    ,CAST(NULL AS nvarchar(max)) AS [Minimum]
                    ,CAST(NULL AS nvarchar(max)) AS [Maximum]
                    ,CAST(NULL AS nvarchar(5)) AS [Codification]
            INTO [#result]
        SET @sql = 'INSERT #result
                        SELECT ''Domain'' AS [Kind]
                              ,[T].[Id]
                              ,[T].[TypeId]
                              ,[T].[MaskId]
                              ,[T].[Name]
                              ,[T].[Length]
                              ,[T].[Decimals]
                              ,[T].[ValidValues]
                              ,[T].[Default]
                              ,[T].[Minimum]
                              ,[T].[Maximum]
                              ,[T].[Codification]
                            FROM [#tmpTable] [#]
                                INNER JOIN [dbo].[Domains] [T] ON [T].[Id] = [#].[Id]
                            WHERE [#].[_] = ''T''
                        UNION ALL
                            SELECT ''Domain'' AS [Kind]
                                  ,[O].[Id]
                                  ,[O].[TypeId]
                                  ,[O].[MaskId]
                                  ,[O].[Name]
                                  ,[O].[Length]
                                  ,[O].[Decimals]
                                  ,[O].[ValidValues]
                                  ,[O].[Default]
                                  ,[O].[Minimum]
                                  ,[O].[Maximum]
                                  ,[O].[Codification]
                                FROM [#tmpTable] [#]
                                    INNER JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id]
                                WHERE [#].[_] = ''O''
                        ORDER BY ' + @OrderBy + '
                        OFFSET ' + CAST(@offset AS NVARCHAR(20)) + ' ROWS
                        FETCH NEXT ' + CAST(@LimitRows AS NVARCHAR(20)) + ' ROWS ONLY'
        EXEC sp_executesql @sql
        SELECT DISTINCT 'Type' AS [Kind]
              ,[R].[Id]
              ,[R].[CategoryId]
              ,[R].[Name]
              ,[R].[MaxLength]
              ,[R].[Minimum]
              ,[R].[Maximum]
              ,[R].[AskLength]
              ,[R].[AskDecimals]
              ,[R].[AskPrimarykey]
              ,[R].[AskAutoincrement]
              ,[R].[AskFilterable]
              ,[R].[AskGridable]
              ,[R].[AskCodification]
              ,[R].[IsLikeable]
              ,[R].[IsActive]
            INTO [#Types]
            FROM [#result] [T]
                INNER JOIN [dbo].[Types] [R] ON [R].[Id] = [T].[TypeId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Types] ON [#Types](Id)
        SELECT DISTINCT 'Category' AS [Kind]
              ,[R].[Id]
              ,[R].[Name]
              ,[R].[HtmlInputType]
              ,[R].[HtmlInputAlign]
              ,[R].[AskEncrypted]
              ,[R].[AskMask]
              ,[R].[AskListable]
              ,[R].[AskDefault]
              ,[R].[AskMinimum]
              ,[R].[AskMaximum]
              ,[R].[AskInWords]
            INTO [#Categories]
            FROM [#Types] [T]
                INNER JOIN [dbo].[Categories] [R] ON [R].[Id] = [T].[CategoryId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Categories] ON [#Categories](Id)
        SELECT DISTINCT 'Mask' AS [Kind]
              ,[R].[Id]
              ,[R].[Name]
              ,[R].[Mask]
            INTO [#Masks]
            FROM [#result] [T]
                INNER JOIN [dbo].[Masks] [R] ON [R].[Id] = [T].[MaskId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Masks] ON [#Masks](Id)
        SELECT (SELECT [Kind]
                      ,[Id]
                      ,[TypeId]
                      ,[MaskId]
                      ,[Name]
                      ,[Name] AS [ListItemValue]
                      ,[Length]
                      ,[Decimals]
                      ,[ValidValues]
                      ,[Default]
                      ,[Minimum]
                      ,[Maximum]
                      ,[Codification]
                    FROM [#result] FOR JSON PATH) AS [result]
              ,ISNULL((SELECT [Types].* FROM [#Types] AS [Types] FOR JSON PATH), '[]') AS [Types]
              ,ISNULL((SELECT [Categories].* FROM [#Categories] AS [Categories] FOR JSON PATH), '[]') AS [Categories]
              ,ISNULL((SELECT [Masks].* FROM [#Masks] AS [Masks] FOR JSON PATH), '[]') AS [Masks]
        SET @ReturnValue = @RowCount

    RETURN 0
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[SystemValidate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[SystemValidate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[SystemValidate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[SystemValidate](@SessionId BIGINT
                                               ,@TransactionId BIGINT
                                               ,@UserName NVARCHAR(25)
                                               ,@Action NVARCHAR(15)
                                               ,@LastRecord NVARCHAR(max)
                                               ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED
    IF @SessionId IS NULL
            THROW 51000, 'Valor de @SessionId é requerido', 1
        IF @UserName IS NULL
            THROW 51000, 'Valor de @UserName é requerido', 1
        IF @Action IS NULL
            THROW 51000, 'Valor de @Action é requerido', 1
        IF @Action NOT IN ('create', 'update', 'delete')
            THROW 51000, 'Valor de @Action é inválido', 1
        IF @Action = 'delete' BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
        END ELSE BEGIN
            IF @ActualRecord IS NULL
                THROW 51000, 'Valor de @ActualRecord é requerido', 1
            IF ISJSON(@ActualRecord) = 0
                THROW 51000, 'Valor de @ActualRecord não está no formato JSON', 1
        END
        IF @TransactionId IS NULL
            THROW 51000, 'Valor de @TransactionId é requerido', 1
        DECLARE @IsConfirmed BIT
               ,@CreatedBy NVARCHAR(25)
               ,@IsPendingCreate BIT = 0
               ,@W_Id AS bigint

        IF @Action = 'delete'
            SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)
        ELSE
            SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        SELECT @IsConfirmed = [IsConfirmed]
              ,@CreatedBy = [CreatedBy]
            FROM [dbo].[Transactions]
            WHERE [Id] = @TransactionId
                  AND [SessionId] = @SessionId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Transação inexistente', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Transação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1;
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @W_Id IS NULL BEGIN
            SET @ErrorMessage = 'Valor de Id em @ActualRecord é requerido.';
            THROW 51000, @ErrorMessage, 1
        END
        IF @W_Id < CAST('1' AS bigint)
            THROW 51000, 'Valor de Id em @ActualRecord deve ser maior que ou igual a 1', 1
        IF EXISTS(SELECT 1 FROM [dbo].[Systems] WHERE [Id] = @W_Id) BEGIN
            IF @Action = 'create'
                THROW 51000, 'Chave-primária já existe em Systems', 1
        END ELSE IF @Action = 'delete' AND EXISTS(SELECT 1
                                    FROM [dbo].[Operations]
                                    WHERE [TransactionId] = @TransactionId
                                          AND [TableName] = 'Systems'
                                          AND [IsConfirmed] IS NULL
                                          AND [Action] = 'create'
                                          AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id)
            SET @IsPendingCreate = 1
        ELSE IF @Action <> 'create'
            THROW 51000, 'Chave-primária não existe em Systems', 1
        IF @Action <> 'create' AND @IsPendingCreate = 0 BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
            IF NOT EXISTS(SELECT 1
                            FROM [dbo].[Systems]
                            WHERE [Id] = JSON_VALUE(@LastRecord, '$.Id')
                                  AND [Name] = JSON_VALUE(@LastRecord, '$.Name')
                                  AND [Description] = JSON_VALUE(@LastRecord, '$.Description')
                                  AND [ClientName] = JSON_VALUE(@LastRecord, '$.ClientName')
                                  AND [MaxRetryLogins] = JSON_VALUE(@LastRecord, '$.MaxRetryLogins')
                                  AND [IsOffAir] = JSON_VALUE(@LastRecord, '$.IsOffAir'))
            AND NOT EXISTS(SELECT 1
                            FROM [dbo].[Operations]
                            WHERE [TransactionId] = @TransactionId
                                  AND [TableName] = 'Systems'
                                  AND [IsConfirmed] IS NULL
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') = JSON_VALUE(@LastRecord, '$.Id')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Name') = JSON_VALUE(@LastRecord, '$.Name')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Description') = JSON_VALUE(@LastRecord, '$.Description')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.ClientName') = JSON_VALUE(@LastRecord, '$.ClientName')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.MaxRetryLogins') = JSON_VALUE(@LastRecord, '$.MaxRetryLogins')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsOffAir') = JSON_VALUE(@LastRecord, '$.IsOffAir'))
                THROW 51000, 'Registro de Systems alterado por outro usuário', 1
        END

        IF @Action = 'delete' BEGIN
            IF EXISTS(SELECT 1 FROM [dbo].[Menus] WHERE [SystemId] = @W_Id)
                THROW 51000, 'Chave-primária referenciada em Menus', 1
            IF EXISTS(SELECT 1 FROM [dbo].[SystemsUsers] WHERE [SystemId] = @W_Id)
                THROW 51000, 'Chave-primária referenciada em SystemsUsers', 1
            IF EXISTS(SELECT 1 FROM [dbo].[SystemsDatabases] WHERE [SystemId] = @W_Id)
                THROW 51000, 'Chave-primária referenciada em SystemsDatabases', 1
            IF EXISTS(SELECT 1 FROM [dbo].[Sessions] WHERE [SystemId] = @W_Id)
                THROW 51000, 'Chave-primária referenciada em Sessions', 1
        END
        IF @Action IN ('create', 'update') BEGIN

            DECLARE @W_Name nvarchar(25) = CAST(JSON_VALUE(@ActualRecord, '$.Name') AS nvarchar(25))
                   ,@W_Description nvarchar(50) = CAST(JSON_VALUE(@ActualRecord, '$.Description') AS nvarchar(50))
                   ,@W_ClientName nvarchar(15) = CAST(JSON_VALUE(@ActualRecord, '$.ClientName') AS nvarchar(15))
                   ,@W_MaxRetryLogins tinyint = CAST(JSON_VALUE(@ActualRecord, '$.MaxRetryLogins') AS tinyint)
                   ,@W_IsOffAir bit = CAST(JSON_VALUE(@ActualRecord, '$.IsOffAir') AS bit)

            IF @W_Name IS NULL
                THROW 51000, 'Valor de Name em @ActualRecord é requerido.', 1
            IF @W_Description IS NULL
                THROW 51000, 'Valor de Description em @ActualRecord é requerido.', 1
            IF @W_ClientName IS NULL
                THROW 51000, 'Valor de ClientName em @ActualRecord é requerido.', 1
            IF @W_MaxRetryLogins IS NULL
                THROW 51000, 'Valor de MaxRetryLogins em @ActualRecord é requerido.', 1
            IF @W_MaxRetryLogins < CAST('1' AS tinyint)
                THROW 51000, 'Valor de MaxRetryLogins em @ActualRecord deve ser maior que ou igual a 1', 1
            IF @W_IsOffAir IS NULL
                THROW 51000, 'Valor de IsOffAir em @ActualRecord é requerido.', 1
            IF @Action = 'create' BEGIN
                IF EXISTS(SELECT 1 FROM [dbo].[Systems] WHERE [Name] = @W_Name)
                    THROW 51000, 'Chave única de UNQ_Systems_Name já existe', 1
            ELSE IF EXISTS(SELECT 1 FROM [dbo].[Systems] WHERE [Name] = @W_Name AND [Id] <> @W_Id)
                THROW 51000, 'Chave única de UNQ_Systems_Name já existe', 1
            END
        END

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[SystemPersist]
**********************************************************************************/
IF(SELECT object_id('[dbo].[SystemPersist]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[SystemPersist] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[SystemPersist](@Login NVARCHAR(MAX)
                                              ,@TransactionId BIGINT
                                              ,@Action NVARCHAR(15)
                                              ,@LastRecord NVARCHAR(max)
                                              ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(255)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    DECLARE @OperationId BIGINT
               ,@CreatedBy NVARCHAR(25)
               ,@ActionAux NVARCHAR(15)
               ,@IsConfirmed BIT
           ,@W_Id bigint

    IF @Action = 'delete'
        SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)
    ELSE
        SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

    IF @Action = 'create' AND @W_Id IS NULL BEGIN
        SELECT @W_Id = CAST(JSON_VALUE([ActualRecord], '$.Id') AS bigint)
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Systems'
                  AND [Action] = 'create'
                  AND [IsConfirmed] IS NULL
        IF @W_Id IS NULL BEGIN
            DECLARE @NewId BIGINT
    EXEC [dbo].[NewId] 'crudex', 'crudex', 'Systems', @NewId OUT
            SET @W_Id = CAST(@NewId AS bigint)
        END
        SET @ActualRecord = JSON_MODIFY(@ActualRecord, '$.Id', @W_Id)
    END

    EXEC @TransactionId = [dbo].[SystemValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        SELECT @OperationId = [Id]
              ,@CreatedBy = [CreatedBy]
              ,@ActionAux = [Action]
              ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Systems'
                  AND [IsConfirmed] IS NULL
                  AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id
        IF @@ROWCOUNT = 0 BEGIN
            EXEC [dbo].[NewOperationId] 'crudex', 'crudex', @OperationId OUT
            INSERT INTO [dbo].[Operations] ([Id]
                                             ,[TransactionId]
                                             ,[TableName]
                                             ,[Action]
                                             ,[LastRecord]
                                             ,[ActualRecord]
                                             ,[IsConfirmed]
                                             ,[CreatedAt]
                                             ,[CreatedBy])
                                       VALUES(@OperationId
                                             ,@TransactionId
                                             ,'Systems'
                                             ,@Action
                                             ,@LastRecord
                                             ,@ActualRecord
                                             ,NULL
                                             ,GETDATE()
                                             ,@UserName)
        END ELSE IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END ELSE IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        ELSE IF @ActionAux = 'delete'
            THROW 51000, 'Registro excluído nesta transação', 1
        ELSE IF @Action = 'create' BEGIN
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END
        ELSE IF @Action = 'update' BEGIN
            IF @ActionAux = 'create'
                EXEC [dbo].[SystemValidate] @SessionId, @TransactionId, @UserName, 'create', NULL, @ActualRecord
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END ELSE IF @ActionAux = 'create' BEGIN
            UPDATE [dbo].[Operations] 
                SET [IsConfirmed] = 0
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END ELSE BEGIN
            UPDATE [dbo].[Operations]
                SET [Action] = 'delete'
                   ,[LastRecord] = @LastRecord
                   ,[ActualRecord] = NULL
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END

    RETURN CAST(@OperationId AS BIGINT)
END
GO

