/**********************************************************************************
Criar stored procedure [dbo].[UsersRead]
**********************************************************************************/
IF(SELECT object_id('[dbo].[UsersRead]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[UsersRead] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[UsersRead](@Login NVARCHAR(MAX)
                                          ,@RecordFilter NVARCHAR(MAX)
                                          ,@OrderBy NVARCHAR(MAX)
                                          ,@PaddingGridLastPage BIT
                                          ,@IsActionList BIT
                                          ,@PageNumber INT OUT
                                          ,@LimitRows INT OUT
                                          ,@MaxPage INT OUT
                                          ,@ReturnValue BIGINT OUT) AS BEGIN

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @LoginId BIGINT
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @LoginId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @LoginId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    IF @RecordFilter IS NULL
            SET @RecordFilter = '{}'
        ELSE IF ISJSON(@RecordFilter) = 0
            THROW 51000, 'Valor de @RecordFilter não está no formato JSON', 1
        SET @OrderBy = TRIM(ISNULL(@OrderBy, ''))
        IF @OrderBy = ''
            SET @OrderBy = '[Id]'
        ELSE BEGIN
            SET @OrderBy = REPLACE(REPLACE(@OrderBy, '[', ''), ']', '')
            IF EXISTS(SELECT 1 
                         FROM (SELECT CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                           WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                           ELSE TRIM([value])
                                      END AS [ColumnName]
                                  FROM STRING_SPLIT(@OrderBy, ',')) AS [O]
                                      LEFT JOIN (SELECT [#1].[name] AS ColumnName
                                                    FROM [sys].[columns] [#1]
                                                        INNER JOIN [sys].[tables] [#2] ON [#1].[object_id] = [#2].[object_id]
                                                    WHERE [#2].[name] = 'Users') AS [T] ON [T].[ColumnName] = [O].[ColumnName]
                         WHERE [T].[ColumnName] IS NULL)
                THROW 51000, 'Nome de coluna em @OrderBy é inválido', 1
            SELECT @OrderBy = STRING_AGG('[' + TRIM(CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                                         ELSE TRIM([value])
                                                    END) + '] ' + 
                                                    CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN 'DESC'
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN 'ASC'
                                                         ELSE 'ASC'
                                                    END, ', ')
                FROM STRING_SPLIT(@OrderBy, ',')
        END
        IF @IsActionList = 1
            SET @OrderBy = '[Name]'
        DECLARE @PickerValue nvarchar(25) = NULL

        DECLARE @TransactionId BIGINT = (SELECT MAX([Id]) FROM [dbo].[Transactions] WHERE [SessionId] = @LoginId)

        IF NOT EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [Id] = @TransactionId AND [IsConfirmed] IS NULL)
            SET @TransactionId = NULL
        SELECT [Action] AS [_]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) AS [Id]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Name') AS nvarchar(25)) AS [Name]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Password') AS nvarchar(256)) AS [Password]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.FullName') AS nvarchar(50)) AS [FullName]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.RetryLogins') AS tinyint) AS [RetryLogins]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsActive') AS bit) AS [IsActive]
            INTO [#tmpOperations]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Users'
                  AND [IsConfirmed] IS NULL
        CREATE UNIQUE INDEX [#tmpOperations] ON [#tmpOperations]([Id])

        DECLARE @_ NVARCHAR(MAX) = (SELECT STRING_AGG(value, ',') FROM OPENJSON(@RecordFilter, '$.Filter._'))
               ,@WhereFixed NVARCHAR(MAX) = ''
               ,@WhereFilter NVARCHAR(MAX) = ''
               ,@WhereSearch NVARCHAR(MAX) = ''
               ,@WhereUser NVARCHAR(MAX) = ''
               ,@Where NVARCHAR(MAX) = ''
               ,@sql NVARCHAR(MAX)

        DECLARE @W_F_Id bigint = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.Id') AS bigint)
               ,@W_U_Id bigint = CAST(JSON_VALUE(@RecordFilter, '$.Filter.Id') AS bigint)
               ,@W_S_Id bigint = CAST(JSON_VALUE(@RecordFilter, '$.Search.Id') AS bigint)
               ,@W_F_Name nvarchar(25) = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.Name') AS nvarchar(25))
               ,@W_U_Name nvarchar(25) = CAST(JSON_VALUE(@RecordFilter, '$.Filter.Name') AS nvarchar(25))
               ,@W_S_Name nvarchar(25) = CAST(JSON_VALUE(@RecordFilter, '$.Search.Name') AS nvarchar(25))
               ,@W_F_FullName nvarchar(50) = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.FullName') AS nvarchar(50))
               ,@W_U_FullName nvarchar(50) = CAST(JSON_VALUE(@RecordFilter, '$.Filter.FullName') AS nvarchar(50))
               ,@W_S_FullName nvarchar(50) = CAST(JSON_VALUE(@RecordFilter, '$.Search.FullName') AS nvarchar(50))
               ,@W_F_IsActive bit = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.IsActive') AS bit)
               ,@W_U_IsActive bit = CAST(JSON_VALUE(@RecordFilter, '$.Filter.IsActive') AS bit)
               ,@W_S_IsActive bit = CAST(JSON_VALUE(@RecordFilter, '$.Search.IsActive') AS bit)

        IF @W_F_Id IS NOT NULL BEGIN
            IF @W_F_Id < CAST('1' AS bigint)
                THROW 51000, 'Valor de Id deve ser maior que ou igual a ''1''', 1
            SET @WhereFixed = @WhereFixed + ' AND [T].[Id] = @F_Id'
        END
        IF @W_F_Name IS NOT NULL BEGIN
            SET @WhereFixed = @WhereFixed + ' AND [T].[Name] = @F_Name'
        END
        IF @W_F_FullName IS NOT NULL BEGIN
            SET @WhereFixed = @WhereFixed + ' AND [T].[FullName] = @F_FullName'
        END
        IF @W_F_IsActive IS NOT NULL BEGIN
            SET @WhereFixed = @WhereFixed + ' AND [T].[IsActive] = @F_IsActive'
        END
        IF @IsActionList = 1 BEGIN
            SET @PickerValue = CAST(JSON_VALUE(@RecordFilter, '$.Picker.Value') AS nvarchar(25))
            IF @PickerValue IS NULL
                SET @PickerValue = ''
            SET @WhereUser = '[T].[Name] LIKE ''%'' + @PickerValue + ''%'''
        END ELSE BEGIN
        IF @_ IS NULL BEGIN
            IF @W_U_Id IS NOT NULL BEGIN
                IF @W_U_Id < CAST('1' AS bigint)
                    THROW 51000, 'Valor de Id deve ser maior que ou igual a ''1''', 1
                SET @WhereFilter = @WhereFilter + ' AND [T].[Id] = @U_Id'
            END
            IF @W_U_Name IS NOT NULL BEGIN
                SET @WhereFilter = @WhereFilter + ' AND [T].[Name] = @U_Name'
            END
            IF @W_U_FullName IS NOT NULL BEGIN
                SET @WhereFilter = @WhereFilter + ' AND [T].[FullName] = @U_FullName'
            END
            IF @W_U_IsActive IS NOT NULL BEGIN
                SET @WhereFilter = @WhereFilter + ' AND [T].[IsActive] = @U_IsActive'
            END
            IF @W_S_Id IS NOT NULL BEGIN
                IF @W_S_Id < CAST('1' AS bigint)
                    THROW 51000, 'Valor de Id deve ser maior que ou igual a ''1''', 1
                SET @WhereSearch = @WhereSearch + ' AND [T].[Id] = @S_Id'
            END
            IF @W_S_Name IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[Name] = @S_Name'
            END
            IF @W_S_FullName IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[FullName] = @S_FullName'
            END
            IF @W_S_IsActive IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[IsActive] = @S_IsActive'
            END
            IF @WhereFilter <> '' AND @WhereSearch <> ''
                SET @WhereUser = '(' + STUFF(@WhereFilter, 1, 5, '') + ') OR (' + STUFF(@WhereSearch, 1, 5, '') + ')'
            ELSE IF @WhereFilter <> ''
                SET @WhereUser = STUFF(@WhereFilter, 1, 5, '')
            ELSE IF @WhereSearch <> ''
                SET @WhereUser = STUFF(@WhereSearch, 1, 5, '')
        END ELSE
            SET @WhereUser = '[T].[Id] IN (' + @_ + ')'
        END
        SET @Where = @WhereFixed
        IF @WhereUser <> ''
            SET @Where = @Where + ' AND (' + @WhereUser + ')'
        SET @sql = 'INSERT [#tmpTable]
                        SELECT ''T'' AS [_]
                              ,[T].[Id]
                            FROM [dbo].[Users] [T]
                                LEFT JOIN [#tmpOperations] [#] ON [#].[Id] = [T].[Id]
                            WHERE [#].[Id] IS NULL'
        SET @sql = @sql + @Where + '
                        UNION ALL
                            SELECT ''O'' AS [_]
                                  ,[T].[Id]
                                FROM [#tmpOperations] [T]
                                WHERE [T].[_] <> ''delete'''
        SET @sql = @sql + @Where
        CREATE TABLE [#tmpTable]([_] CHAR(1), [Id] bigint)
        IF @_ IS NULL
            EXEC sp_executesql @sql
                               ,N'@F_Id bigint,@U_Id bigint,@S_Id bigint
                               ,@F_Name nvarchar(25),@U_Name nvarchar(25),@S_Name nvarchar(25)
                               ,@F_FullName nvarchar(50),@U_FullName nvarchar(50),@S_FullName nvarchar(50)
                               ,@F_IsActive bit,@U_IsActive bit,@S_IsActive bit,@PickerValue nvarchar(25)'
                           ,@F_Id = @W_F_Id
                           ,@U_Id = @W_U_Id
                           ,@S_Id = @W_S_Id
                           ,@F_Name = @W_F_Name
                           ,@U_Name = @W_U_Name
                           ,@S_Name = @W_S_Name
                           ,@F_FullName = @W_F_FullName
                           ,@U_FullName = @W_U_FullName
                           ,@S_FullName = @W_S_FullName
                           ,@F_IsActive = @W_F_IsActive
                           ,@U_IsActive = @W_U_IsActive
                           ,@S_IsActive = @W_S_IsActive
                           ,@PickerValue = @PickerValue
        ELSE
            EXEC sp_executesql @sql

        DECLARE @RowCount INT = @@ROWCOUNT
               ,@OffSet INT

        CREATE UNIQUE INDEX [#tmpTable] ON [#tmpTable]([Id])
        IF @RowCount = 0 OR ISNULL(@PageNumber, 0) = 0 OR ISNULL(@LimitRows, 0) <= 0 BEGIN
            SET @OffSet = 0
            SET @LimitRows = CASE WHEN @RowCount = 0 THEN 1 ELSE @RowCount END
            SET @PageNumber = 1
            SET @MaxPage = 1
        END ELSE BEGIN
            SET @MaxPage = @RowCount / @LimitRows + CASE WHEN @RowCount % @LimitRows = 0 THEN 0 ELSE 1 END
            IF ABS(@PageNumber) > @MaxPage
                SET @PageNumber = CASE WHEN @PageNumber < 0 THEN -@MaxPage ELSE @MaxPage END
            IF @PageNumber < 0
                SET @PageNumber = @MaxPage - ABS(@PageNumber) + 1
            SET @OffSet = (@PageNumber - 1) * @LimitRows
            IF @PaddingGridLastPage = 1 AND @OffSet + @LimitRows > @RowCount
                SET @OffSet = CASE WHEN @RowCount > @LimitRows THEN @RowCount - @LimitRows ELSE 0 END
        END
        SELECT TOP 0 CAST(NULL AS NVARCHAR(50)) AS [Kind]
                    ,CAST(NULL AS bigint) AS [Id]
                    ,CAST(NULL AS nvarchar(25)) AS [Name]
                    ,CAST(NULL AS nvarchar(256)) AS [Password]
                    ,CAST(NULL AS nvarchar(50)) AS [FullName]
                    ,CAST(NULL AS tinyint) AS [RetryLogins]
                    ,CAST(NULL AS bit) AS [IsActive]
            INTO [#result]
        SET @sql = 'INSERT #result
                        SELECT ''User'' AS [Kind]
                              ,[T].[Id]
                              ,[T].[Name]
                              ,[T].[Password]
                              ,[T].[FullName]
                              ,[T].[RetryLogins]
                              ,[T].[IsActive]
                            FROM [#tmpTable] [#]
                                INNER JOIN [dbo].[Users] [T] ON [T].[Id] = [#].[Id]
                            WHERE [#].[_] = ''T''
                        UNION ALL
                            SELECT ''User'' AS [Kind]
                                  ,[O].[Id]
                                  ,[O].[Name]
                                  ,[O].[Password]
                                  ,[O].[FullName]
                                  ,[O].[RetryLogins]
                                  ,[O].[IsActive]
                                FROM [#tmpTable] [#]
                                    INNER JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id]
                                WHERE [#].[_] = ''O''
                        ORDER BY ' + @OrderBy + '
                        OFFSET ' + CAST(@offset AS NVARCHAR(20)) + ' ROWS
                        FETCH NEXT ' + CAST(@LimitRows AS NVARCHAR(20)) + ' ROWS ONLY'
        EXEC sp_executesql @sql
        SELECT (SELECT [Kind]
                      ,[Id]
                      ,[Name]
                      ,[Name] AS [ListItemValue]
                      ,[Password]
                      ,[FullName]
                      ,[RetryLogins]
                      ,[IsActive]
                    FROM [#result] FOR JSON PATH) AS [result]
        SET @ReturnValue = @RowCount

    RETURN 0
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[SystemUserValidate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[SystemUserValidate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[SystemUserValidate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[SystemUserValidate](@SessionId BIGINT
                                               ,@TransactionId BIGINT
                                               ,@UserName NVARCHAR(25)
                                               ,@Action NVARCHAR(15)
                                               ,@LastRecord NVARCHAR(max)
                                               ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED
    IF @SessionId IS NULL
            THROW 51000, 'Valor de @SessionId é requerido', 1
        IF @UserName IS NULL
            THROW 51000, 'Valor de @UserName é requerido', 1
        IF @Action IS NULL
            THROW 51000, 'Valor de @Action é requerido', 1
        IF @Action NOT IN ('create', 'update', 'delete')
            THROW 51000, 'Valor de @Action é inválido', 1
        IF @Action = 'delete' BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
        END ELSE BEGIN
            IF @ActualRecord IS NULL
                THROW 51000, 'Valor de @ActualRecord é requerido', 1
            IF ISJSON(@ActualRecord) = 0
                THROW 51000, 'Valor de @ActualRecord não está no formato JSON', 1
        END
        IF @TransactionId IS NULL
            THROW 51000, 'Valor de @TransactionId é requerido', 1
        DECLARE @IsConfirmed BIT
               ,@CreatedBy NVARCHAR(25)
               ,@IsPendingCreate BIT = 0
               ,@W_Id AS bigint

        IF @Action = 'delete'
            SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)
        ELSE
            SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        SELECT @IsConfirmed = [IsConfirmed]
              ,@CreatedBy = [CreatedBy]
            FROM [dbo].[Transactions]
            WHERE [Id] = @TransactionId
                  AND [SessionId] = @SessionId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Transação inexistente', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Transação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1;
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @W_Id IS NULL BEGIN
            SET @ErrorMessage = 'Valor de Id em @ActualRecord é requerido.';
            THROW 51000, @ErrorMessage, 1
        END
        IF @W_Id < CAST('1' AS bigint)
            THROW 51000, 'Valor de Id em @ActualRecord deve ser maior que ou igual a 1', 1
        IF EXISTS(SELECT 1 FROM [dbo].[SystemsUsers] WHERE [Id] = @W_Id) BEGIN
            IF @Action = 'create'
                THROW 51000, 'Chave-primária já existe em SystemsUsers', 1
        END ELSE IF @Action = 'delete' AND EXISTS(SELECT 1
                                    FROM [dbo].[Operations]
                                    WHERE [TransactionId] = @TransactionId
                                          AND [TableName] = 'SystemsUsers'
                                          AND [IsConfirmed] IS NULL
                                          AND [Action] = 'create'
                                          AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id)
            SET @IsPendingCreate = 1
        ELSE IF @Action <> 'create'
            THROW 51000, 'Chave-primária não existe em SystemsUsers', 1
        IF @Action <> 'create' AND @IsPendingCreate = 0 BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
            IF NOT EXISTS(SELECT 1
                            FROM [dbo].[SystemsUsers]
                            WHERE [Id] = JSON_VALUE(@LastRecord, '$.Id')
                                  AND [SystemId] = JSON_VALUE(@LastRecord, '$.SystemId')
                                  AND [UserId] = JSON_VALUE(@LastRecord, '$.UserId')
                                  AND [Name] = JSON_VALUE(@LastRecord, '$.Name'))
            AND NOT EXISTS(SELECT 1
                            FROM [dbo].[Operations]
                            WHERE [TransactionId] = @TransactionId
                                  AND [TableName] = 'SystemsUsers'
                                  AND [IsConfirmed] IS NULL
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') = JSON_VALUE(@LastRecord, '$.Id')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.SystemId') = JSON_VALUE(@LastRecord, '$.SystemId')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.UserId') = JSON_VALUE(@LastRecord, '$.UserId')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Name') = JSON_VALUE(@LastRecord, '$.Name'))
                THROW 51000, 'Registro de SystemsUsers alterado por outro usuário', 1
        END

        IF @Action IN ('create', 'update') BEGIN

            DECLARE @W_SystemId bigint = CAST(JSON_VALUE(@ActualRecord, '$.SystemId') AS bigint)
                   ,@W_UserId bigint = CAST(JSON_VALUE(@ActualRecord, '$.UserId') AS bigint)
                   ,@W_Name nvarchar(50) = CAST(JSON_VALUE(@ActualRecord, '$.Name') AS nvarchar(50))

            IF @W_SystemId IS NULL
                THROW 51000, 'Valor de SystemId em @ActualRecord é requerido.', 1
            IF @W_SystemId < CAST('1' AS bigint)
                THROW 51000, 'Valor de SystemId em @ActualRecord deve ser maior que ou igual a 1', 1
            IF NOT EXISTS(SELECT 1 FROM [dbo].[Systems] WHERE [Id] = @W_SystemId)
                THROW 51000, 'Valor de SystemId em @ActualRecord inexiste em Systems', 1
            IF @W_UserId IS NULL
                THROW 51000, 'Valor de UserId em @ActualRecord é requerido.', 1
            IF @W_UserId < CAST('1' AS bigint)
                THROW 51000, 'Valor de UserId em @ActualRecord deve ser maior que ou igual a 1', 1
            IF NOT EXISTS(SELECT 1 FROM [dbo].[Users] WHERE [Id] = @W_UserId)
                THROW 51000, 'Valor de UserId em @ActualRecord inexiste em Users', 1
            IF @W_Name IS NULL
                THROW 51000, 'Valor de Name em @ActualRecord é requerido.', 1
            IF @Action = 'create' BEGIN
                IF EXISTS(SELECT 1 FROM [dbo].[SystemsUsers] WHERE [SystemId] = @W_SystemId AND [UserId] = @W_UserId)
                    THROW 51000, 'Chave única de UNQ_SystemsUsers_SystemId_UserId já existe', 1
                IF EXISTS(SELECT 1 FROM [dbo].[SystemsUsers] WHERE [Name] = @W_Name)
                    THROW 51000, 'Chave única de UNQ_SystemsUsers_Name já existe', 1
            ELSE IF EXISTS(SELECT 1 FROM [dbo].[SystemsUsers] WHERE [SystemId] = @W_SystemId AND [UserId] = @W_UserId AND [Id] <> @W_Id)
                THROW 51000, 'Chave única de UNQ_SystemsUsers_SystemId_UserId já existe', 1
            ELSE IF EXISTS(SELECT 1 FROM [dbo].[SystemsUsers] WHERE [Name] = @W_Name AND [Id] <> @W_Id)
                THROW 51000, 'Chave única de UNQ_SystemsUsers_Name já existe', 1
            END
        END

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[SystemUserPersist]
**********************************************************************************/
IF(SELECT object_id('[dbo].[SystemUserPersist]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[SystemUserPersist] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[SystemUserPersist](@Login NVARCHAR(MAX)
                                              ,@TransactionId BIGINT
                                              ,@Action NVARCHAR(15)
                                              ,@LastRecord NVARCHAR(max)
                                              ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(255)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    DECLARE @OperationId BIGINT
               ,@CreatedBy NVARCHAR(25)
               ,@ActionAux NVARCHAR(15)
               ,@IsConfirmed BIT
           ,@W_Id bigint

    IF @Action = 'delete'
        SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)
    ELSE
        SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

    IF @Action = 'create' AND @W_Id IS NULL BEGIN
        SELECT @W_Id = CAST(JSON_VALUE([ActualRecord], '$.Id') AS bigint)
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'SystemsUsers'
                  AND [Action] = 'create'
                  AND [IsConfirmed] IS NULL
        IF @W_Id IS NULL BEGIN
            DECLARE @NewId BIGINT
    EXEC [dbo].[NewId] 'crudex', 'crudex', 'SystemsUsers', @NewId OUT
            SET @W_Id = CAST(@NewId AS bigint)
        END
        SET @ActualRecord = JSON_MODIFY(@ActualRecord, '$.Id', @W_Id)
    END

    EXEC @TransactionId = [dbo].[SystemUserValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        SELECT @OperationId = [Id]
              ,@CreatedBy = [CreatedBy]
              ,@ActionAux = [Action]
              ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'SystemsUsers'
                  AND [IsConfirmed] IS NULL
                  AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id
        IF @@ROWCOUNT = 0 BEGIN
            EXEC [dbo].[NewOperationId] 'crudex', 'crudex', @OperationId OUT
            INSERT INTO [dbo].[Operations] ([Id]
                                             ,[TransactionId]
                                             ,[TableName]
                                             ,[Action]
                                             ,[LastRecord]
                                             ,[ActualRecord]
                                             ,[IsConfirmed]
                                             ,[CreatedAt]
                                             ,[CreatedBy])
                                       VALUES(@OperationId
                                             ,@TransactionId
                                             ,'SystemsUsers'
                                             ,@Action
                                             ,@LastRecord
                                             ,@ActualRecord
                                             ,NULL
                                             ,GETDATE()
                                             ,@UserName)
        END ELSE IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END ELSE IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        ELSE IF @ActionAux = 'delete'
            THROW 51000, 'Registro excluído nesta transação', 1
        ELSE IF @Action = 'create' BEGIN
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END
        ELSE IF @Action = 'update' BEGIN
            IF @ActionAux = 'create'
                EXEC [dbo].[SystemUserValidate] @SessionId, @TransactionId, @UserName, 'create', NULL, @ActualRecord
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END ELSE IF @ActionAux = 'create' BEGIN
            UPDATE [dbo].[Operations] 
                SET [IsConfirmed] = 0
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END ELSE BEGIN
            UPDATE [dbo].[Operations]
                SET [Action] = 'delete'
                   ,[LastRecord] = @LastRecord
                   ,[ActualRecord] = NULL
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END

    RETURN CAST(@OperationId AS BIGINT)
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[SystemUserCreate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[SystemUserCreate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[SystemUserCreate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[SystemUserCreate](@Login NVARCHAR(MAX)
                                             ,@OperationId BIGINT) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    DECLARE @TransactionId BIGINT
               ,@TransactionIdAux BIGINT
               ,@TableName NVARCHAR(25)
               ,@Action NVARCHAR(15)
               ,@CreatedBy NVARCHAR(25)
               ,@LastRecord NVARCHAR(max)
               ,@ActualRecord NVARCHAR(max)
               ,@IsConfirmed BIT

    IF @OperationId IS NULL
            THROW 51000, 'Valor de @OperationId requerido', 1
        SELECT @TransactionId = [TransactionId]
               ,@TableName = [TableName]
               ,@Action = [Action]
               ,@CreatedBy = [CreatedBy]
               ,@LastRecord = [LastRecord]
               ,@ActualRecord = [ActualRecord]
               ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [Id] = @OperationId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Operação inexistente', 1
        IF @TableName <> 'SystemsUsers'
            THROW 51000, 'Tabela da operação é inválida', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @Action <> 'create'
            THROW 51000, 'Ação da operação é inválida para Create', 1
        EXEC @TransactionIdAux = [dbo].[SystemUserValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        IF @TransactionId <> @TransactionIdAux
            THROW 51000, 'Transação da operação é inválida', 1
        DECLARE @W_Id bigint = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        DECLARE @W_SystemId bigint = CAST(JSON_VALUE(@ActualRecord, '$.SystemId') AS bigint)
               ,@W_UserId bigint = CAST(JSON_VALUE(@ActualRecord, '$.UserId') AS bigint)
               ,@W_Name nvarchar(50) = CAST(JSON_VALUE(@ActualRecord, '$.Name') AS nvarchar(50))

        INSERT INTO [dbo].[SystemsUsers] ([Id]
                                            ,[SystemId]
                                            ,[UserId]
                                            ,[Name]
                                            ,[CreatedAt]
                                            ,[CreatedBy])
                                      VALUES (@W_Id
                                             ,@W_SystemId
                                             ,@W_UserId
                                             ,@W_Name
                                             ,GETDATE()
                                             ,@UserName)
        UPDATE [dbo].[Operations]
            SET [IsConfirmed] = 1
                ,[UpdatedAt] = GETDATE()
                ,[UpdatedBy] = @UserName
            WHERE [Id] = @OperationId

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[SystemUserUpdate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[SystemUserUpdate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[SystemUserUpdate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[SystemUserUpdate](@Login NVARCHAR(MAX)
                                             ,@OperationId BIGINT) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    DECLARE @TransactionId BIGINT
               ,@TransactionIdAux BIGINT
               ,@TableName NVARCHAR(25)
               ,@Action NVARCHAR(15)
               ,@CreatedBy NVARCHAR(25)
               ,@LastRecord NVARCHAR(max)
               ,@ActualRecord NVARCHAR(max)
               ,@IsConfirmed BIT

    IF @OperationId IS NULL
            THROW 51000, 'Valor de @OperationId requerido', 1
        SELECT @TransactionId = [TransactionId]
               ,@TableName = [TableName]
               ,@Action = [Action]
               ,@CreatedBy = [CreatedBy]
               ,@LastRecord = [LastRecord]
               ,@ActualRecord = [ActualRecord]
               ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [Id] = @OperationId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Operação inexistente', 1
        IF @TableName <> 'SystemsUsers'
            THROW 51000, 'Tabela da operação é inválida', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @Action <> 'update'
            THROW 51000, 'Ação da operação é inválida para Update', 1
        EXEC @TransactionIdAux = [dbo].[SystemUserValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        IF @TransactionId <> @TransactionIdAux
            THROW 51000, 'Transação da operação é inválida', 1
        DECLARE @W_Id bigint = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        DECLARE @W_SystemId bigint = CAST(JSON_VALUE(@ActualRecord, '$.SystemId') AS bigint)
               ,@W_UserId bigint = CAST(JSON_VALUE(@ActualRecord, '$.UserId') AS bigint)
               ,@W_Name nvarchar(50) = CAST(JSON_VALUE(@ActualRecord, '$.Name') AS nvarchar(50))

        UPDATE [dbo].[SystemsUsers] SET [Id] = @W_Id
                                          ,[SystemId] = @W_SystemId
                                          ,[UserId] = @W_UserId
                                          ,[Name] = @W_Name
                                          ,[UpdatedAt] = GETDATE()
                                          ,[UpdatedBy] = @UserName
            WHERE [Id] = @W_Id
        UPDATE [dbo].[Operations]
            SET [IsConfirmed] = 1
                ,[UpdatedAt] = GETDATE()
                ,[UpdatedBy] = @UserName
            WHERE [Id] = @OperationId

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[SystemUserDelete]
**********************************************************************************/
IF(SELECT object_id('[dbo].[SystemUserDelete]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[SystemUserDelete] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[SystemUserDelete](@Login NVARCHAR(MAX)
                                             ,@OperationId BIGINT) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    DECLARE @TransactionId BIGINT
               ,@TransactionIdAux BIGINT
               ,@TableName NVARCHAR(25)
               ,@Action NVARCHAR(15)
               ,@CreatedBy NVARCHAR(25)
               ,@LastRecord NVARCHAR(max)
               ,@ActualRecord NVARCHAR(max)
               ,@IsConfirmed BIT

    IF @OperationId IS NULL
            THROW 51000, 'Valor de @OperationId requerido', 1
        SELECT @TransactionId = [TransactionId]
               ,@TableName = [TableName]
               ,@Action = [Action]
               ,@CreatedBy = [CreatedBy]
               ,@LastRecord = [LastRecord]
               ,@ActualRecord = [ActualRecord]
               ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [Id] = @OperationId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Operação inexistente', 1
        IF @TableName <> 'SystemsUsers'
            THROW 51000, 'Tabela da operação é inválida', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @Action <> 'delete'
            THROW 51000, 'Ação da operação é inválida para Delete', 1
        EXEC @TransactionIdAux = [dbo].[SystemUserValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        IF @TransactionId <> @TransactionIdAux
            THROW 51000, 'Transação da operação é inválida', 1
        DECLARE @W_Id bigint = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)

        DELETE FROM [dbo].[SystemsUsers] WHERE [Id] = @W_Id

        UPDATE [dbo].[Operations]
            SET [IsConfirmed] = 1
                ,[UpdatedAt] = GETDATE()
                ,[UpdatedBy] = @UserName
            WHERE [Id] = @OperationId

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[SystemsUsersRead]
**********************************************************************************/
IF(SELECT object_id('[dbo].[SystemsUsersRead]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[SystemsUsersRead] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[SystemsUsersRead](@Login NVARCHAR(MAX)
                                          ,@RecordFilter NVARCHAR(MAX)
                                          ,@OrderBy NVARCHAR(MAX)
                                          ,@PaddingGridLastPage BIT
                                          ,@IsActionList BIT
                                          ,@PageNumber INT OUT
                                          ,@LimitRows INT OUT
                                          ,@MaxPage INT OUT
                                          ,@ReturnValue BIGINT OUT) AS BEGIN

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @LoginId BIGINT
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @LoginId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @LoginId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    IF @RecordFilter IS NULL
            SET @RecordFilter = '{}'
        ELSE IF ISJSON(@RecordFilter) = 0
            THROW 51000, 'Valor de @RecordFilter não está no formato JSON', 1
        SET @OrderBy = TRIM(ISNULL(@OrderBy, ''))
        IF @OrderBy = ''
            SET @OrderBy = '[Id]'
        ELSE BEGIN
            SET @OrderBy = REPLACE(REPLACE(@OrderBy, '[', ''), ']', '')
            IF EXISTS(SELECT 1 
                         FROM (SELECT CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                           WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                           ELSE TRIM([value])
                                      END AS [ColumnName]
                                  FROM STRING_SPLIT(@OrderBy, ',')) AS [O]
                                      LEFT JOIN (SELECT [#1].[name] AS ColumnName
                                                    FROM [sys].[columns] [#1]
                                                        INNER JOIN [sys].[tables] [#2] ON [#1].[object_id] = [#2].[object_id]
                                                    WHERE [#2].[name] = 'SystemsUsers') AS [T] ON [T].[ColumnName] = [O].[ColumnName]
                         WHERE [T].[ColumnName] IS NULL)
                THROW 51000, 'Nome de coluna em @OrderBy é inválido', 1
            SELECT @OrderBy = STRING_AGG('[' + TRIM(CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                                         ELSE TRIM([value])
                                                    END) + '] ' + 
                                                    CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN 'DESC'
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN 'ASC'
                                                         ELSE 'ASC'
                                                    END, ', ')
                FROM STRING_SPLIT(@OrderBy, ',')
        END
        IF @IsActionList = 1
            SET @OrderBy = '[Name]'
        DECLARE @PickerValue nvarchar(50) = NULL

        DECLARE @TransactionId BIGINT = (SELECT MAX([Id]) FROM [dbo].[Transactions] WHERE [SessionId] = @LoginId)

        IF NOT EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [Id] = @TransactionId AND [IsConfirmed] IS NULL)
            SET @TransactionId = NULL
        SELECT [Action] AS [_]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) AS [Id]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.SystemId') AS bigint) AS [SystemId]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.UserId') AS bigint) AS [UserId]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Name') AS nvarchar(50)) AS [Name]
            INTO [#tmpOperations]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'SystemsUsers'
                  AND [IsConfirmed] IS NULL
        CREATE UNIQUE INDEX [#tmpOperations] ON [#tmpOperations]([Id])

        DECLARE @_ NVARCHAR(MAX) = (SELECT STRING_AGG(value, ',') FROM OPENJSON(@RecordFilter, '$.Filter._'))
               ,@WhereFixed NVARCHAR(MAX) = ''
               ,@WhereFilter NVARCHAR(MAX) = ''
               ,@WhereSearch NVARCHAR(MAX) = ''
               ,@WhereUser NVARCHAR(MAX) = ''
               ,@Where NVARCHAR(MAX) = ''
               ,@sql NVARCHAR(MAX)

        DECLARE @W_F_Id bigint = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.Id') AS bigint)
               ,@W_U_Id bigint = CAST(JSON_VALUE(@RecordFilter, '$.Filter.Id') AS bigint)
               ,@W_S_Id bigint = CAST(JSON_VALUE(@RecordFilter, '$.Search.Id') AS bigint)
               ,@W_F_SystemId bigint = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.SystemId') AS bigint)
               ,@W_U_SystemId bigint = CAST(JSON_VALUE(@RecordFilter, '$.Filter.SystemId') AS bigint)
               ,@W_S_SystemId bigint = CAST(JSON_VALUE(@RecordFilter, '$.Search.SystemId') AS bigint)
               ,@W_F_UserId bigint = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.UserId') AS bigint)
               ,@W_U_UserId bigint = CAST(JSON_VALUE(@RecordFilter, '$.Filter.UserId') AS bigint)
               ,@W_S_UserId bigint = CAST(JSON_VALUE(@RecordFilter, '$.Search.UserId') AS bigint)
               ,@W_F_Name nvarchar(50) = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.Name') AS nvarchar(50))
               ,@W_U_Name nvarchar(50) = CAST(JSON_VALUE(@RecordFilter, '$.Filter.Name') AS nvarchar(50))
               ,@W_S_Name nvarchar(50) = CAST(JSON_VALUE(@RecordFilter, '$.Search.Name') AS nvarchar(50))

        IF @W_F_Id IS NOT NULL BEGIN
            IF @W_F_Id < CAST('1' AS bigint)
                THROW 51000, 'Valor de Id deve ser maior que ou igual a ''1''', 1
            SET @WhereFixed = @WhereFixed + ' AND [T].[Id] = @F_Id'
        END
        IF @W_F_SystemId IS NOT NULL BEGIN
            IF @W_F_SystemId < CAST('1' AS bigint)
                THROW 51000, 'Valor de SystemId deve ser maior que ou igual a ''1''', 1
            SET @WhereFixed = @WhereFixed + ' AND [T].[SystemId] = @F_SystemId'
        END
        IF @W_F_UserId IS NOT NULL BEGIN
            IF @W_F_UserId < CAST('1' AS bigint)
                THROW 51000, 'Valor de UserId deve ser maior que ou igual a ''1''', 1
            SET @WhereFixed = @WhereFixed + ' AND [T].[UserId] = @F_UserId'
        END
        IF @W_F_Name IS NOT NULL BEGIN
            SET @WhereFixed = @WhereFixed + ' AND [T].[Name] = @F_Name'
        END
        IF @IsActionList = 1 BEGIN
            SET @PickerValue = CAST(JSON_VALUE(@RecordFilter, '$.Picker.Value') AS nvarchar(50))
            IF @PickerValue IS NULL
                SET @PickerValue = ''
            SET @WhereUser = '[T].[Name] LIKE ''%'' + @PickerValue + ''%'''
        END ELSE BEGIN
        IF @_ IS NULL BEGIN
            IF @W_U_Id IS NOT NULL BEGIN
                IF @W_U_Id < CAST('1' AS bigint)
                    THROW 51000, 'Valor de Id deve ser maior que ou igual a ''1''', 1
                SET @WhereFilter = @WhereFilter + ' AND [T].[Id] = @U_Id'
            END
            IF @W_U_SystemId IS NOT NULL BEGIN
                IF @W_U_SystemId < CAST('1' AS bigint)
                    THROW 51000, 'Valor de SystemId deve ser maior que ou igual a ''1''', 1
                SET @WhereFilter = @WhereFilter + ' AND [T].[SystemId] = @U_SystemId'
            END
            IF @W_U_UserId IS NOT NULL BEGIN
                IF @W_U_UserId < CAST('1' AS bigint)
                    THROW 51000, 'Valor de UserId deve ser maior que ou igual a ''1''', 1
                SET @WhereFilter = @WhereFilter + ' AND [T].[UserId] = @U_UserId'
            END
            IF @W_U_Name IS NOT NULL BEGIN
                SET @WhereFilter = @WhereFilter + ' AND [T].[Name] = @U_Name'
            END
            IF @W_S_Id IS NOT NULL BEGIN
                IF @W_S_Id < CAST('1' AS bigint)
                    THROW 51000, 'Valor de Id deve ser maior que ou igual a ''1''', 1
                SET @WhereSearch = @WhereSearch + ' AND [T].[Id] = @S_Id'
            END
            IF @W_S_SystemId IS NOT NULL BEGIN
                IF @W_S_SystemId < CAST('1' AS bigint)
                    THROW 51000, 'Valor de SystemId deve ser maior que ou igual a ''1''', 1
                SET @WhereSearch = @WhereSearch + ' AND [T].[SystemId] = @S_SystemId'
            END
            IF @W_S_UserId IS NOT NULL BEGIN
                IF @W_S_UserId < CAST('1' AS bigint)
                    THROW 51000, 'Valor de UserId deve ser maior que ou igual a ''1''', 1
                SET @WhereSearch = @WhereSearch + ' AND [T].[UserId] = @S_UserId'
            END
            IF @W_S_Name IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[Name] = @S_Name'
            END
            IF @WhereFilter <> '' AND @WhereSearch <> ''
                SET @WhereUser = '(' + STUFF(@WhereFilter, 1, 5, '') + ') OR (' + STUFF(@WhereSearch, 1, 5, '') + ')'
            ELSE IF @WhereFilter <> ''
                SET @WhereUser = STUFF(@WhereFilter, 1, 5, '')
            ELSE IF @WhereSearch <> ''
                SET @WhereUser = STUFF(@WhereSearch, 1, 5, '')
        END ELSE
            SET @WhereUser = '[T].[Id] IN (' + @_ + ')'
        END
        SET @Where = @WhereFixed
        IF @WhereUser <> ''
            SET @Where = @Where + ' AND (' + @WhereUser + ')'
        SET @sql = 'INSERT [#tmpTable]
                        SELECT ''T'' AS [_]
                              ,[T].[Id]
                            FROM [dbo].[SystemsUsers] [T]
                                LEFT JOIN [#tmpOperations] [#] ON [#].[Id] = [T].[Id]
                            WHERE [#].[Id] IS NULL'
        SET @sql = @sql + @Where + '
                        UNION ALL
                            SELECT ''O'' AS [_]
                                  ,[T].[Id]
                                FROM [#tmpOperations] [T]
                                WHERE [T].[_] <> ''delete'''
        SET @sql = @sql + @Where
        CREATE TABLE [#tmpTable]([_] CHAR(1), [Id] bigint)
        IF @_ IS NULL
            EXEC sp_executesql @sql
                               ,N'@F_Id bigint,@U_Id bigint,@S_Id bigint
                               ,@F_SystemId bigint,@U_SystemId bigint,@S_SystemId bigint
                               ,@F_UserId bigint,@U_UserId bigint,@S_UserId bigint
                               ,@F_Name nvarchar(50),@U_Name nvarchar(50),@S_Name nvarchar(50),@PickerValue nvarchar(50)'
                           ,@F_Id = @W_F_Id
                           ,@U_Id = @W_U_Id
                           ,@S_Id = @W_S_Id
                           ,@F_SystemId = @W_F_SystemId
                           ,@U_SystemId = @W_U_SystemId
                           ,@S_SystemId = @W_S_SystemId
                           ,@F_UserId = @W_F_UserId
                           ,@U_UserId = @W_U_UserId
                           ,@S_UserId = @W_S_UserId
                           ,@F_Name = @W_F_Name
                           ,@U_Name = @W_U_Name
                           ,@S_Name = @W_S_Name
                           ,@PickerValue = @PickerValue
        ELSE
            EXEC sp_executesql @sql

        DECLARE @RowCount INT = @@ROWCOUNT
               ,@OffSet INT

        CREATE UNIQUE INDEX [#tmpTable] ON [#tmpTable]([Id])
        IF @RowCount = 0 OR ISNULL(@PageNumber, 0) = 0 OR ISNULL(@LimitRows, 0) <= 0 BEGIN
            SET @OffSet = 0
            SET @LimitRows = CASE WHEN @RowCount = 0 THEN 1 ELSE @RowCount END
            SET @PageNumber = 1
            SET @MaxPage = 1
        END ELSE BEGIN
            SET @MaxPage = @RowCount / @LimitRows + CASE WHEN @RowCount % @LimitRows = 0 THEN 0 ELSE 1 END
            IF ABS(@PageNumber) > @MaxPage
                SET @PageNumber = CASE WHEN @PageNumber < 0 THEN -@MaxPage ELSE @MaxPage END
            IF @PageNumber < 0
                SET @PageNumber = @MaxPage - ABS(@PageNumber) + 1
            SET @OffSet = (@PageNumber - 1) * @LimitRows
            IF @PaddingGridLastPage = 1 AND @OffSet + @LimitRows > @RowCount
                SET @OffSet = CASE WHEN @RowCount > @LimitRows THEN @RowCount - @LimitRows ELSE 0 END
        END
        SELECT TOP 0 CAST(NULL AS NVARCHAR(50)) AS [Kind]
                    ,CAST(NULL AS bigint) AS [Id]
                    ,CAST(NULL AS bigint) AS [SystemId]
                    ,CAST(NULL AS bigint) AS [UserId]
                    ,CAST(NULL AS nvarchar(50)) AS [Name]
            INTO [#result]
        SET @sql = 'INSERT #result
                        SELECT ''SystemUser'' AS [Kind]
                              ,[T].[Id]
                              ,[T].[SystemId]
                              ,[T].[UserId]
                              ,[T].[Name]
                            FROM [#tmpTable] [#]
                                INNER JOIN [dbo].[SystemsUsers] [T] ON [T].[Id] = [#].[Id]
                            WHERE [#].[_] = ''T''
                        UNION ALL
                            SELECT ''SystemUser'' AS [Kind]
                                  ,[O].[Id]
                                  ,[O].[SystemId]
                                  ,[O].[UserId]
                                  ,[O].[Name]
                                FROM [#tmpTable] [#]
                                    INNER JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id]
                                WHERE [#].[_] = ''O''
                        ORDER BY ' + @OrderBy + '
                        OFFSET ' + CAST(@offset AS NVARCHAR(20)) + ' ROWS
                        FETCH NEXT ' + CAST(@LimitRows AS NVARCHAR(20)) + ' ROWS ONLY'
        EXEC sp_executesql @sql
        SELECT DISTINCT 'System' AS [Kind]
              ,[R].[Id]
              ,[R].[Name]
              ,[R].[Description]
              ,[R].[ClientName]
              ,[R].[MaxRetryLogins]
              ,[R].[IsOffAir]
            INTO [#Systems]
            FROM [#result] [T]
                INNER JOIN [dbo].[Systems] [R] ON [R].[Id] = [T].[SystemId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Systems] ON [#Systems](Id)
        SELECT DISTINCT 'User' AS [Kind]
              ,[R].[Id]
              ,[R].[Name]
              ,[R].[Password]
              ,[R].[FullName]
              ,[R].[RetryLogins]
              ,[R].[IsActive]
            INTO [#Users]
            FROM [#result] [T]
                INNER JOIN [dbo].[Users] [R] ON [R].[Id] = [T].[UserId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Users] ON [#Users](Id)
        SELECT (SELECT [Kind]
                      ,[Id]
                      ,[SystemId]
                      ,[UserId]
                      ,[Name]
                      ,[Name] AS [ListItemValue]
                    FROM [#result] FOR JSON PATH) AS [result]
              ,ISNULL((SELECT [Systems].* FROM [#Systems] AS [Systems] FOR JSON PATH), '[]') AS [Systems]
              ,ISNULL((SELECT [Users].* FROM [#Users] AS [Users] FOR JSON PATH), '[]') AS [Users]
        SET @ReturnValue = @RowCount

    RETURN 0
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[ConnectionValidate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[ConnectionValidate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[ConnectionValidate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[ConnectionValidate](@SessionId BIGINT
                                               ,@TransactionId BIGINT
                                               ,@UserName NVARCHAR(25)
                                               ,@Action NVARCHAR(15)
                                               ,@LastRecord NVARCHAR(max)
                                               ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED
    IF @SessionId IS NULL
            THROW 51000, 'Valor de @SessionId é requerido', 1
        IF @UserName IS NULL
            THROW 51000, 'Valor de @UserName é requerido', 1
        IF @Action IS NULL
            THROW 51000, 'Valor de @Action é requerido', 1
        IF @Action NOT IN ('create', 'update', 'delete')
            THROW 51000, 'Valor de @Action é inválido', 1
        IF @Action = 'delete' BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
        END ELSE BEGIN
            IF @ActualRecord IS NULL
                THROW 51000, 'Valor de @ActualRecord é requerido', 1
            IF ISJSON(@ActualRecord) = 0
                THROW 51000, 'Valor de @ActualRecord não está no formato JSON', 1
        END
        IF @TransactionId IS NULL
            THROW 51000, 'Valor de @TransactionId é requerido', 1
        DECLARE @IsConfirmed BIT
               ,@CreatedBy NVARCHAR(25)
               ,@IsPendingCreate BIT = 0
               ,@W_Id AS bigint

        IF @Action = 'delete'
            SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)
        ELSE
            SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        SELECT @IsConfirmed = [IsConfirmed]
              ,@CreatedBy = [CreatedBy]
            FROM [dbo].[Transactions]
            WHERE [Id] = @TransactionId
                  AND [SessionId] = @SessionId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Transação inexistente', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Transação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1;
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @W_Id IS NULL BEGIN
            SET @ErrorMessage = 'Valor de Id em @ActualRecord é requerido.';
            THROW 51000, @ErrorMessage, 1
        END
        IF EXISTS(SELECT 1 FROM [dbo].[Connections] WHERE [Id] = @W_Id) BEGIN
            IF @Action = 'create'
                THROW 51000, 'Chave-primária já existe em Connections', 1
        END ELSE IF @Action = 'delete' AND EXISTS(SELECT 1
                                    FROM [dbo].[Operations]
                                    WHERE [TransactionId] = @TransactionId
                                          AND [TableName] = 'Connections'
                                          AND [IsConfirmed] IS NULL
                                          AND [Action] = 'create'
                                          AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id)
            SET @IsPendingCreate = 1
        ELSE IF @Action <> 'create'
            THROW 51000, 'Chave-primária não existe em Connections', 1
        IF @Action <> 'create' AND @IsPendingCreate = 0 BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
            IF NOT EXISTS(SELECT 1
                            FROM [dbo].[Connections]
                            WHERE [Id] = JSON_VALUE(@LastRecord, '$.Id')
                                  AND [Environment] = JSON_VALUE(@LastRecord, '$.Environment')
                                  AND [ConnectionString] = JSON_VALUE(@LastRecord, '$.ConnectionString'))
            AND NOT EXISTS(SELECT 1
                            FROM [dbo].[Operations]
                            WHERE [TransactionId] = @TransactionId
                                  AND [TableName] = 'Connections'
                                  AND [IsConfirmed] IS NULL
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') = JSON_VALUE(@LastRecord, '$.Id')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Environment') = JSON_VALUE(@LastRecord, '$.Environment')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.ConnectionString') = JSON_VALUE(@LastRecord, '$.ConnectionString'))
                THROW 51000, 'Registro de Connections alterado por outro usuário', 1
        END

        IF @Action = 'delete' BEGIN
            IF EXISTS(SELECT 1 FROM [dbo].[Databases] WHERE [ConnectionId] = @W_Id)
                THROW 51000, 'Chave-primária referenciada em Databases', 1
        END
        IF @Action IN ('create', 'update') BEGIN

            DECLARE @W_Environment nvarchar(3) = CAST(JSON_VALUE(@ActualRecord, '$.Environment') AS nvarchar(3))
                   ,@W_ConnectionString nvarchar(256) = CAST(JSON_VALUE(@ActualRecord, '$.ConnectionString') AS nvarchar(256))

            IF @W_Environment IS NULL
                THROW 51000, 'Valor de Environment em @ActualRecord é requerido.', 1
            IF @W_ConnectionString IS NULL
                THROW 51000, 'Valor de ConnectionString em @ActualRecord é requerido.', 1
        END

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[ConnectionPersist]
**********************************************************************************/
IF(SELECT object_id('[dbo].[ConnectionPersist]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[ConnectionPersist] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[ConnectionPersist](@Login NVARCHAR(MAX)
                                              ,@TransactionId BIGINT
                                              ,@Action NVARCHAR(15)
                                              ,@LastRecord NVARCHAR(max)
                                              ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(255)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    DECLARE @OperationId BIGINT
               ,@CreatedBy NVARCHAR(25)
               ,@ActionAux NVARCHAR(15)
               ,@IsConfirmed BIT
           ,@W_Id bigint

    IF @Action = 'delete'
        SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)
    ELSE
        SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

    IF @Action = 'create' AND @W_Id IS NULL BEGIN
        SELECT @W_Id = CAST(JSON_VALUE([ActualRecord], '$.Id') AS bigint)
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Connections'
                  AND [Action] = 'create'
                  AND [IsConfirmed] IS NULL
        IF @W_Id IS NULL BEGIN
            DECLARE @NewId BIGINT
    EXEC [dbo].[NewId] 'crudex', 'crudex', 'Connections', @NewId OUT
            SET @W_Id = CAST(@NewId AS bigint)
        END
        SET @ActualRecord = JSON_MODIFY(@ActualRecord, '$.Id', @W_Id)
    END

    EXEC @TransactionId = [dbo].[ConnectionValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        SELECT @OperationId = [Id]
              ,@CreatedBy = [CreatedBy]
              ,@ActionAux = [Action]
              ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Connections'
                  AND [IsConfirmed] IS NULL
                  AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id
        IF @@ROWCOUNT = 0 BEGIN
            EXEC [dbo].[NewOperationId] 'crudex', 'crudex', @OperationId OUT
            INSERT INTO [dbo].[Operations] ([Id]
                                             ,[TransactionId]
                                             ,[TableName]
                                             ,[Action]
                                             ,[LastRecord]
                                             ,[ActualRecord]
                                             ,[IsConfirmed]
                                             ,[CreatedAt]
                                             ,[CreatedBy])
                                       VALUES(@OperationId
                                             ,@TransactionId
                                             ,'Connections'
                                             ,@Action
                                             ,@LastRecord
                                             ,@ActualRecord
                                             ,NULL
                                             ,GETDATE()
                                             ,@UserName)
        END ELSE IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END ELSE IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        ELSE IF @ActionAux = 'delete'
            THROW 51000, 'Registro excluído nesta transação', 1
        ELSE IF @Action = 'create' BEGIN
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END
        ELSE IF @Action = 'update' BEGIN
            IF @ActionAux = 'create'
                EXEC [dbo].[ConnectionValidate] @SessionId, @TransactionId, @UserName, 'create', NULL, @ActualRecord
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END ELSE IF @ActionAux = 'create' BEGIN
            UPDATE [dbo].[Operations] 
                SET [IsConfirmed] = 0
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END ELSE BEGIN
            UPDATE [dbo].[Operations]
                SET [Action] = 'delete'
                   ,[LastRecord] = @LastRecord
                   ,[ActualRecord] = NULL
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END

    RETURN CAST(@OperationId AS BIGINT)
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[ConnectionCreate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[ConnectionCreate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[ConnectionCreate] AS PRINT 1')
