/**********************************************************************************
Criar stored procedure [dbo].[SystemsDatabasesRead]
**********************************************************************************/
IF(SELECT object_id('[dbo].[SystemsDatabasesRead]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[SystemsDatabasesRead] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[SystemsDatabasesRead](@Login NVARCHAR(MAX)
                                          ,@RecordFilter NVARCHAR(MAX)
                                          ,@OrderBy NVARCHAR(MAX)
                                          ,@PaddingGridLastPage BIT
                                          ,@IsActionList BIT
                                          ,@PageNumber INT OUT
                                          ,@LimitRows INT OUT
                                          ,@MaxPage INT OUT
                                          ,@ReturnValue BIGINT OUT) AS BEGIN

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @LoginId BIGINT
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @LoginId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @LoginId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    IF @RecordFilter IS NULL
            SET @RecordFilter = '{}'
        ELSE IF ISJSON(@RecordFilter) = 0
            THROW 51000, 'Valor de @RecordFilter não está no formato JSON', 1
        SET @OrderBy = TRIM(ISNULL(@OrderBy, ''))
        IF @OrderBy = ''
            SET @OrderBy = '[Id]'
        ELSE BEGIN
            SET @OrderBy = REPLACE(REPLACE(@OrderBy, '[', ''), ']', '')
            IF EXISTS(SELECT 1 
                         FROM (SELECT CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                           WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                           ELSE TRIM([value])
                                      END AS [ColumnName]
                                  FROM STRING_SPLIT(@OrderBy, ',')) AS [O]
                                      LEFT JOIN (SELECT [#1].[name] AS ColumnName
                                                    FROM [sys].[columns] [#1]
                                                        INNER JOIN [sys].[tables] [#2] ON [#1].[object_id] = [#2].[object_id]
                                                    WHERE [#2].[name] = 'SystemsDatabases') AS [T] ON [T].[ColumnName] = [O].[ColumnName]
                         WHERE [T].[ColumnName] IS NULL)
                THROW 51000, 'Nome de coluna em @OrderBy é inválido', 1
            SELECT @OrderBy = STRING_AGG('[' + TRIM(CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                                         ELSE TRIM([value])
                                                    END) + '] ' + 
                                                    CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN 'DESC'
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN 'ASC'
                                                         ELSE 'ASC'
                                                    END, ', ')
                FROM STRING_SPLIT(@OrderBy, ',')
        END
        IF @IsActionList = 1
            SET @OrderBy = '[Name]'
        DECLARE @PickerValue nvarchar(50) = NULL

        DECLARE @TransactionId BIGINT = (SELECT MAX([Id]) FROM [dbo].[Transactions] WHERE [SessionId] = @LoginId)

        IF NOT EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [Id] = @TransactionId AND [IsConfirmed] IS NULL)
            SET @TransactionId = NULL
        SELECT [Action] AS [_]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) AS [Id]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.SystemId') AS bigint) AS [SystemId]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.DatabaseId') AS bigint) AS [DatabaseId]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Name') AS nvarchar(50)) AS [Name]
            INTO [#tmpOperations]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'SystemsDatabases'
                  AND [IsConfirmed] IS NULL
        CREATE UNIQUE INDEX [#tmpOperations] ON [#tmpOperations]([Id])

        DECLARE @_ NVARCHAR(MAX) = (SELECT STRING_AGG(value, ',') FROM OPENJSON(@RecordFilter, '$.Filter._'))
               ,@WhereFixed NVARCHAR(MAX) = ''
               ,@WhereFilter NVARCHAR(MAX) = ''
               ,@WhereSearch NVARCHAR(MAX) = ''
               ,@WhereUser NVARCHAR(MAX) = ''
               ,@Where NVARCHAR(MAX) = ''
               ,@sql NVARCHAR(MAX)

        DECLARE @W_F_Id bigint = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.Id') AS bigint)
               ,@W_U_Id bigint = CAST(JSON_VALUE(@RecordFilter, '$.Filter.Id') AS bigint)
               ,@W_S_Id bigint = CAST(JSON_VALUE(@RecordFilter, '$.Search.Id') AS bigint)
               ,@W_F_SystemId bigint = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.SystemId') AS bigint)
               ,@W_U_SystemId bigint = CAST(JSON_VALUE(@RecordFilter, '$.Filter.SystemId') AS bigint)
               ,@W_S_SystemId bigint = CAST(JSON_VALUE(@RecordFilter, '$.Search.SystemId') AS bigint)
               ,@W_F_DatabaseId bigint = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.DatabaseId') AS bigint)
               ,@W_U_DatabaseId bigint = CAST(JSON_VALUE(@RecordFilter, '$.Filter.DatabaseId') AS bigint)
               ,@W_S_DatabaseId bigint = CAST(JSON_VALUE(@RecordFilter, '$.Search.DatabaseId') AS bigint)
               ,@W_F_Name nvarchar(50) = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.Name') AS nvarchar(50))
               ,@W_U_Name nvarchar(50) = CAST(JSON_VALUE(@RecordFilter, '$.Filter.Name') AS nvarchar(50))
               ,@W_S_Name nvarchar(50) = CAST(JSON_VALUE(@RecordFilter, '$.Search.Name') AS nvarchar(50))

        IF @W_F_Id IS NOT NULL BEGIN
            IF @W_F_Id < CAST('1' AS bigint)
                THROW 51000, 'Valor de Id deve ser maior que ou igual a ''1''', 1
            SET @WhereFixed = @WhereFixed + ' AND [T].[Id] = @F_Id'
        END
        IF @W_F_SystemId IS NOT NULL BEGIN
            IF @W_F_SystemId < CAST('1' AS bigint)
                THROW 51000, 'Valor de SystemId deve ser maior que ou igual a ''1''', 1
            SET @WhereFixed = @WhereFixed + ' AND [T].[SystemId] = @F_SystemId'
        END
        IF @W_F_DatabaseId IS NOT NULL BEGIN
            IF @W_F_DatabaseId < CAST('1' AS bigint)
                THROW 51000, 'Valor de DatabaseId deve ser maior que ou igual a ''1''', 1
            SET @WhereFixed = @WhereFixed + ' AND [T].[DatabaseId] = @F_DatabaseId'
        END
        IF @W_F_Name IS NOT NULL BEGIN
            SET @WhereFixed = @WhereFixed + ' AND [T].[Name] = @F_Name'
        END
        IF @IsActionList = 1 BEGIN
            SET @PickerValue = CAST(JSON_VALUE(@RecordFilter, '$.Picker.Value') AS nvarchar(50))
            IF @PickerValue IS NULL
                SET @PickerValue = ''
            SET @WhereUser = '[T].[Name] LIKE ''%'' + @PickerValue + ''%'''
        END ELSE BEGIN
        IF @_ IS NULL BEGIN
            IF @W_U_Id IS NOT NULL BEGIN
                IF @W_U_Id < CAST('1' AS bigint)
                    THROW 51000, 'Valor de Id deve ser maior que ou igual a ''1''', 1
                SET @WhereFilter = @WhereFilter + ' AND [T].[Id] = @U_Id'
            END
            IF @W_U_SystemId IS NOT NULL BEGIN
                IF @W_U_SystemId < CAST('1' AS bigint)
                    THROW 51000, 'Valor de SystemId deve ser maior que ou igual a ''1''', 1
                SET @WhereFilter = @WhereFilter + ' AND [T].[SystemId] = @U_SystemId'
            END
            IF @W_U_DatabaseId IS NOT NULL BEGIN
                IF @W_U_DatabaseId < CAST('1' AS bigint)
                    THROW 51000, 'Valor de DatabaseId deve ser maior que ou igual a ''1''', 1
                SET @WhereFilter = @WhereFilter + ' AND [T].[DatabaseId] = @U_DatabaseId'
            END
            IF @W_U_Name IS NOT NULL BEGIN
                SET @WhereFilter = @WhereFilter + ' AND [T].[Name] = @U_Name'
            END
            IF @W_S_Id IS NOT NULL BEGIN
                IF @W_S_Id < CAST('1' AS bigint)
                    THROW 51000, 'Valor de Id deve ser maior que ou igual a ''1''', 1
                SET @WhereSearch = @WhereSearch + ' AND [T].[Id] = @S_Id'
            END
            IF @W_S_SystemId IS NOT NULL BEGIN
                IF @W_S_SystemId < CAST('1' AS bigint)
                    THROW 51000, 'Valor de SystemId deve ser maior que ou igual a ''1''', 1
                SET @WhereSearch = @WhereSearch + ' AND [T].[SystemId] = @S_SystemId'
            END
            IF @W_S_DatabaseId IS NOT NULL BEGIN
                IF @W_S_DatabaseId < CAST('1' AS bigint)
                    THROW 51000, 'Valor de DatabaseId deve ser maior que ou igual a ''1''', 1
                SET @WhereSearch = @WhereSearch + ' AND [T].[DatabaseId] = @S_DatabaseId'
            END
            IF @W_S_Name IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[Name] = @S_Name'
            END
            IF @WhereFilter <> '' AND @WhereSearch <> ''
                SET @WhereUser = '(' + STUFF(@WhereFilter, 1, 5, '') + ') OR (' + STUFF(@WhereSearch, 1, 5, '') + ')'
            ELSE IF @WhereFilter <> ''
                SET @WhereUser = STUFF(@WhereFilter, 1, 5, '')
            ELSE IF @WhereSearch <> ''
                SET @WhereUser = STUFF(@WhereSearch, 1, 5, '')
        END ELSE
            SET @WhereUser = '[T].[Id] IN (' + @_ + ')'
        END
        SET @Where = @WhereFixed
        IF @WhereUser <> ''
            SET @Where = @Where + ' AND (' + @WhereUser + ')'
        SET @sql = 'INSERT [#tmpTable]
                        SELECT ''T'' AS [_]
                              ,[T].[Id]
                            FROM [dbo].[SystemsDatabases] [T]
                                LEFT JOIN [#tmpOperations] [#] ON [#].[Id] = [T].[Id]
                            WHERE [#].[Id] IS NULL'
        SET @sql = @sql + @Where + '
                        UNION ALL
                            SELECT ''O'' AS [_]
                                  ,[T].[Id]
                                FROM [#tmpOperations] [T]
                                WHERE [T].[_] <> ''delete'''
        SET @sql = @sql + @Where
        CREATE TABLE [#tmpTable]([_] CHAR(1), [Id] bigint)
        IF @_ IS NULL
            EXEC sp_executesql @sql
                               ,N'@F_Id bigint,@U_Id bigint,@S_Id bigint
                               ,@F_SystemId bigint,@U_SystemId bigint,@S_SystemId bigint
                               ,@F_DatabaseId bigint,@U_DatabaseId bigint,@S_DatabaseId bigint
                               ,@F_Name nvarchar(50),@U_Name nvarchar(50),@S_Name nvarchar(50),@PickerValue nvarchar(50)'
                           ,@F_Id = @W_F_Id
                           ,@U_Id = @W_U_Id
                           ,@S_Id = @W_S_Id
                           ,@F_SystemId = @W_F_SystemId
                           ,@U_SystemId = @W_U_SystemId
                           ,@S_SystemId = @W_S_SystemId
                           ,@F_DatabaseId = @W_F_DatabaseId
                           ,@U_DatabaseId = @W_U_DatabaseId
                           ,@S_DatabaseId = @W_S_DatabaseId
                           ,@F_Name = @W_F_Name
                           ,@U_Name = @W_U_Name
                           ,@S_Name = @W_S_Name
                           ,@PickerValue = @PickerValue
        ELSE
            EXEC sp_executesql @sql

        DECLARE @RowCount INT = @@ROWCOUNT
               ,@OffSet INT

        CREATE UNIQUE INDEX [#tmpTable] ON [#tmpTable]([Id])
        IF @RowCount = 0 OR ISNULL(@PageNumber, 0) = 0 OR ISNULL(@LimitRows, 0) <= 0 BEGIN
            SET @OffSet = 0
            SET @LimitRows = CASE WHEN @RowCount = 0 THEN 1 ELSE @RowCount END
            SET @PageNumber = 1
            SET @MaxPage = 1
        END ELSE BEGIN
            SET @MaxPage = @RowCount / @LimitRows + CASE WHEN @RowCount % @LimitRows = 0 THEN 0 ELSE 1 END
            IF ABS(@PageNumber) > @MaxPage
                SET @PageNumber = CASE WHEN @PageNumber < 0 THEN -@MaxPage ELSE @MaxPage END
            IF @PageNumber < 0
                SET @PageNumber = @MaxPage - ABS(@PageNumber) + 1
            SET @OffSet = (@PageNumber - 1) * @LimitRows
            IF @PaddingGridLastPage = 1 AND @OffSet + @LimitRows > @RowCount
                SET @OffSet = CASE WHEN @RowCount > @LimitRows THEN @RowCount - @LimitRows ELSE 0 END
        END
        SELECT TOP 0 CAST(NULL AS NVARCHAR(50)) AS [Kind]
                    ,CAST(NULL AS bigint) AS [Id]
                    ,CAST(NULL AS bigint) AS [SystemId]
                    ,CAST(NULL AS bigint) AS [DatabaseId]
                    ,CAST(NULL AS nvarchar(50)) AS [Name]
            INTO [#result]
        SET @sql = 'INSERT #result
                        SELECT ''SystemDatabase'' AS [Kind]
                              ,[T].[Id]
                              ,[T].[SystemId]
                              ,[T].[DatabaseId]
                              ,[T].[Name]
                            FROM [#tmpTable] [#]
                                INNER JOIN [dbo].[SystemsDatabases] [T] ON [T].[Id] = [#].[Id]
                            WHERE [#].[_] = ''T''
                        UNION ALL
                            SELECT ''SystemDatabase'' AS [Kind]
                                  ,[O].[Id]
                                  ,[O].[SystemId]
                                  ,[O].[DatabaseId]
                                  ,[O].[Name]
                                FROM [#tmpTable] [#]
                                    INNER JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id]
                                WHERE [#].[_] = ''O''
                        ORDER BY ' + @OrderBy + '
                        OFFSET ' + CAST(@offset AS NVARCHAR(20)) + ' ROWS
                        FETCH NEXT ' + CAST(@LimitRows AS NVARCHAR(20)) + ' ROWS ONLY'
        EXEC sp_executesql @sql
        SELECT DISTINCT 'System' AS [Kind]
              ,[R].[Id]
              ,[R].[Name]
              ,[R].[Description]
              ,[R].[ClientName]
              ,[R].[MaxRetryLogins]
              ,[R].[IsOffAir]
            INTO [#Systems]
            FROM [#result] [T]
                INNER JOIN [dbo].[Systems] [R] ON [R].[Id] = [T].[SystemId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Systems] ON [#Systems](Id)
        SELECT DISTINCT 'Database' AS [Kind]
              ,[R].[Id]
              ,[R].[ConnectionId]
              ,[R].[Name]
              ,[R].[Alias]
              ,[R].[Description]
              ,[R].[Folder]
              ,[R].[IsLegacy]
              ,[R].[CurrentOperationId]
            INTO [#Databases]
            FROM [#result] [T]
                INNER JOIN [dbo].[Databases] [R] ON [R].[Id] = [T].[DatabaseId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Databases] ON [#Databases](Id)
        SELECT DISTINCT 'Connection' AS [Kind]
              ,[R].[Id]
              ,[R].[Environment]
              ,[R].[ConnectionString]
            INTO [#Connections]
            FROM [#Databases] [T]
                INNER JOIN [dbo].[Connections] [R] ON [R].[Id] = [T].[ConnectionId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Connections] ON [#Connections](Id)
        SELECT (SELECT [Kind]
                      ,[Id]
                      ,[SystemId]
                      ,[DatabaseId]
                      ,[Name]
                      ,[Name] AS [ListItemValue]
                    FROM [#result] FOR JSON PATH) AS [result]
              ,ISNULL((SELECT [Systems].* FROM [#Systems] AS [Systems] FOR JSON PATH), '[]') AS [Systems]
              ,ISNULL((SELECT [Databases].* FROM [#Databases] AS [Databases] FOR JSON PATH), '[]') AS [Databases]
              ,ISNULL((SELECT [Connections].* FROM [#Connections] AS [Connections] FOR JSON PATH), '[]') AS [Connections]
        SET @ReturnValue = @RowCount

    RETURN 0
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[TableValidate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[TableValidate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[TableValidate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[TableValidate](@SessionId BIGINT
                                               ,@TransactionId BIGINT
                                               ,@UserName NVARCHAR(25)
                                               ,@Action NVARCHAR(15)
                                               ,@LastRecord NVARCHAR(max)
                                               ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED
    IF @SessionId IS NULL
            THROW 51000, 'Valor de @SessionId é requerido', 1
        IF @UserName IS NULL
            THROW 51000, 'Valor de @UserName é requerido', 1
        IF @Action IS NULL
            THROW 51000, 'Valor de @Action é requerido', 1
        IF @Action NOT IN ('create', 'update', 'delete')
            THROW 51000, 'Valor de @Action é inválido', 1
        IF @Action = 'delete' BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
        END ELSE BEGIN
            IF @ActualRecord IS NULL
                THROW 51000, 'Valor de @ActualRecord é requerido', 1
            IF ISJSON(@ActualRecord) = 0
                THROW 51000, 'Valor de @ActualRecord não está no formato JSON', 1
        END
        IF @TransactionId IS NULL
            THROW 51000, 'Valor de @TransactionId é requerido', 1
        DECLARE @IsConfirmed BIT
               ,@CreatedBy NVARCHAR(25)
               ,@IsPendingCreate BIT = 0
               ,@W_Id AS bigint

        IF @Action = 'delete'
            SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)
        ELSE
            SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        SELECT @IsConfirmed = [IsConfirmed]
              ,@CreatedBy = [CreatedBy]
            FROM [dbo].[Transactions]
            WHERE [Id] = @TransactionId
                  AND [SessionId] = @SessionId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Transação inexistente', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Transação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1;
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @W_Id IS NULL BEGIN
            SET @ErrorMessage = 'Valor de Id em @ActualRecord é requerido.';
            THROW 51000, @ErrorMessage, 1
        END
        IF @W_Id < CAST('1' AS bigint)
            THROW 51000, 'Valor de Id em @ActualRecord deve ser maior que ou igual a 1', 1
        IF EXISTS(SELECT 1 FROM [dbo].[Tables] WHERE [Id] = @W_Id) BEGIN
            IF @Action = 'create'
                THROW 51000, 'Chave-primária já existe em Tables', 1
        END ELSE IF @Action = 'delete' AND EXISTS(SELECT 1
                                    FROM [dbo].[Operations]
                                    WHERE [TransactionId] = @TransactionId
                                          AND [TableName] = 'Tables'
                                          AND [IsConfirmed] IS NULL
                                          AND [Action] = 'create'
                                          AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id)
            SET @IsPendingCreate = 1
        ELSE IF @Action <> 'create'
            THROW 51000, 'Chave-primária não existe em Tables', 1
        IF @Action <> 'create' AND @IsPendingCreate = 0 BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
            IF NOT EXISTS(SELECT 1
                            FROM [dbo].[Tables]
                            WHERE [Id] = JSON_VALUE(@LastRecord, '$.Id')
                                  AND [Name] = JSON_VALUE(@LastRecord, '$.Name')
                                  AND [Alias] = JSON_VALUE(@LastRecord, '$.Alias')
                                  AND [Description] = JSON_VALUE(@LastRecord, '$.Description')
                                  AND [dbo].[IS_EQUAL]([ParentTableId], JSON_VALUE(@LastRecord, '$.ParentTableId'), 'bigint') = 1
                                  AND [IsLegacy] = JSON_VALUE(@LastRecord, '$.IsLegacy')
                                  AND [CurrentId] = JSON_VALUE(@LastRecord, '$.CurrentId'))
            AND NOT EXISTS(SELECT 1
                            FROM [dbo].[Operations]
                            WHERE [TransactionId] = @TransactionId
                                  AND [TableName] = 'Tables'
                                  AND [IsConfirmed] IS NULL
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') = JSON_VALUE(@LastRecord, '$.Id')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Name') = JSON_VALUE(@LastRecord, '$.Name')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Alias') = JSON_VALUE(@LastRecord, '$.Alias')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Description') = JSON_VALUE(@LastRecord, '$.Description')
                                  AND [dbo].[IS_EQUAL](JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.ParentTableId'), JSON_VALUE(@LastRecord, '$.ParentTableId'), 'bigint') = 1
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsLegacy') = JSON_VALUE(@LastRecord, '$.IsLegacy')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.CurrentId') = JSON_VALUE(@LastRecord, '$.CurrentId'))
                THROW 51000, 'Registro de Tables alterado por outro usuário', 1
        END

        IF @Action = 'delete' BEGIN
            IF EXISTS(SELECT 1 FROM [dbo].[Tables] WHERE [ParentTableId] = @W_Id)
                THROW 51000, 'Chave-primária referenciada em Tables', 1
            IF EXISTS(SELECT 1 FROM [dbo].[DatabasesTables] WHERE [TableId] = @W_Id)
                THROW 51000, 'Chave-primária referenciada em DatabasesTables', 1
            IF EXISTS(SELECT 1 FROM [dbo].[Columns] WHERE [TableId] = @W_Id)
                THROW 51000, 'Chave-primária referenciada em Columns', 1
            IF EXISTS(SELECT 1 FROM [dbo].[Columns] WHERE [ReferenceTableId] = @W_Id)
                THROW 51000, 'Chave-primária referenciada em Columns', 1
            IF EXISTS(SELECT 1 FROM [dbo].[Indexes] WHERE [TableId] = @W_Id)
                THROW 51000, 'Chave-primária referenciada em Indexes', 1
        END
        IF @Action IN ('create', 'update') BEGIN

            DECLARE @W_Name nvarchar(25) = CAST(JSON_VALUE(@ActualRecord, '$.Name') AS nvarchar(25))
                   ,@W_Alias nvarchar(25) = CAST(JSON_VALUE(@ActualRecord, '$.Alias') AS nvarchar(25))
                   ,@W_Description nvarchar(50) = CAST(JSON_VALUE(@ActualRecord, '$.Description') AS nvarchar(50))
                   ,@W_ParentTableId bigint = CAST(JSON_VALUE(@ActualRecord, '$.ParentTableId') AS bigint)
                   ,@W_IsLegacy bit = CAST(JSON_VALUE(@ActualRecord, '$.IsLegacy') AS bit)
                   ,@W_CurrentId bigint = CAST(JSON_VALUE(@ActualRecord, '$.CurrentId') AS bigint)

            IF @W_Name IS NULL
                THROW 51000, 'Valor de Name em @ActualRecord é requerido.', 1
            IF @W_Alias IS NULL
                THROW 51000, 'Valor de Alias em @ActualRecord é requerido.', 1
            IF @W_Description IS NULL
                THROW 51000, 'Valor de Description em @ActualRecord é requerido.', 1
            IF @W_ParentTableId IS NOT NULL AND @W_ParentTableId < CAST('0' AS bigint)
                THROW 51000, 'Valor de ParentTableId em @ActualRecord deve ser maior que ou igual a 0', 1
            IF @W_ParentTableId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM [dbo].[Tables] WHERE [Id] = @W_ParentTableId)
                THROW 51000, 'Valor de ParentTableId em @ActualRecord inexiste em Tables', 1
            IF @W_IsLegacy IS NULL
                THROW 51000, 'Valor de IsLegacy em @ActualRecord é requerido.', 1
            IF @W_CurrentId IS NULL
                THROW 51000, 'Valor de CurrentId em @ActualRecord é requerido.', 1
            IF @W_CurrentId < CAST('0' AS bigint)
                THROW 51000, 'Valor de CurrentId em @ActualRecord deve ser maior que ou igual a 0', 1
            IF @Action = 'create' BEGIN
                IF EXISTS(SELECT 1 FROM [dbo].[Tables] WHERE [Name] = @W_Name)
                    THROW 51000, 'Chave única de UNQ_Tables_Name já existe', 1
                IF EXISTS(SELECT 1 FROM [dbo].[Tables] WHERE [Alias] = @W_Alias)
                    THROW 51000, 'Chave única de UNQ_Tables_Alias já existe', 1
            ELSE IF EXISTS(SELECT 1 FROM [dbo].[Tables] WHERE [Name] = @W_Name AND [Id] <> @W_Id)
                THROW 51000, 'Chave única de UNQ_Tables_Name já existe', 1
            ELSE IF EXISTS(SELECT 1 FROM [dbo].[Tables] WHERE [Alias] = @W_Alias AND [Id] <> @W_Id)
                THROW 51000, 'Chave única de UNQ_Tables_Alias já existe', 1
            END
        END

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[TablePersist]
**********************************************************************************/
IF(SELECT object_id('[dbo].[TablePersist]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[TablePersist] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[TablePersist](@Login NVARCHAR(MAX)
                                              ,@TransactionId BIGINT
                                              ,@Action NVARCHAR(15)
                                              ,@LastRecord NVARCHAR(max)
                                              ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(255)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    DECLARE @OperationId BIGINT
               ,@CreatedBy NVARCHAR(25)
               ,@ActionAux NVARCHAR(15)
               ,@IsConfirmed BIT
           ,@W_Id bigint

    IF @Action = 'delete'
        SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)
    ELSE
        SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

    IF @Action = 'create' AND @W_Id IS NULL BEGIN
        SELECT @W_Id = CAST(JSON_VALUE([ActualRecord], '$.Id') AS bigint)
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Tables'
                  AND [Action] = 'create'
                  AND [IsConfirmed] IS NULL
        IF @W_Id IS NULL BEGIN
            DECLARE @NewId BIGINT
    EXEC [dbo].[NewId] 'crudex', 'crudex', 'Tables', @NewId OUT
            SET @W_Id = CAST(@NewId AS bigint)
        END
        SET @ActualRecord = JSON_MODIFY(@ActualRecord, '$.Id', @W_Id)
    END

    EXEC @TransactionId = [dbo].[TableValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        SELECT @OperationId = [Id]
              ,@CreatedBy = [CreatedBy]
              ,@ActionAux = [Action]
              ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Tables'
                  AND [IsConfirmed] IS NULL
                  AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id
        IF @@ROWCOUNT = 0 BEGIN
            EXEC [dbo].[NewOperationId] 'crudex', 'crudex', @OperationId OUT
            INSERT INTO [dbo].[Operations] ([Id]
                                             ,[TransactionId]
                                             ,[TableName]
                                             ,[Action]
                                             ,[LastRecord]
                                             ,[ActualRecord]
                                             ,[IsConfirmed]
                                             ,[CreatedAt]
                                             ,[CreatedBy])
                                       VALUES(@OperationId
                                             ,@TransactionId
                                             ,'Tables'
                                             ,@Action
                                             ,@LastRecord
                                             ,@ActualRecord
                                             ,NULL
                                             ,GETDATE()
                                             ,@UserName)
        END ELSE IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END ELSE IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        ELSE IF @ActionAux = 'delete'
            THROW 51000, 'Registro excluído nesta transação', 1
        ELSE IF @Action = 'create' BEGIN
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END
        ELSE IF @Action = 'update' BEGIN
            IF @ActionAux = 'create'
                EXEC [dbo].[TableValidate] @SessionId, @TransactionId, @UserName, 'create', NULL, @ActualRecord
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END ELSE IF @ActionAux = 'create' BEGIN
            UPDATE [dbo].[Operations] 
                SET [IsConfirmed] = 0
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END ELSE BEGIN
            UPDATE [dbo].[Operations]
                SET [Action] = 'delete'
                   ,[LastRecord] = @LastRecord
                   ,[ActualRecord] = NULL
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END

    RETURN CAST(@OperationId AS BIGINT)
END
GO

