                    THROW 51000, 'Valor de DomainId deve ser maior que ou igual a ''1''', 1
                SET @WhereSearch = @WhereSearch + ' AND [T].[DomainId] = @S_DomainId'
            END
            IF @W_S_ReferenceTableId IS NOT NULL BEGIN
                IF @W_S_ReferenceTableId < CAST('1' AS bigint)
                    THROW 51000, 'Valor de ReferenceTableId deve ser maior que ou igual a ''1''', 1
                SET @WhereSearch = @WhereSearch + ' AND [T].[ReferenceTableId] = @S_ReferenceTableId'
            END
            IF @W_S_Name IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[Name] = @S_Name'
            END
            IF @W_S_Alias IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[Alias] = @S_Alias'
            END
            IF @W_S_IsAutoIncrement IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[IsAutoIncrement] = @S_IsAutoIncrement'
            END
            IF @W_S_IsRequired IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[IsRequired] = @S_IsRequired'
            END
            IF @W_S_IsListable IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[IsListable] = @S_IsListable'
            END
            IF @W_S_IsFilterable IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[IsFilterable] = @S_IsFilterable'
            END
            IF @W_S_IsEditable IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[IsEditable] = @S_IsEditable'
            END
            IF @W_S_IsGridable IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[IsGridable] = @S_IsGridable'
            END
            IF @W_S_IsEncrypted IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[IsEncrypted] = @S_IsEncrypted'
            END
            IF @W_S_IsInWords IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[IsInWords] = @S_IsInWords'
            END
            IF @WhereFilter <> '' AND @WhereSearch <> ''
                SET @WhereUser = '(' + STUFF(@WhereFilter, 1, 5, '') + ') OR (' + STUFF(@WhereSearch, 1, 5, '') + ')'
            ELSE IF @WhereFilter <> ''
                SET @WhereUser = STUFF(@WhereFilter, 1, 5, '')
            ELSE IF @WhereSearch <> ''
                SET @WhereUser = STUFF(@WhereSearch, 1, 5, '')
        END ELSE
            SET @WhereUser = '[T].[Id] IN (' + @_ + ')'
        SET @Where = @WhereFixed
        IF @WhereUser <> ''
            SET @Where = @Where + ' AND (' + @WhereUser + ')'
        SET @sql = 'INSERT [#tmpTable]
                        SELECT ''T'' AS [_]
                              ,[T].[Id]
                            FROM [dbo].[Columns] [T]
                                LEFT JOIN [#tmpOperations] [#] ON [#].[Id] = [T].[Id]
                            WHERE [#].[Id] IS NULL'
        SET @sql = @sql + @Where + '
                        UNION ALL
                            SELECT ''O'' AS [_]
                                  ,[T].[Id]
                                FROM [#tmpOperations] [T]
                                WHERE [T].[_] <> ''delete'''
        SET @sql = @sql + @Where
        CREATE TABLE [#tmpTable]([_] CHAR(1), [Id] bigint)
        IF @_ IS NULL
            EXEC sp_executesql @sql
                               ,N'@F_Id bigint,@U_Id bigint,@S_Id bigint
                               ,@F_TableId bigint,@U_TableId bigint,@S_TableId bigint
                               ,@F_DomainId bigint,@U_DomainId bigint,@S_DomainId bigint
                               ,@F_ReferenceTableId bigint,@U_ReferenceTableId bigint,@S_ReferenceTableId bigint
                               ,@F_Name nvarchar(25),@U_Name nvarchar(25),@S_Name nvarchar(25)
                               ,@F_Alias nvarchar(25),@U_Alias nvarchar(25),@S_Alias nvarchar(25)
                               ,@F_IsAutoIncrement bit,@U_IsAutoIncrement bit,@S_IsAutoIncrement bit
                               ,@F_IsRequired bit,@U_IsRequired bit,@S_IsRequired bit
                               ,@F_IsListable bit,@U_IsListable bit,@S_IsListable bit
                               ,@F_IsFilterable bit,@U_IsFilterable bit,@S_IsFilterable bit
                               ,@F_IsEditable bit,@U_IsEditable bit,@S_IsEditable bit
                               ,@F_IsGridable bit,@U_IsGridable bit,@S_IsGridable bit
                               ,@F_IsEncrypted bit,@U_IsEncrypted bit,@S_IsEncrypted bit
                               ,@F_IsInWords bit,@U_IsInWords bit,@S_IsInWords bit'
                           ,@F_Id = @W_F_Id
                           ,@U_Id = @W_U_Id
                           ,@S_Id = @W_S_Id
                           ,@F_TableId = @W_F_TableId
                           ,@U_TableId = @W_U_TableId
                           ,@S_TableId = @W_S_TableId
                           ,@F_DomainId = @W_F_DomainId
                           ,@U_DomainId = @W_U_DomainId
                           ,@S_DomainId = @W_S_DomainId
                           ,@F_ReferenceTableId = @W_F_ReferenceTableId
                           ,@U_ReferenceTableId = @W_U_ReferenceTableId
                           ,@S_ReferenceTableId = @W_S_ReferenceTableId
                           ,@F_Name = @W_F_Name
                           ,@U_Name = @W_U_Name
                           ,@S_Name = @W_S_Name
                           ,@F_Alias = @W_F_Alias
                           ,@U_Alias = @W_U_Alias
                           ,@S_Alias = @W_S_Alias
                           ,@F_IsAutoIncrement = @W_F_IsAutoIncrement
                           ,@U_IsAutoIncrement = @W_U_IsAutoIncrement
                           ,@S_IsAutoIncrement = @W_S_IsAutoIncrement
                           ,@F_IsRequired = @W_F_IsRequired
                           ,@U_IsRequired = @W_U_IsRequired
                           ,@S_IsRequired = @W_S_IsRequired
                           ,@F_IsListable = @W_F_IsListable
                           ,@U_IsListable = @W_U_IsListable
                           ,@S_IsListable = @W_S_IsListable
                           ,@F_IsFilterable = @W_F_IsFilterable
                           ,@U_IsFilterable = @W_U_IsFilterable
                           ,@S_IsFilterable = @W_S_IsFilterable
                           ,@F_IsEditable = @W_F_IsEditable
                           ,@U_IsEditable = @W_U_IsEditable
                           ,@S_IsEditable = @W_S_IsEditable
                           ,@F_IsGridable = @W_F_IsGridable
                           ,@U_IsGridable = @W_U_IsGridable
                           ,@S_IsGridable = @W_S_IsGridable
                           ,@F_IsEncrypted = @W_F_IsEncrypted
                           ,@U_IsEncrypted = @W_U_IsEncrypted
                           ,@S_IsEncrypted = @W_S_IsEncrypted
                           ,@F_IsInWords = @W_F_IsInWords
                           ,@U_IsInWords = @W_U_IsInWords
                           ,@S_IsInWords = @W_S_IsInWords
        ELSE
            EXEC sp_executesql @sql

        DECLARE @RowCount INT = @@ROWCOUNT
               ,@OffSet INT

        CREATE UNIQUE INDEX [#tmpTable] ON [#tmpTable]([Id])
        IF @RowCount = 0 OR ISNULL(@PageNumber, 0) = 0 OR ISNULL(@LimitRows, 0) <= 0 BEGIN
            SET @OffSet = 0
            SET @LimitRows = CASE WHEN @RowCount = 0 THEN 1 ELSE @RowCount END
            SET @PageNumber = 1
            SET @MaxPage = 1
        END ELSE BEGIN
            SET @MaxPage = @RowCount / @LimitRows + CASE WHEN @RowCount % @LimitRows = 0 THEN 0 ELSE 1 END
            IF ABS(@PageNumber) > @MaxPage
                SET @PageNumber = CASE WHEN @PageNumber < 0 THEN -@MaxPage ELSE @MaxPage END
            IF @PageNumber < 0
                SET @PageNumber = @MaxPage - ABS(@PageNumber) + 1
            SET @OffSet = (@PageNumber - 1) * @LimitRows
            IF @PaddingGridLastPage = 1 AND @OffSet + @LimitRows > @RowCount
                SET @OffSet = CASE WHEN @RowCount > @LimitRows THEN @RowCount - @LimitRows ELSE 0 END
        END
        SELECT TOP 0 CAST(NULL AS NVARCHAR(50)) AS [Kind]
                    ,CAST(NULL AS bigint) AS [Id]
                    ,CAST(NULL AS bigint) AS [TableId]
                    ,CAST(NULL AS smallint) AS [Sequence]
                    ,CAST(NULL AS bigint) AS [DomainId]
                    ,CAST(NULL AS bigint) AS [ReferenceTableId]
                    ,CAST(NULL AS nvarchar(25)) AS [Name]
                    ,CAST(NULL AS nvarchar(25)) AS [Alias]
                    ,CAST(NULL AS nvarchar(50)) AS [Description]
                    ,CAST(NULL AS nvarchar(25)) AS [Title]
                    ,CAST(NULL AS nvarchar(25)) AS [Caption]
                    ,CAST(NULL AS nvarchar(max)) AS [Default]
                    ,CAST(NULL AS nvarchar(max)) AS [Minimum]
                    ,CAST(NULL AS nvarchar(max)) AS [Maximum]
                    ,CAST(NULL AS bit) AS [IsPrimarykey]
                    ,CAST(NULL AS bit) AS [IsAutoIncrement]
                    ,CAST(NULL AS bit) AS [IsRequired]
                    ,CAST(NULL AS bit) AS [IsListable]
                    ,CAST(NULL AS bit) AS [IsFilterable]
                    ,CAST(NULL AS bit) AS [IsEditable]
                    ,CAST(NULL AS bit) AS [IsGridable]
                    ,CAST(NULL AS bit) AS [IsEncrypted]
                    ,CAST(NULL AS bit) AS [IsInWords]
            INTO [#result]
        SET @sql = 'INSERT #result
                        SELECT ''Column'' AS [Kind]
                              ,[T].[Id]
                              ,[T].[TableId]
                              ,[T].[Sequence]
                              ,[T].[DomainId]
                              ,[T].[ReferenceTableId]
                              ,[T].[Name]
                              ,[T].[Alias]
                              ,[T].[Description]
                              ,[T].[Title]
                              ,[T].[Caption]
                              ,[T].[Default]
                              ,[T].[Minimum]
                              ,[T].[Maximum]
                              ,[T].[IsPrimarykey]
                              ,[T].[IsAutoIncrement]
                              ,[T].[IsRequired]
                              ,[T].[IsListable]
                              ,[T].[IsFilterable]
                              ,[T].[IsEditable]
                              ,[T].[IsGridable]
                              ,[T].[IsEncrypted]
                              ,[T].[IsInWords]
                            FROM [#tmpTable] [#]
                                INNER JOIN [dbo].[Columns] [T] ON [T].[Id] = [#].[Id]
                            WHERE [#].[_] = ''T''
                        UNION ALL
                            SELECT ''Column'' AS [Kind]
                                  ,[O].[Id]
                                  ,[O].[TableId]
                                  ,[O].[Sequence]
                                  ,[O].[DomainId]
                                  ,[O].[ReferenceTableId]
                                  ,[O].[Name]
                                  ,[O].[Alias]
                                  ,[O].[Description]
                                  ,[O].[Title]
                                  ,[O].[Caption]
                                  ,[O].[Default]
                                  ,[O].[Minimum]
                                  ,[O].[Maximum]
                                  ,[O].[IsPrimarykey]
                                  ,[O].[IsAutoIncrement]
                                  ,[O].[IsRequired]
                                  ,[O].[IsListable]
                                  ,[O].[IsFilterable]
                                  ,[O].[IsEditable]
                                  ,[O].[IsGridable]
                                  ,[O].[IsEncrypted]
                                  ,[O].[IsInWords]
                                FROM [#tmpTable] [#]
                                    INNER JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id]
                                WHERE [#].[_] = ''O''
                        ORDER BY ' + @OrderBy + '
                        OFFSET ' + CAST(@offset AS NVARCHAR(20)) + ' ROWS
                        FETCH NEXT ' + CAST(@LimitRows AS NVARCHAR(20)) + ' ROWS ONLY'
        EXEC sp_executesql @sql
        SELECT DISTINCT 'Table' AS [Kind]
              ,[R].[Id]
              ,[R].[Name]
              ,[R].[Alias]
              ,[R].[Description]
              ,[R].[ParentTableId]
              ,[R].[IsLegacy]
              ,[R].[CurrentId]
            INTO [#Tables]
            FROM [#result] [T]
                INNER JOIN [dbo].[Tables] [R] ON [R].[Id] = [T].[TableId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Tables] ON [#Tables](Id)
        INSERT INTO [#Tables]
            SELECT DISTINCT 'Table' AS [Kind]
                  ,[R].[Id]
                  ,[R].[Name]
                  ,[R].[Alias]
                  ,[R].[Description]
                  ,[R].[ParentTableId]
                  ,[R].[IsLegacy]
                  ,[R].[CurrentId]
                FROM [#Tables] [T]
                    INNER JOIN [dbo].[Tables] [R] ON [R].[Id] = [T].[ParentTableId]
                WHERE NOT EXISTS(SELECT 1 FROM [#Tables] WHERE [Id] = [R].[Id])
                ORDER BY [R].[Id]
        SELECT DISTINCT 'Domain' AS [Kind]
              ,[R].[Id]
              ,[R].[TypeId]
              ,[R].[MaskId]
              ,[R].[Name]
              ,[R].[Length]
              ,[R].[Decimals]
              ,[R].[ValidValues]
              ,[R].[Default]
              ,[R].[Minimum]
              ,[R].[Maximum]
              ,[R].[Codification]
            INTO [#Domains]
            FROM [#result] [T]
                INNER JOIN [dbo].[Domains] [R] ON [R].[Id] = [T].[DomainId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Domains] ON [#Domains](Id)
        SELECT DISTINCT 'Type' AS [Kind]
              ,[R].[Id]
              ,[R].[CategoryId]
              ,[R].[Name]
              ,[R].[MaxLength]
              ,[R].[Minimum]
              ,[R].[Maximum]
              ,[R].[AskLength]
              ,[R].[AskDecimals]
              ,[R].[AskPrimarykey]
              ,[R].[AskAutoincrement]
              ,[R].[AskFilterable]
              ,[R].[AskGridable]
              ,[R].[AskCodification]
              ,[R].[IsLikeable]
              ,[R].[IsActive]
            INTO [#Types]
            FROM [#Domains] [T]
                INNER JOIN [dbo].[Types] [R] ON [R].[Id] = [T].[TypeId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Types] ON [#Types](Id)
        SELECT DISTINCT 'Category' AS [Kind]
              ,[R].[Id]
              ,[R].[Name]
              ,[R].[HtmlInputType]
              ,[R].[HtmlInputAlign]
              ,[R].[AskEncrypted]
              ,[R].[AskMask]
              ,[R].[AskListable]
              ,[R].[AskDefault]
              ,[R].[AskMinimum]
              ,[R].[AskMaximum]
              ,[R].[AskInWords]
            INTO [#Categories]
            FROM [#Types] [T]
                INNER JOIN [dbo].[Categories] [R] ON [R].[Id] = [T].[CategoryId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Categories] ON [#Categories](Id)
        INSERT INTO [#Tables]
            SELECT DISTINCT 'Table' AS [Kind]
                  ,[R].[Id]
                  ,[R].[Name]
                  ,[R].[Alias]
                  ,[R].[Description]
                  ,[R].[ParentTableId]
                  ,[R].[IsLegacy]
                  ,[R].[CurrentId]
                FROM [#result] [T]
                    INNER JOIN [dbo].[Tables] [R] ON [R].[Id] = [T].[ReferenceTableId]
                WHERE NOT EXISTS(SELECT 1 FROM [#Tables] WHERE [Id] = [R].[Id])
                ORDER BY [R].[Id]
        INSERT INTO [#Tables]
            SELECT DISTINCT 'Table' AS [Kind]
                  ,[R].[Id]
                  ,[R].[Name]
                  ,[R].[Alias]
                  ,[R].[Description]
                  ,[R].[ParentTableId]
                  ,[R].[IsLegacy]
                  ,[R].[CurrentId]
                FROM [#Tables] [T]
                    INNER JOIN [dbo].[Tables] [R] ON [R].[Id] = [T].[ParentTableId]
                WHERE NOT EXISTS(SELECT 1 FROM [#Tables] WHERE [Id] = [R].[Id])
                ORDER BY [R].[Id]
        SELECT (SELECT [Kind]
                      ,[Id]
                      ,[TableId]
                      ,[Sequence]
                      ,[DomainId]
                      ,[ReferenceTableId]
                      ,[Name]
                      ,[Alias]
                      ,[Description]
                      ,[Title]
                      ,[Caption]
                      ,[Default]
                      ,[Minimum]
                      ,[Maximum]
                      ,[IsPrimarykey]
                      ,[IsAutoIncrement]
                      ,[IsRequired]
                      ,[IsListable]
                      ,[IsFilterable]
                      ,[IsEditable]
                      ,[IsGridable]
                      ,[IsEncrypted]
                      ,[IsInWords]
                    FROM [#result] FOR JSON PATH) AS [result]
              ,ISNULL((SELECT [Tables].* FROM [#Tables] AS [Tables] FOR JSON PATH), '[]') AS [Tables]
              ,ISNULL((SELECT [Domains].* FROM [#Domains] AS [Domains] FOR JSON PATH), '[]') AS [Domains]
              ,ISNULL((SELECT [Types].* FROM [#Types] AS [Types] FOR JSON PATH), '[]') AS [Types]
              ,ISNULL((SELECT [Categories].* FROM [#Categories] AS [Categories] FOR JSON PATH), '[]') AS [Categories]
        SET @ReturnValue = @RowCount

    RETURN 0
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[IndexValidate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[IndexValidate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[IndexValidate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[IndexValidate](@SessionId BIGINT
                                               ,@TransactionId BIGINT
                                               ,@UserName NVARCHAR(25)
                                               ,@Action NVARCHAR(15)
                                               ,@LastRecord NVARCHAR(max)
                                               ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED
    IF @SessionId IS NULL
            THROW 51000, 'Valor de @SessionId é requerido', 1
        IF @UserName IS NULL
            THROW 51000, 'Valor de @UserName é requerido', 1
        IF @Action IS NULL
            THROW 51000, 'Valor de @Action é requerido', 1
        IF @Action NOT IN ('create', 'update', 'delete')
            THROW 51000, 'Valor de @Action é inválido', 1
        IF @Action = 'delete' BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
        END ELSE BEGIN
            IF @ActualRecord IS NULL
                THROW 51000, 'Valor de @ActualRecord é requerido', 1
            IF ISJSON(@ActualRecord) = 0
                THROW 51000, 'Valor de @ActualRecord não está no formato JSON', 1
        END
        IF @TransactionId IS NULL
            THROW 51000, 'Valor de @TransactionId é requerido', 1
        DECLARE @IsConfirmed BIT
               ,@CreatedBy NVARCHAR(25)
               ,@IsPendingCreate BIT = 0
               ,@W_Id AS bigint

        IF @Action = 'delete'
            SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)
        ELSE
            SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        SELECT @IsConfirmed = [IsConfirmed]
              ,@CreatedBy = [CreatedBy]
            FROM [dbo].[Transactions]
            WHERE [Id] = @TransactionId
                  AND [SessionId] = @SessionId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Transação inexistente', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Transação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1;
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @W_Id IS NULL BEGIN
            SET @ErrorMessage = 'Valor de Id em @ActualRecord é requerido.';
            THROW 51000, @ErrorMessage, 1
        END
        IF @W_Id < CAST('1' AS bigint)
            THROW 51000, 'Valor de Id em @ActualRecord deve ser maior que ou igual a 1', 1
        IF EXISTS(SELECT 1 FROM [dbo].[Indexes] WHERE [Id] = @W_Id) BEGIN
            IF @Action = 'create'
                THROW 51000, 'Chave-primária já existe em Indexes', 1
        END ELSE IF @Action = 'delete' AND EXISTS(SELECT 1
                                    FROM [dbo].[Operations]
                                    WHERE [TransactionId] = @TransactionId
                                          AND [TableName] = 'Indexes'
                                          AND [IsConfirmed] IS NULL
                                          AND [Action] = 'create'
                                          AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id)
            SET @IsPendingCreate = 1
        ELSE IF @Action <> 'create'
            THROW 51000, 'Chave-primária não existe em Indexes', 1
        IF @Action <> 'create' AND @IsPendingCreate = 0 BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
            IF NOT EXISTS(SELECT 1
                            FROM [dbo].[Indexes]
                            WHERE [Id] = JSON_VALUE(@LastRecord, '$.Id')
                                  AND [TableId] = JSON_VALUE(@LastRecord, '$.TableId')
                                  AND [Name] = JSON_VALUE(@LastRecord, '$.Name')
                                  AND [IsUnique] = JSON_VALUE(@LastRecord, '$.IsUnique'))
            AND NOT EXISTS(SELECT 1
                            FROM [dbo].[Operations]
                            WHERE [TransactionId] = @TransactionId
                                  AND [TableName] = 'Indexes'
                                  AND [IsConfirmed] IS NULL
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') = JSON_VALUE(@LastRecord, '$.Id')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.TableId') = JSON_VALUE(@LastRecord, '$.TableId')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Name') = JSON_VALUE(@LastRecord, '$.Name')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsUnique') = JSON_VALUE(@LastRecord, '$.IsUnique'))
                THROW 51000, 'Registro de Indexes alterado por outro usuário', 1
        END

        IF @Action = 'delete' BEGIN
            IF EXISTS(SELECT 1 FROM [dbo].[Indexkeys] WHERE [IndexId] = @W_Id)
                THROW 51000, 'Chave-primária referenciada em Indexkeys', 1
        END
        IF @Action IN ('create', 'update') BEGIN

            DECLARE @W_TableId bigint = CAST(JSON_VALUE(@ActualRecord, '$.TableId') AS bigint)
                   ,@W_Name nvarchar(50) = CAST(JSON_VALUE(@ActualRecord, '$.Name') AS nvarchar(50))
                   ,@W_IsUnique bit = CAST(JSON_VALUE(@ActualRecord, '$.IsUnique') AS bit)

            IF @W_TableId IS NULL
                THROW 51000, 'Valor de TableId em @ActualRecord é requerido.', 1
            IF @W_TableId < CAST('1' AS bigint)
                THROW 51000, 'Valor de TableId em @ActualRecord deve ser maior que ou igual a 1', 1
            IF NOT EXISTS(SELECT 1 FROM [dbo].[Tables] WHERE [Id] = @W_TableId)
                THROW 51000, 'Valor de TableId em @ActualRecord inexiste em Tables', 1
            IF @W_Name IS NULL
                THROW 51000, 'Valor de Name em @ActualRecord é requerido.', 1
            IF @W_IsUnique IS NULL
                THROW 51000, 'Valor de IsUnique em @ActualRecord é requerido.', 1
            IF @Action = 'create' BEGIN
                IF EXISTS(SELECT 1 FROM [dbo].[Indexes] WHERE [Name] = @W_Name)
                    THROW 51000, 'Chave única de UNQ_Indexes_Name já existe', 1
            ELSE IF EXISTS(SELECT 1 FROM [dbo].[Indexes] WHERE [Name] = @W_Name AND [Id] <> @W_Id)
                THROW 51000, 'Chave única de UNQ_Indexes_Name já existe', 1
            END
        END

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[IndexPersist]
**********************************************************************************/
IF(SELECT object_id('[dbo].[IndexPersist]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[IndexPersist] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[IndexPersist](@Login NVARCHAR(MAX)
                                              ,@TransactionId BIGINT
                                              ,@Action NVARCHAR(15)
                                              ,@LastRecord NVARCHAR(max)
                                              ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(255)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    DECLARE @OperationId BIGINT
               ,@CreatedBy NVARCHAR(25)
               ,@ActionAux NVARCHAR(15)
               ,@IsConfirmed BIT
           ,@W_Id bigint

    IF @Action = 'delete'
        SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)
    ELSE
        SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

    IF @Action = 'create' AND @W_Id IS NULL BEGIN
        SELECT @W_Id = CAST(JSON_VALUE([ActualRecord], '$.Id') AS bigint)
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Indexes'
                  AND [Action] = 'create'
                  AND [IsConfirmed] IS NULL
        IF @W_Id IS NULL BEGIN
            DECLARE @NewId BIGINT
    EXEC [dbo].[NewId] 'crudex', 'crudex', 'Indexes', @NewId OUT
            SET @W_Id = CAST(@NewId AS bigint)
        END
        SET @ActualRecord = JSON_MODIFY(@ActualRecord, '$.Id', @W_Id)
    END

    EXEC @TransactionId = [dbo].[IndexValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        SELECT @OperationId = [Id]
              ,@CreatedBy = [CreatedBy]
              ,@ActionAux = [Action]
              ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Indexes'
                  AND [IsConfirmed] IS NULL
                  AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id
        IF @@ROWCOUNT = 0 BEGIN
            EXEC [dbo].[NewOperationId] 'crudex', 'crudex', @OperationId OUT
            INSERT INTO [dbo].[Operations] ([Id]
                                             ,[TransactionId]
                                             ,[TableName]
                                             ,[Action]
                                             ,[LastRecord]
                                             ,[ActualRecord]
                                             ,[IsConfirmed]
                                             ,[CreatedAt]
                                             ,[CreatedBy])
                                       VALUES(@OperationId
                                             ,@TransactionId
                                             ,'Indexes'
                                             ,@Action
                                             ,@LastRecord
                                             ,@ActualRecord
                                             ,NULL
                                             ,GETDATE()
                                             ,@UserName)
        END ELSE IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END ELSE IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        ELSE IF @ActionAux = 'delete'
            THROW 51000, 'Registro excluído nesta transação', 1
        ELSE IF @Action = 'create' BEGIN
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END
        ELSE IF @Action = 'update' BEGIN
            IF @ActionAux = 'create'
                EXEC [dbo].[IndexValidate] @SessionId, @TransactionId, @UserName, 'create', NULL, @ActualRecord
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END ELSE IF @ActionAux = 'create' BEGIN
            UPDATE [dbo].[Operations] 
                SET [IsConfirmed] = 0
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END ELSE BEGIN
            UPDATE [dbo].[Operations]
                SET [Action] = 'delete'
                   ,[LastRecord] = @LastRecord
                   ,[ActualRecord] = NULL
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END

    RETURN CAST(@OperationId AS BIGINT)
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[IndexCreate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[IndexCreate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[IndexCreate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[IndexCreate](@Login NVARCHAR(MAX)
                                             ,@OperationId BIGINT) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    DECLARE @TransactionId BIGINT
               ,@TransactionIdAux BIGINT
               ,@TableName NVARCHAR(25)
               ,@Action NVARCHAR(15)
               ,@CreatedBy NVARCHAR(25)
               ,@LastRecord NVARCHAR(max)
               ,@ActualRecord NVARCHAR(max)
               ,@IsConfirmed BIT

    IF @OperationId IS NULL
            THROW 51000, 'Valor de @OperationId requerido', 1
        SELECT @TransactionId = [TransactionId]
               ,@TableName = [TableName]
               ,@Action = [Action]
               ,@CreatedBy = [CreatedBy]
               ,@LastRecord = [LastRecord]
               ,@ActualRecord = [ActualRecord]
               ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [Id] = @OperationId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Operação inexistente', 1
        IF @TableName <> 'Indexes'
            THROW 51000, 'Tabela da operação é inválida', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @Action <> 'create'
            THROW 51000, 'Ação da operação é inválida para Create', 1
        EXEC @TransactionIdAux = [dbo].[IndexValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        IF @TransactionId <> @TransactionIdAux
            THROW 51000, 'Transação da operação é inválida', 1
        DECLARE @W_Id bigint = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        DECLARE @W_TableId bigint = CAST(JSON_VALUE(@ActualRecord, '$.TableId') AS bigint)
               ,@W_Name nvarchar(50) = CAST(JSON_VALUE(@ActualRecord, '$.Name') AS nvarchar(50))
               ,@W_IsUnique bit = CAST(JSON_VALUE(@ActualRecord, '$.IsUnique') AS bit)

        INSERT INTO [dbo].[Indexes] ([Id]
                                            ,[TableId]
                                            ,[Name]
                                            ,[IsUnique]
                                            ,[CreatedAt]
                                            ,[CreatedBy])
                                      VALUES (@W_Id
                                             ,@W_TableId
                                             ,@W_Name
                                             ,@W_IsUnique
                                             ,GETDATE()
                                             ,@UserName)
        UPDATE [dbo].[Operations]
            SET [IsConfirmed] = 1
                ,[UpdatedAt] = GETDATE()
                ,[UpdatedBy] = @UserName
            WHERE [Id] = @OperationId

    RETURN @TransactionId
END
GO

