ALTER PROCEDURE [dbo].[UnicitiesRead](@Login NVARCHAR(MAX)
                                          ,@RecordFilter NVARCHAR(MAX)
                                          ,@OrderBy NVARCHAR(MAX)
                                          ,@PaddingGridLastPage BIT
                                          ,@IsActionList BIT
                                          ,@PageNumber INT OUT
                                          ,@LimitRows INT OUT
                                          ,@MaxPage INT OUT
                                          ,@ReturnValue BIGINT OUT) AS BEGIN

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @LoginId BIGINT
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @LoginId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @LoginId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    IF @RecordFilter IS NULL
            SET @RecordFilter = '{}'
        ELSE IF ISJSON(@RecordFilter) = 0
            THROW 51000, 'Valor de @RecordFilter não está no formato JSON', 1
        SET @OrderBy = TRIM(ISNULL(@OrderBy, ''))
        IF @OrderBy = ''
            SET @OrderBy = '[Id]'
        ELSE BEGIN
            SET @OrderBy = REPLACE(REPLACE(@OrderBy, '[', ''), ']', '')
            IF EXISTS(SELECT 1 
                         FROM (SELECT CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                           WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                           ELSE TRIM([value])
                                      END AS [ColumnName]
                                  FROM STRING_SPLIT(@OrderBy, ',')) AS [O]
                                      LEFT JOIN (SELECT [#1].[name] AS ColumnName
                                                    FROM [sys].[columns] [#1]
                                                        INNER JOIN [sys].[tables] [#2] ON [#1].[object_id] = [#2].[object_id]
                                                    WHERE [#2].[name] = 'Unicities') AS [T] ON [T].[ColumnName] = [O].[ColumnName]
                         WHERE [T].[ColumnName] IS NULL)
                THROW 51000, 'Nome de coluna em @OrderBy é inválido', 1
            SELECT @OrderBy = STRING_AGG('[' + TRIM(CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                                         ELSE TRIM([value])
                                                    END) + '] ' + 
                                                    CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN 'DESC'
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN 'ASC'
                                                         ELSE 'ASC'
                                                    END, ', ')
                FROM STRING_SPLIT(@OrderBy, ',')
        END

        DECLARE @TransactionId BIGINT = (SELECT MAX([Id]) FROM [dbo].[Transactions] WHERE [SessionId] = @LoginId)

        IF NOT EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [Id] = @TransactionId AND [IsConfirmed] IS NULL)
            SET @TransactionId = NULL
        SELECT [Action] AS [_]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) AS [Id]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.ColumnId1') AS bigint) AS [ColumnId1]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.ColumnId2') AS bigint) AS [ColumnId2]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsBidirectional') AS bit) AS [IsBidirectional]
            INTO [#tmpOperations]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Unicities'
                  AND [IsConfirmed] IS NULL
        CREATE UNIQUE INDEX [#tmpOperations] ON [#tmpOperations]([Id])

        DECLARE @_ NVARCHAR(MAX) = (SELECT STRING_AGG(value, ',') FROM OPENJSON(@RecordFilter, '$.Filter._'))
               ,@WhereFixed NVARCHAR(MAX) = ''
               ,@WhereFilter NVARCHAR(MAX) = ''
               ,@WhereSearch NVARCHAR(MAX) = ''
               ,@WhereUser NVARCHAR(MAX) = ''
               ,@Where NVARCHAR(MAX) = ''
               ,@sql NVARCHAR(MAX)

        DECLARE @W_F_Id bigint = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.Id') AS bigint)
               ,@W_U_Id bigint = CAST(JSON_VALUE(@RecordFilter, '$.Filter.Id') AS bigint)
               ,@W_S_Id bigint = CAST(JSON_VALUE(@RecordFilter, '$.Search.Id') AS bigint)
               ,@W_F_ColumnId1 bigint = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.ColumnId1') AS bigint)
               ,@W_U_ColumnId1 bigint = CAST(JSON_VALUE(@RecordFilter, '$.Filter.ColumnId1') AS bigint)
               ,@W_S_ColumnId1 bigint = CAST(JSON_VALUE(@RecordFilter, '$.Search.ColumnId1') AS bigint)
               ,@W_F_ColumnId2 bigint = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.ColumnId2') AS bigint)
               ,@W_U_ColumnId2 bigint = CAST(JSON_VALUE(@RecordFilter, '$.Filter.ColumnId2') AS bigint)
               ,@W_S_ColumnId2 bigint = CAST(JSON_VALUE(@RecordFilter, '$.Search.ColumnId2') AS bigint)
               ,@W_F_IsBidirectional bit = CAST(JSON_VALUE(@RecordFilter, '$.Fixed.IsBidirectional') AS bit)
               ,@W_U_IsBidirectional bit = CAST(JSON_VALUE(@RecordFilter, '$.Filter.IsBidirectional') AS bit)
               ,@W_S_IsBidirectional bit = CAST(JSON_VALUE(@RecordFilter, '$.Search.IsBidirectional') AS bit)

        IF @W_F_Id IS NOT NULL BEGIN
            IF @W_F_Id < CAST('1' AS bigint)
                THROW 51000, 'Valor de Id deve ser maior que ou igual a ''1''', 1
            SET @WhereFixed = @WhereFixed + ' AND [T].[Id] = @F_Id'
        END
        IF @W_F_ColumnId1 IS NOT NULL BEGIN
            SET @WhereFixed = @WhereFixed + ' AND [T].[ColumnId1] = @F_ColumnId1'
        END
        IF @W_F_ColumnId2 IS NOT NULL BEGIN
            SET @WhereFixed = @WhereFixed + ' AND [T].[ColumnId2] = @F_ColumnId2'
        END
        IF @W_F_IsBidirectional IS NOT NULL BEGIN
            SET @WhereFixed = @WhereFixed + ' AND [T].[IsBidirectional] = @F_IsBidirectional'
        END
        IF @_ IS NULL BEGIN
            IF @W_U_Id IS NOT NULL BEGIN
                IF @W_U_Id < CAST('1' AS bigint)
                    THROW 51000, 'Valor de Id deve ser maior que ou igual a ''1''', 1
                SET @WhereFilter = @WhereFilter + ' AND [T].[Id] = @U_Id'
            END
            IF @W_U_ColumnId1 IS NOT NULL BEGIN
                SET @WhereFilter = @WhereFilter + ' AND [T].[ColumnId1] = @U_ColumnId1'
            END
            IF @W_U_ColumnId2 IS NOT NULL BEGIN
                SET @WhereFilter = @WhereFilter + ' AND [T].[ColumnId2] = @U_ColumnId2'
            END
            IF @W_U_IsBidirectional IS NOT NULL BEGIN
                SET @WhereFilter = @WhereFilter + ' AND [T].[IsBidirectional] = @U_IsBidirectional'
            END
            IF @W_S_Id IS NOT NULL BEGIN
                IF @W_S_Id < CAST('1' AS bigint)
                    THROW 51000, 'Valor de Id deve ser maior que ou igual a ''1''', 1
                SET @WhereSearch = @WhereSearch + ' AND [T].[Id] = @S_Id'
            END
            IF @W_S_ColumnId1 IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[ColumnId1] = @S_ColumnId1'
            END
            IF @W_S_ColumnId2 IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[ColumnId2] = @S_ColumnId2'
            END
            IF @W_S_IsBidirectional IS NOT NULL BEGIN
                SET @WhereSearch = @WhereSearch + ' AND [T].[IsBidirectional] = @S_IsBidirectional'
            END
            IF @WhereFilter <> '' AND @WhereSearch <> ''
                SET @WhereUser = '(' + STUFF(@WhereFilter, 1, 5, '') + ') OR (' + STUFF(@WhereSearch, 1, 5, '') + ')'
            ELSE IF @WhereFilter <> ''
                SET @WhereUser = STUFF(@WhereFilter, 1, 5, '')
            ELSE IF @WhereSearch <> ''
                SET @WhereUser = STUFF(@WhereSearch, 1, 5, '')
        END ELSE
            SET @WhereUser = '[T].[Id] IN (' + @_ + ')'
        SET @Where = @WhereFixed
        IF @WhereUser <> ''
            SET @Where = @Where + ' AND (' + @WhereUser + ')'
        SET @sql = 'INSERT [#tmpTable]
                        SELECT ''T'' AS [_]
                              ,[T].[Id]
                            FROM [dbo].[Unicities] [T]
                                LEFT JOIN [#tmpOperations] [#] ON [#].[Id] = [T].[Id]
                            WHERE [#].[Id] IS NULL'
        SET @sql = @sql + @Where + '
                        UNION ALL
                            SELECT ''O'' AS [_]
                                  ,[T].[Id]
                                FROM [#tmpOperations] [T]
                                WHERE [T].[_] <> ''delete'''
        SET @sql = @sql + @Where
        CREATE TABLE [#tmpTable]([_] CHAR(1), [Id] bigint)
        IF @_ IS NULL
            EXEC sp_executesql @sql
                               ,N'@F_Id bigint,@U_Id bigint,@S_Id bigint
                               ,@F_ColumnId1 bigint,@U_ColumnId1 bigint,@S_ColumnId1 bigint
                               ,@F_ColumnId2 bigint,@U_ColumnId2 bigint,@S_ColumnId2 bigint
                               ,@F_IsBidirectional bit,@U_IsBidirectional bit,@S_IsBidirectional bit'
                           ,@F_Id = @W_F_Id
                           ,@U_Id = @W_U_Id
                           ,@S_Id = @W_S_Id
                           ,@F_ColumnId1 = @W_F_ColumnId1
                           ,@U_ColumnId1 = @W_U_ColumnId1
                           ,@S_ColumnId1 = @W_S_ColumnId1
                           ,@F_ColumnId2 = @W_F_ColumnId2
                           ,@U_ColumnId2 = @W_U_ColumnId2
                           ,@S_ColumnId2 = @W_S_ColumnId2
                           ,@F_IsBidirectional = @W_F_IsBidirectional
                           ,@U_IsBidirectional = @W_U_IsBidirectional
                           ,@S_IsBidirectional = @W_S_IsBidirectional
        ELSE
            EXEC sp_executesql @sql

        DECLARE @RowCount INT = @@ROWCOUNT
               ,@OffSet INT

        CREATE UNIQUE INDEX [#tmpTable] ON [#tmpTable]([Id])
        IF @RowCount = 0 OR ISNULL(@PageNumber, 0) = 0 OR ISNULL(@LimitRows, 0) <= 0 BEGIN
            SET @OffSet = 0
            SET @LimitRows = CASE WHEN @RowCount = 0 THEN 1 ELSE @RowCount END
            SET @PageNumber = 1
            SET @MaxPage = 1
        END ELSE BEGIN
            SET @MaxPage = @RowCount / @LimitRows + CASE WHEN @RowCount % @LimitRows = 0 THEN 0 ELSE 1 END
            IF ABS(@PageNumber) > @MaxPage
                SET @PageNumber = CASE WHEN @PageNumber < 0 THEN -@MaxPage ELSE @MaxPage END
            IF @PageNumber < 0
                SET @PageNumber = @MaxPage - ABS(@PageNumber) + 1
            SET @OffSet = (@PageNumber - 1) * @LimitRows
            IF @PaddingGridLastPage = 1 AND @OffSet + @LimitRows > @RowCount
                SET @OffSet = CASE WHEN @RowCount > @LimitRows THEN @RowCount - @LimitRows ELSE 0 END
        END
        SELECT TOP 0 CAST(NULL AS NVARCHAR(50)) AS [Kind]
                    ,CAST(NULL AS bigint) AS [Id]
                    ,CAST(NULL AS bigint) AS [ColumnId1]
                    ,CAST(NULL AS bigint) AS [ColumnId2]
                    ,CAST(NULL AS bit) AS [IsBidirectional]
            INTO [#result]
        SET @sql = 'INSERT #result
                        SELECT ''Unicity'' AS [Kind]
                              ,[T].[Id]
                              ,[T].[ColumnId1]
                              ,[T].[ColumnId2]
                              ,[T].[IsBidirectional]
                            FROM [#tmpTable] [#]
                                INNER JOIN [dbo].[Unicities] [T] ON [T].[Id] = [#].[Id]
                            WHERE [#].[_] = ''T''
                        UNION ALL
                            SELECT ''Unicity'' AS [Kind]
                                  ,[O].[Id]
                                  ,[O].[ColumnId1]
                                  ,[O].[ColumnId2]
                                  ,[O].[IsBidirectional]
                                FROM [#tmpTable] [#]
                                    INNER JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id]
                                WHERE [#].[_] = ''O''
                        ORDER BY ' + @OrderBy + '
                        OFFSET ' + CAST(@offset AS NVARCHAR(20)) + ' ROWS
                        FETCH NEXT ' + CAST(@LimitRows AS NVARCHAR(20)) + ' ROWS ONLY'
        EXEC sp_executesql @sql
        SELECT DISTINCT 'Column' AS [Kind]
              ,[R].[Id]
              ,[R].[TableId]
              ,[R].[Sequence]
              ,[R].[DomainId]
              ,[R].[ReferenceTableId]
              ,[R].[Name]
              ,[R].[Alias]
              ,[R].[Description]
              ,[R].[Title]
              ,[R].[Caption]
              ,[R].[Default]
              ,[R].[Minimum]
              ,[R].[Maximum]
              ,[R].[IsPrimarykey]
              ,[R].[IsAutoIncrement]
              ,[R].[IsRequired]
              ,[R].[IsListable]
              ,[R].[IsFilterable]
              ,[R].[IsEditable]
              ,[R].[IsGridable]
              ,[R].[IsEncrypted]
              ,[R].[IsInWords]
            INTO [#Columns]
            FROM [#result] [T]
                INNER JOIN [dbo].[Columns] [R] ON [R].[Id] = [T].[ColumnId1]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Columns] ON [#Columns](Id)
        SELECT DISTINCT 'Table' AS [Kind]
              ,[R].[Id]
              ,[R].[Name]
              ,[R].[Alias]
              ,[R].[Description]
              ,[R].[ParentTableId]
              ,[R].[IsLegacy]
              ,[R].[CurrentId]
            INTO [#Tables]
            FROM [#Columns] [T]
                INNER JOIN [dbo].[Tables] [R] ON [R].[Id] = [T].[TableId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Tables] ON [#Tables](Id)
        INSERT INTO [#Tables]
            SELECT DISTINCT 'Table' AS [Kind]
                  ,[R].[Id]
                  ,[R].[Name]
                  ,[R].[Alias]
                  ,[R].[Description]
                  ,[R].[ParentTableId]
                  ,[R].[IsLegacy]
                  ,[R].[CurrentId]
                FROM [#Tables] [T]
                    INNER JOIN [dbo].[Tables] [R] ON [R].[Id] = [T].[ParentTableId]
                WHERE NOT EXISTS(SELECT 1 FROM [#Tables] WHERE [Id] = [R].[Id])
                ORDER BY [R].[Id]
        INSERT INTO [#Columns]
            SELECT DISTINCT 'Column' AS [Kind]
                  ,[R].[Id]
                  ,[R].[TableId]
                  ,[R].[Sequence]
                  ,[R].[DomainId]
                  ,[R].[ReferenceTableId]
                  ,[R].[Name]
                  ,[R].[Alias]
                  ,[R].[Description]
                  ,[R].[Title]
                  ,[R].[Caption]
                  ,[R].[Default]
                  ,[R].[Minimum]
                  ,[R].[Maximum]
                  ,[R].[IsPrimarykey]
                  ,[R].[IsAutoIncrement]
                  ,[R].[IsRequired]
                  ,[R].[IsListable]
                  ,[R].[IsFilterable]
                  ,[R].[IsEditable]
                  ,[R].[IsGridable]
                  ,[R].[IsEncrypted]
                  ,[R].[IsInWords]
                FROM [#result] [T]
                    INNER JOIN [dbo].[Columns] [R] ON [R].[Id] = [T].[ColumnId2]
                WHERE NOT EXISTS(SELECT 1 FROM [#Columns] WHERE [Id] = [R].[Id])
                ORDER BY [R].[Id]
        INSERT INTO [#Tables]
            SELECT DISTINCT 'Table' AS [Kind]
                  ,[R].[Id]
                  ,[R].[Name]
                  ,[R].[Alias]
                  ,[R].[Description]
                  ,[R].[ParentTableId]
                  ,[R].[IsLegacy]
                  ,[R].[CurrentId]
                FROM [#Columns] [T]
                    INNER JOIN [dbo].[Tables] [R] ON [R].[Id] = [T].[TableId]
                WHERE NOT EXISTS(SELECT 1 FROM [#Tables] WHERE [Id] = [R].[Id])
                ORDER BY [R].[Id]
        INSERT INTO [#Tables]
            SELECT DISTINCT 'Table' AS [Kind]
                  ,[R].[Id]
                  ,[R].[Name]
                  ,[R].[Alias]
                  ,[R].[Description]
                  ,[R].[ParentTableId]
                  ,[R].[IsLegacy]
                  ,[R].[CurrentId]
                FROM [#Tables] [T]
                    INNER JOIN [dbo].[Tables] [R] ON [R].[Id] = [T].[ParentTableId]
                WHERE NOT EXISTS(SELECT 1 FROM [#Tables] WHERE [Id] = [R].[Id])
                ORDER BY [R].[Id]
        SELECT (SELECT [Kind]
                      ,[Id]
                      ,[ColumnId1]
                      ,[ColumnId2]
                      ,[IsBidirectional]
                    FROM [#result] FOR JSON PATH) AS [result]
              ,ISNULL((SELECT [Columns].* FROM [#Columns] AS [Columns] FOR JSON PATH), '[]') AS [Columns]
              ,ISNULL((SELECT [Tables].* FROM [#Tables] AS [Tables] FOR JSON PATH), '[]') AS [Tables]
        SET @ReturnValue = @RowCount

    RETURN 0
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[OperatorValidate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[OperatorValidate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[OperatorValidate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[OperatorValidate](@SessionId BIGINT
                                               ,@TransactionId BIGINT
                                               ,@UserName NVARCHAR(25)
                                               ,@Action NVARCHAR(15)
                                               ,@LastRecord NVARCHAR(max)
                                               ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED
    IF @SessionId IS NULL
            THROW 51000, 'Valor de @SessionId é requerido', 1
        IF @UserName IS NULL
            THROW 51000, 'Valor de @UserName é requerido', 1
        IF @Action IS NULL
            THROW 51000, 'Valor de @Action é requerido', 1
        IF @Action NOT IN ('create', 'update', 'delete')
            THROW 51000, 'Valor de @Action é inválido', 1
        IF @Action = 'delete' BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
        END ELSE BEGIN
            IF @ActualRecord IS NULL
                THROW 51000, 'Valor de @ActualRecord é requerido', 1
            IF ISJSON(@ActualRecord) = 0
                THROW 51000, 'Valor de @ActualRecord não está no formato JSON', 1
        END
        IF @TransactionId IS NULL
            THROW 51000, 'Valor de @TransactionId é requerido', 1
        DECLARE @IsConfirmed BIT
               ,@CreatedBy NVARCHAR(25)
               ,@IsPendingCreate BIT = 0
               ,@W_Id AS tinyint

        IF @Action = 'delete'
            SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS tinyint)
        ELSE
            SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS tinyint)

        SELECT @IsConfirmed = [IsConfirmed]
              ,@CreatedBy = [CreatedBy]
            FROM [dbo].[Transactions]
            WHERE [Id] = @TransactionId
                  AND [SessionId] = @SessionId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Transação inexistente', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Transação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1;
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @W_Id IS NULL BEGIN
            SET @ErrorMessage = 'Valor de Id em @ActualRecord é requerido.';
            THROW 51000, @ErrorMessage, 1
        END
        IF @W_Id < CAST('1' AS tinyint)
            THROW 51000, 'Valor de Id em @ActualRecord deve ser maior que ou igual a 1', 1
        IF EXISTS(SELECT 1 FROM [dbo].[Operators] WHERE [Id] = @W_Id) BEGIN
            IF @Action = 'create'
                THROW 51000, 'Chave-primária já existe em Operators', 1
        END ELSE IF @Action = 'delete' AND EXISTS(SELECT 1
                                    FROM [dbo].[Operations]
                                    WHERE [TransactionId] = @TransactionId
                                          AND [TableName] = 'Operators'
                                          AND [IsConfirmed] IS NULL
                                          AND [Action] = 'create'
                                          AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS tinyint) = @W_Id)
            SET @IsPendingCreate = 1
        ELSE IF @Action <> 'create'
            THROW 51000, 'Chave-primária não existe em Operators', 1
        IF @Action <> 'create' AND @IsPendingCreate = 0 BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
            IF NOT EXISTS(SELECT 1
                            FROM [dbo].[Operators]
                            WHERE [Id] = JSON_VALUE(@LastRecord, '$.Id')
                                  AND [Name] = JSON_VALUE(@LastRecord, '$.Name')
                                  AND [CodeSQL] = JSON_VALUE(@LastRecord, '$.CodeSQL')
                                  AND [dbo].[IS_EQUAL]([CodeJS], JSON_VALUE(@LastRecord, '$.CodeJS'), 'nvarchar') = 1)
            AND NOT EXISTS(SELECT 1
                            FROM [dbo].[Operations]
                            WHERE [TransactionId] = @TransactionId
                                  AND [TableName] = 'Operators'
                                  AND [IsConfirmed] IS NULL
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') = JSON_VALUE(@LastRecord, '$.Id')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Name') = JSON_VALUE(@LastRecord, '$.Name')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.CodeSQL') = JSON_VALUE(@LastRecord, '$.CodeSQL')
                                  AND [dbo].[IS_EQUAL](JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.CodeJS'), JSON_VALUE(@LastRecord, '$.CodeJS'), 'nvarchar') = 1)
                THROW 51000, 'Registro de Operators alterado por outro usuário', 1
        END

        IF @Action IN ('create', 'update') BEGIN

            DECLARE @W_Name nvarchar(15) = CAST(JSON_VALUE(@ActualRecord, '$.Name') AS nvarchar(15))
                   ,@W_CodeSQL nvarchar(15) = CAST(JSON_VALUE(@ActualRecord, '$.CodeSQL') AS nvarchar(15))
                   ,@W_CodeJS nvarchar(15) = CAST(JSON_VALUE(@ActualRecord, '$.CodeJS') AS nvarchar(15))

            IF @W_Name IS NULL
                THROW 51000, 'Valor de Name em @ActualRecord é requerido.', 1
            IF @W_CodeSQL IS NULL
                THROW 51000, 'Valor de CodeSQL em @ActualRecord é requerido.', 1
        END

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[OperatorPersist]
**********************************************************************************/
IF(SELECT object_id('[dbo].[OperatorPersist]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[OperatorPersist] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[OperatorPersist](@Login NVARCHAR(MAX)
                                              ,@TransactionId BIGINT
                                              ,@Action NVARCHAR(15)
                                              ,@LastRecord NVARCHAR(max)
                                              ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(255)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    DECLARE @OperationId BIGINT
               ,@CreatedBy NVARCHAR(25)
               ,@ActionAux NVARCHAR(15)
               ,@IsConfirmed BIT
           ,@W_Id tinyint

    IF @Action = 'delete'
        SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS tinyint)
    ELSE
        SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS tinyint)

    IF @Action = 'create' AND @W_Id IS NULL BEGIN
        SELECT @W_Id = CAST(JSON_VALUE([ActualRecord], '$.Id') AS tinyint)
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Operators'
                  AND [Action] = 'create'
                  AND [IsConfirmed] IS NULL
        IF @W_Id IS NULL BEGIN
            DECLARE @NewId BIGINT
    EXEC [dbo].[NewId] 'crudex', 'crudex', 'Operators', @NewId OUT
            SET @W_Id = CAST(@NewId AS tinyint)
        END
        SET @ActualRecord = JSON_MODIFY(@ActualRecord, '$.Id', @W_Id)
    END

    EXEC @TransactionId = [dbo].[OperatorValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        SELECT @OperationId = [Id]
              ,@CreatedBy = [CreatedBy]
              ,@ActionAux = [Action]
              ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Operators'
                  AND [IsConfirmed] IS NULL
                  AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS tinyint) = @W_Id
        IF @@ROWCOUNT = 0 BEGIN
            EXEC [dbo].[NewOperationId] 'crudex', 'crudex', @OperationId OUT
            INSERT INTO [dbo].[Operations] ([Id]
                                             ,[TransactionId]
                                             ,[TableName]
                                             ,[Action]
                                             ,[LastRecord]
                                             ,[ActualRecord]
                                             ,[IsConfirmed]
                                             ,[CreatedAt]
                                             ,[CreatedBy])
                                       VALUES(@OperationId
                                             ,@TransactionId
                                             ,'Operators'
                                             ,@Action
                                             ,@LastRecord
                                             ,@ActualRecord
                                             ,NULL
                                             ,GETDATE()
                                             ,@UserName)
        END ELSE IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END ELSE IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        ELSE IF @ActionAux = 'delete'
            THROW 51000, 'Registro excluído nesta transação', 1
        ELSE IF @Action = 'create' BEGIN
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END
        ELSE IF @Action = 'update' BEGIN
            IF @ActionAux = 'create'
                EXEC [dbo].[OperatorValidate] @SessionId, @TransactionId, @UserName, 'create', NULL, @ActualRecord
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END ELSE IF @ActionAux = 'create' BEGIN
            UPDATE [dbo].[Operations] 
                SET [IsConfirmed] = 0
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END ELSE BEGIN
            UPDATE [dbo].[Operations]
                SET [Action] = 'delete'
                   ,[LastRecord] = @LastRecord
                   ,[ActualRecord] = NULL
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END

    RETURN CAST(@OperationId AS BIGINT)
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[OperatorCreate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[OperatorCreate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[OperatorCreate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[OperatorCreate](@Login NVARCHAR(MAX)
                                             ,@OperationId BIGINT) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'LoginId é requerido', 1

    DECLARE @TransactionId BIGINT
               ,@TransactionIdAux BIGINT
               ,@TableName NVARCHAR(25)
               ,@Action NVARCHAR(15)
               ,@CreatedBy NVARCHAR(25)
               ,@LastRecord NVARCHAR(max)
               ,@ActualRecord NVARCHAR(max)
               ,@IsConfirmed BIT

    IF @OperationId IS NULL
            THROW 51000, 'Valor de @OperationId requerido', 1
        SELECT @TransactionId = [TransactionId]
               ,@TableName = [TableName]
               ,@Action = [Action]
               ,@CreatedBy = [CreatedBy]
               ,@LastRecord = [LastRecord]
               ,@ActualRecord = [ActualRecord]
               ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [Id] = @OperationId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Operação inexistente', 1
        IF @TableName <> 'Operators'
            THROW 51000, 'Tabela da operação é inválida', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @Action <> 'create'
            THROW 51000, 'Ação da operação é inválida para Create', 1
        EXEC @TransactionIdAux = [dbo].[OperatorValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        IF @TransactionId <> @TransactionIdAux
            THROW 51000, 'Transação da operação é inválida', 1
        DECLARE @W_Id tinyint = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS tinyint)

        DECLARE @W_Name nvarchar(15) = CAST(JSON_VALUE(@ActualRecord, '$.Name') AS nvarchar(15))
               ,@W_CodeSQL nvarchar(15) = CAST(JSON_VALUE(@ActualRecord, '$.CodeSQL') AS nvarchar(15))
               ,@W_CodeJS nvarchar(15) = CAST(JSON_VALUE(@ActualRecord, '$.CodeJS') AS nvarchar(15))

        INSERT INTO [dbo].[Operators] ([Id]
                                            ,[Name]
                                            ,[CodeSQL]
                                            ,[CodeJS]
                                            ,[CreatedAt]
                                            ,[CreatedBy])
                                      VALUES (@W_Id
                                             ,@W_Name
                                             ,@W_CodeSQL
                                             ,@W_CodeJS
                                             ,GETDATE()
                                             ,@UserName)
        UPDATE [dbo].[Operations]
            SET [IsConfirmed] = 1
                ,[UpdatedAt] = GETDATE()
                ,[UpdatedBy] = @UserName
            WHERE [Id] = @OperationId

    RETURN @TransactionId
END
GO

